INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(91,'2026-02-25',NULL,'Miércoles de la I Semana de Cuaresma','Lectura de la profecía de Jonás (3,1-10)',replace('EL Señor dirigió la palabra a Jonás:\n\n«Ponte en marcha y ve a la gran ciudad de Nínive; allí les anunciarás el mensaje que yo te comunicaré».\n\nJonás se puso en marcha hacia Nínive, siguiendo la orden del Señor. Nínive era una ciudad inmensa; hacían falta tres días para recorrerla. Jonás empezó a recorrer la ciudad el primer día, proclamando:\n\n«Dentro de cuarenta días, Nínive será arrasada».\n\nLos ninivitas creyeron en Dios, proclamaron un ayuno y se vistieron con rudo sayal, desde el más importante al menor.\n\nLa noticia llegó a oídos del rey de Nínive, que se levantó de su trono, se despojó del manto real, se cubrió con rudo sayal y se sentó sobre el polvo. Después ordenó proclamar en Nínive este anuncio de parte del rey y de sus ministros:\n\n«Que hombres y animales, ganado mayor y menor no coman nada; que no pasten ni beban agua. Que hombres y animales se cubran con rudo sayal e invoquen a Dios con ardor. Que cada cual se convierta de su mal camino y abandone la violencia. ¡Quién sabe si Dios cambiará y se compadecerá, se arrepentirá de su violenta ira y no nos destruirá!».\n\nVio Dios su comportamiento, cómo habían abandonado el mal camino, y se arrepintió de la desgracia que había determinado enviarles. Así que no la ejecutó.','\n',char(10)),'Sal 50,3-4.12-13.18-19',replace('R/. Un corazón quebrantado y humillado,\n\ntú, Dios mío, no lo desprecias\nV/. Misericordia, Dios mío, por tu bondad,\n\npor tu inmensa compasión borra mi culpa;\n\nlava del todo mi delito,\n\nlimpia mi pecado. R/.\nV/. Oh, Dios, crea en mí un corazón puro,\n\nrenuévame por dentro con espíritu firme.\n\nNo me arrojes lejos de tu rostro,\n\nno me quites tu santo espíritu. R/.\nV/. Los sacrificios no te satisfacen:\n\nsi te ofreciera un holocausto, no lo querrías.\n\nEl sacrificio agradable a Dios\n\nes un espíritu quebrantado;\n\nun corazón quebrantado y humillado,\n\ntú, oh, Dios, tú no lo desprecias. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio segun san Lucas (11,29-32)',replace('EN aquel tiempo, la gente se apiñaba alrededor de Jesús,\n\ny él se puso a decirles:\n\n«Esta generación es una generación perversa. Pide un signo, pero no se le dará más signo que el signo de Jonás. Pues como Jonás fue un signo para los habitantes de Nínive, lo mismo será el Hijo del hombre para esta generación.\n\nLa reina del Sur se levantará en el juicio contra los hombres de esta generación y hará que los condenen, porque ella vino desde los confines de la tierra para escuchar la sabiduría de Salomón, y aquí hay uno que es más que Salomón.\n\nLos hombres de Nínive se alzarán en el juicio contra esta generación y harán que la condenen; porque ellos se convirtieron con la proclamación de Jonás, y aquí hay uno que es más que Jonás».','\n',char(10)),'2026-03-01 05:04:07','2026-03-01 05:04:07');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(92,'2026-02-27',NULL,'Viernes de la I Semana de Cuaresma','Lectura de la profecía de Ezequiel (18,21-28)',replace('ESTO dice el Señor Dios:\n\n«Si el malvado se convierte de todos los pecados cometidos y observa todos mis preceptos, practica el derecho y la justicia, ciertamente vivirá y no morirá. No se tendrán en cuenta los delitos cometidos; por la justicia que ha practicado, vivirá. ¿Acaso quiero yo la muerte del malvado —oráculo del Señor Dios—, y no que se convierta de su conducta y viva?\n\nSi el inocente se aparta de su inocencia y comete maldades, como las acciones detestables del malvado, ¿acaso podrá vivir? No se tendrán en cuenta sus obras justas. Por el mal que hizo y por el pecado cometido, morirá.\n\nInsistis: No es justo el proceder del Señor. Escuchad, casa de Israel: ¿Es injusto mi proceder? ¿No es más bien vuestro proceder el que es injusto?\n\nCuando el inocente se aparta de su inocencia, comete la maldad y muere, muere por la maldad que cometió. Y cuando el malvado se convierte de la maldad que hizo y practica el derecho y la justicia, él salva su propia vida. Si recapacita y se convierte de los delitos cometidos, ciertamente vivirá y no morirá».','\n',char(10)),'Sal 129,1-2.3-4.5-7',replace('R/. Si llevas cuenta de los delitos, Señor,\n\n¿quién podrá resistir?\nV/. Desde lo hondo a ti grito, Señor;\n\nSeñor, escucha mi voz;\n\nestén tus oídos atentos\n\na la voz de mi súplica. R/.\nV/. Si llevas cuenta de los delitos, Señor,\n\n¿quién podrá resistir?\n\nPero de ti procede el perdón,\n\ny así infundes temor. R/.\nV/. Mi alma espera en el Señor,\n\nespera en su palabra;\n\nmi alma aguarda al Señor,\n\nmás que el centinela la aurora.\n\nAguarde Israel al Señor,\n\ncomo el centinela la aurora. R/.\nV/. Porque del Señor viene la misericordia,\n\nla redención copiosa;\n\ny el redimirá a Israel\n\nde todos sus delitos. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Mateo (5,20-26)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Si vuestra justicia no es mayor que la de los escribas y fariseos, no entraréis en el reino de los cielos.\n\nHabéis oído que se dijo a los antiguos: “No matarás”, y el que mate será reo de juicio. Pero yo os digo: todo el que se deja llevar de la cólera contra su hermano será procesado. Y si uno llama a su hermano “imbécil” tendrá que comparecer ante el Sanedrín, y si lo llama “necio”, merece la condena de la “gehena” del fuego.\n\nPor tanto, si cuando vas a presentar tu ofrenda sobre el altar, te acuerdas allí mismo de que tu hermano tiene quejas contra ti, deja allí tu ofrenda ante el altar y vete primero a reconciliarte con tu hermano, y entonces vuelve a presentar tu ofrenda.\n\nCon el que te pone pleito procura arreglarte enseguida, mientras vais todavía de camino, no sea que te entregue al juez y el juez al alguacil, y te metan en la cárcel. En verdad te digo que no saldrás de allí hasta que hayas pagado el último céntimo».','\n',char(10)),'2026-03-01 05:04:17','2026-03-01 05:04:17');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(93,'2026-02-28',NULL,'Sábado de la I Semana de Cuaresma','Lectura del libro del Deuteronomio (26,16-19)',replace('MOISÉS habló al pueblo, diciendo:\n\n«Hoy el Señor, tu Dios, te manda que cumplas estos mandatos y decretos. Acátalos y cúmplelos con todo tu corazón y con toda tu alma.\n\nHoy has elegido al Señor para que él sea tu Dios y tú vayas por sus caminos, observes sus mandatos, preceptos y decretos, y escuches su voz. Y el Señor te ha elegido para que seas su propio pueblo, como te prometió, y observes todos sus preceptos.\n\nÉl te elevará en gloria, nombre y esplendor, por encima de todas las naciones que ha hecho, y serás el pueblo santo del Señor, tu Dios, como prometió».','\n',char(10)),'Sal 118,1-2.4-5.7-8',replace('R/. Dichoso el que camina en la voluntad del Señor\nV/. Dichoso el que, con vida intachable,\n\ncamina en la ley del Señor;\n\ndichoso el que, guardando sus preceptos,\n\nlo busca de todo corazón. R/.\nV/. Tú promulgas tus mandatos\n\npara que se observen exactamente.\n\nOjalá esté firme mi camino,\n\npara cumplir tus decretos. R/.\nV/. Te alabaré con sincero corazón\n\ncuando aprenda tus justos mandamientos.\n\nQuiero guardar tus decretos exactamente,\n\ntú no me abandones. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Mateo (5,43-48)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Habéis oído que se dijo: “Amarás a tu prójimo’ y aborrecerás a tu enemigo”.\n\nPero yo os digo: amad a vuestros enemigos y rezad por los que os persiguen, para que seáis hijos de vuestro Padre celestial, que hace salir su sol sobre malos y buenos, y manda la lluvia a justos e injustos.\n\nPorque, si amáis a los que os aman, ¿qué premio tendréis? ¿No hacen lo mismo también los publicanos? Y, si saludáis solo a vuestros hermanos, ¿qué hacéis de extraordinario? ¿No hacen lo mismo también los gentiles? Por tanto, sed perfectos, como vuestro Padre celestial es perfecto».','\n',char(10)),'2026-03-01 05:04:24','2026-03-01 05:04:24');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(94,'2026-03-02',NULL,'Lunes de la II Semana de Cuaresma','Lectura de la profecía de Daniel (9,4b-10)',replace('¡AY, mi Señor, Dios grande y terrible, que guarda la alianza y es leal con los que lo aman y cumplen sus mandamientos!\n\nHemos pecado, hemos cometido crímenes y delitos, nos hemos rebelado apartándonos de tus mandatos y preceptos. No hicimos caso a tus siervos los profetas, que hablaban en tu nombre a nuestros reyes, a nuestros príncipes, a nuestros padres y a todo el pueblo de la tierra.\n\nTú, mi Señor, tienes razón y a nosotros nos abruma la vergüenza, tal como sucede hoy a los hombres de Judá, a los habitantes de Jerusalén y a todo Israel, a los de cerca y a los de lejos, en todos los países por donde los dispersaste a causa de los delitos que cometieron contra ti.\n\nSeñor, nos abruma la vergüenza: a nuestros reyes, príncipes y padres, porque hemos pecado contra ti.\n\nPero, mi Señor, nuestro Dios, es compasivo y perdona, aunque nos hemos rebelado contra él. No obedecimos la voz del Señor, nuestro Dios, siguiendo las normas que nos daba por medio de sus siervos, los profetas.','\n',char(10)),'Sal 78,8.9.11.13',replace('R/. Señor, no nos trates\n\ncomo merecen nuestros pecados\nV/. No recuerdes contra nosotros las culpas de nuestros padres;\n\nque tu compasión nos alcance pronto,\n\npues estamos agotados. R/.\nV/. Socórrenos, Dios, Salvador nuestro,\n\npor el honor de tu nombre;\n\nlíbranos y perdona nuestros pecados\n\na causa de tu nombre. R/.\nV/. Llegue a tu presencia el gemido del cautivo:\n\ncon tu brazo poderoso, salva a los condenados a muerte. R/.\nV/. Nosotros, pueblo, ovejas de tu rebaño,\n\nte daremos gracias siempre,\n\ncantaremos tus alabanzas de generación en generación. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Lucas (6,36-38)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Sed misericordiosos como vuestro Padre es misericordioso; no juzguéis, y no seréis juzgados; no condenéis, y no seréis condenados; perdonad, y seréis perdonados; dad, y se os dará: os verterán una medida generosa, colmada, remecida, rebosante, pues con la medida con que midiereis se os medirá a vosotros».','\n',char(10)),'2026-03-01 05:04:35','2026-03-01 05:04:35');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(95,'2026-03-17',NULL,'Martes de la IV Semana de Cuaresma','Lectura de la profecía de Ezequiel (47,1-9.12)',replace('EN aquellos días, el ángel me hizo volver a la entrada del templo del Señor.\n\nDe debajo del umbral del templo corría agua hacia el este —el templo miraba al este—. El agua bajaba por el lado derecho del templo, al sur del altar.\n\nMe hizo salir por el pórtico septentrional y me llevó por fuera hasta el pórtico exterior que mira al este. El agua corría por el lado derecho.\n\nEl hombre que llevaba el cordel en la mano salió hacia el este, midió quinientos metros y me hizo atravesar el agua, que me llegaba hasta los tobillos. Midió otros quinientos metros y me hizo atravesar el agua, que me llegaba hasta las rodillas. Midió todavía otros quinientos metros y me hizo atravesar el agua, que me llegaba hasta la cintura. Midió otros quinientos metros: era ya un torrente que no se podía vadear, sino cruzar a nado.\n\nEntonces me dijo:\n\n    «¿Has visto, hijo de hombre?»,\n\nDespués me condujo por la ribera del torrente.\n\nAl volver vi en ambas riberas del torrente una gran arboleda. Me dijo:\n\n    «Estas aguas fluyen hacia la zona oriental, descienden hacia la estepa y desembocan en el mar de la Sal, Cuando hayan entrado en él, sus aguas serán saneadas. Todo ser viviente que se agita, allí donde desemboque la corriente, tendrá vida; y habrá peces en abundancia. Porque apenas estas aguas hayan llegado hasta allí, habrán saneado el mar y habrá vida allí donde llegue el torrente.\n\nEn ambas riberas del torrente crecerá toda clase de árboles frutales; no se marchitarán sus hojas ni se acabarán sus frutos; darán nuevos frutos cada mes, porque las aguas del torrente fluyen del santuario; su fruto será comestible y sus hojas medicinales».','\n',char(10)),'Sal 45,2-3.5-6.8-9',replace('R/. El Señor de los ejércitos está con nosotros,\n\nnuestro alcázar es el Dios de Jacob\nV/.   Dios es nuestro refugio y nuestra fuerza,\n\n                poderoso defensor en el peligro.\n\n                Por eso no tememos aunque tiemble la tierra,\n\n                y los montes se desplomen en el mar.   R/.\nV/.   Un río y sus canales alegran la ciudad de Dios,\n\n                el Altísimo consagra su morada.\n\n                Teniendo a Dios en medio, no vacila;\n\n                Dios la socorre al despuntar la aurora.   R/.\nV/.   El Señor del universo está con nosotros,\n\n                nuestro alcázar es el Dios de Jacob.\n\n                Venid a ver las obras del Señor,\n\n                las maravillas que hace en la tierra.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (5,1-16)',replace('SE celebraba una fiesta de los judíos, y Jesús subió a Jerusalén.\n\nHay en Jerusalén, junto a la Puerta de las Ovejas, una piscina que llaman en hebreo Betesda. Esta tiene cinco soportales, y allí estaban echados muchos enfermos, ciegos, cojos, paralíticos.\n\nEstaba también allí un hombre que llevaba treinta y ocho años enfermo.\n\nJesús, al verlo echado, y sabiendo que ya llevaba mucho tiempo, le dice:\n\n    «¿Quieres quedar sano?».\n\nEl enfermo le contestó:\n\n    «Señor, no tengo a nadie que me meta en la piscina cuando se remueve el agua; para cuando llego yo, otro se me ha adelantado».\n\nJesús le dice:\n\n    «Levántate, toma tu camilla y echa a andar».\n\nY al momento el hombre quedó sano, tomó su camilla y echó a andar.\n\nAquel día era sábado, y los judíos dijeron al hombre que había quedado sano:\n\n    «Hoy es sábado, y no se puede llevar la camilla».\n\nÉl les contestó:\n\n    «El que me ha curado es quien me ha dicho: “Toma tu camilla y echa a andar”».\n\nEllos le preguntaron:\n\n    «¿Quién es el que te ha dicho que tomes la camilla y eches a andar?».\n\nPero el que había quedado sano no sabía quién era, porque Jesús, a causa del gentío que había en aquel sitio, se había alejado.\n\nMás tarde lo encuentra Jesús en el templo y le dice:\n\n    «Mira, has quedado sano; no peques más, no sea que te ocurra algo peor».\n\nSe marchó aquel hombre y dijo a los judíos que era Jesús quien lo había sanado.\n\nPor esto los judíos perseguían a Jesús, porque hacía tales cosas en sábado.','\n',char(10)),'2026-03-17 00:25:52','2026-03-17 00:25:52');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(96,'2026-03-18',NULL,'Miércoles de la IV Semana de Cuaresma','Lectura del libro de Isaías (49,8-15)',replace('ESTO dice el Señor:\n\n«En tiempo de gracia te he respondido,\n\nen día propicio te he auxiliado;\n\nte he defendido y constituido alianza del pueblo,\n\npara restaurar el país,\n\npara repartir heredades desoladas,\n\npara decir a los cautivos: “Salid”,\n\na los que están en tinieblas: “Venid a la luz”.\n\nAun por los caminos pastarán,\n\n     tendrán praderas en todas las dunas;\n\n     no pasarán hambre ni sed,\n\n     no les hará daño el bochorno ni el sol;\n\n     porque los conduce el compasivo\n\n     y los guía a manantiales de agua.\n\nConvertiré mis montes en caminos,\n\n     y mis senderos se nivelarán.\n\nMiradlos venir de lejos;\n\n     miradlos, del Norte y del Poniente,\n\n     y los otros de la tierra de Sin.\n\nExulta, cielo; alégrate, tierra;\n\n     romped a cantar, montañas,\n\n     porque el Señor consuela a su pueblo\n\n     y se compadece de los desamparados».\n\nSion decía: «Me ha abandonado el Señor,\n\n     mi dueño me ha olvidado».\n\n¿Puede una madre olvidar al niño que amamanta,\n\n     no tener compasión del hijo de sus entrañas?\n\n     Pues, aunque ella se olvidara, yo no te olvidaré.','\n',char(10)),'Sal 144,8-9.13',replace('R/. El Señor es clemente y misericordioso\nV/.   El Señor es clemente y misericordioso,\n\n                lento a la cólera y rico en piedad;\n\n                el Señor es bueno con todos,\n\n                es cariñoso con todas sus criaturas.   R/.\nV/.   El Señor es fiel a sus palabras,\n\n                bondadoso en todas sus acciones.\n\n                El Señor sostiene a los que van a caer,\n\n                endereza a los que ya se doblan.   R/.\nV/.   El Señor es justo en todos sus caminos,\n\n                es bondadoso en todas sus acciones.\n\n                Cerca está el Señor de los que lo invocan,\n\n                de los que lo invocan sinceramente.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (5,17-30)',replace('EN aquel tiempo, Jesús dijo a los judíos:\n\n    «Mi Padre sigue actuando, y yo también actúo».\n\nPor eso los judíos tenían más ganas de matarlo: porque no solo quebrantaba el sábado, sino también llamaba a Dios Padre suyo, haciéndose igual a Dios.\n\nJesús tomó la palabra y les dijo:\n\n    «En verdad, en verdad os digo: el Hijo no puede hacer nada por su cuenta sino lo que viere hacer al Padre. Lo que hace este, eso mismo hace también el Hijo, pues el Padre ama al Hijo y le muestra todo lo que él hace, y le mostrará obras mayores que esta, para vuestro asombro.\n\nLo mismo que el Padre resucita a los muertos y les da vida, así también el Hijo da vida a los que quiere.\n\nPorque el Padre no juzga a nadie, sino que ha confiado al Hijo todo el juicio, para que todos honren al Hijo como honran al Padre. El que no honra al Hijo, no honra al Padre que lo envió.\n\nEn verdad, en verdad os digo: quien escucha mi palabra y cree al que me envió posee la vida eterna y no incurre en juicio, sino que ha pasado ya de la muerte a la vida.\n\nEn verdad, en verdad os digo: llega la hora, y ya está aquí, en que los muertos oirán la voz del Hijo de Dios, y los que hayan oído vivirán.\n\nPorque, igual que el Padre tiene vida en sí mismo, así ha dado también al Hijo tener vida en sí mismo. Y le ha dado potestad de juzgar, porque es el Hijo del hombre.\n\nNo os sorprenda esto, porque viene la hora en que los que están en el sepulcro oirán su voz: los que hayan hecho el bien saldrán a una resurrección de vida; los que hayan hecho el mal, a una resurrección de juicio.\n\nYo no puedo hacer nada por mí mismo; según le oigo, juzgo, y mi juicio es justo, porque no busco mi voluntad, sino la voluntad del que me envió».','\n',char(10)),'2026-03-17 00:26:00','2026-03-17 00:26:00');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(97,'2026-03-19',NULL,'San José, esposo de la Bienaventurada Virgen María','Lectura del segundo libro de Samuel (7,4-5a.12-14a.16)',replace('En aquellos días, recibió Natán la siguiente palabra del Señor:\n\n&#8211; «Ve y dile a mi siervo David: «Esto dice el Señor: Cuando tus días se hayan cumplido y te acuestes con tus padres, afirmaré después de ti la descendencia que saldrá de tus entrañas, y consolidaré su realeza. El cons¬truirá una casa para mi nombre, y yo consolidaré el trono de su realeza para siempre. Yo seré para él padre, y él será para mí hijo. Tu casa y tu reino durarán por siempre en mi presencia; tu trono permanecerá por siempre.» ».','\n',char(10)),'Sal 88,2-3.4-5.27.29',replace('R/. Su linaje será perpetuo\nCantaré eternamente las misericordias del Señor,\n\nanunciaré tu fidelidad por todas las edades.\n\nPorque dije: «Tu misericordia es un edificio eterno,\n\nmás que el cielo has afianzado tu fidelidad.» R.\nSellé una alianza con mi elegido,\n\njurando a David, mi siervo:\n\n«Te fundaré un linaje perpetuo,\n\nedificaré tu trono para todas las edades.» R.\nEl me invocará: «Tú eres mi padre, mi Dios,\n\nmi Roca salvadora.»\n\nLe mantendré eternamente mi favor,\n\ny mi alianza con él será estable. R.','\n',char(10)),'Lectura de la carta  del apóstol san Pablo a los Romanos (4,13.16-18)',replace('Hermanos:\n\nNo fue la observancia de la Ley, sino la justificación obtenida por la fe, la que obtuvo para Abrahán y su\n\ndescendencia la promesa de heredar el mundo.\n\nPor eso, como todo depende de la fe, todo es gracia; así, la promesaestáaseguradapara todala descendencia, no solamente para la descendencia legal, sino también para la que nace de la fe de Abrahán, que es padre de todos nosotros. Así, dice la Escritura: «Te hago padre de muchos pueblos.»\n\nAl encontrarse con el Dios que da vida a los muertos y llama a la existencia lo que, no existe, Abrahán\n\ncreyó.\n\nApoyado en la esperanza, creyó, contra toda esperanza, que llegaría a ser padre de muchas naciones, según lo que se le había dicho: «Así será tu descendencia.»','\n',char(10)),'Lectura del santo evangelio según san Mateo (1,16.18-21.24a)',replace('Jacob engendró a José, el esposo de María, de la cual nació Jesús, llamado Cristo.\n\nEl nacimiento de Jesucristo fue de esta manera:\n\nMaría, su madre, estaba desposada con José y, antes de vivir juntos, resultó que ella esperaba un hijo por obra del Espíritu Santo.\n\nJosé, su esposo, que era justo y no quería denunciarla, decidió repudiarla en secreto. Pero, apenas había tomado esta resolución, se le apareció en sueños un ángel del Señor que le dijo:\n\n-«José, hijo de David, no tengas reparo en llevarte a María, tu mujer, porque la criatura que hay en ella viene del Espíritu Santo. Dará a luz un hijo, y tú le pondrás por nombre Jesús, porque él salvará a su pueblo de los pecados.»\n\nCuando José se despertó, hizo lo que le había mandado el ángel del Señor.','\n',char(10)),'2026-03-17 00:26:08','2026-03-17 00:26:08');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(98,'2026-03-20',NULL,'Viernes de la IV Semana de Cuaresma','Lectura del libro de la Sabiduría (2,1a.12-22)',replace('SE decían los impíos, razonando equivocadamente:\n\n«Acechemos al justo, que nos resulta fastidioso:\n\nse opone a nuestro modo de actuar,\n\nnos reprocha las faltas contra la ley\n\ny nos reprende contra la educación recibida;\n\npresume de conocer a Dios\n\ny se llama a sí mismo hijo de Dios.\n\nEs un reproche contra nuestros criterios,\n\n     su sola presencia nos resulta insoportable.\n\nLleva una vida distinta de todos los demás\n\n     y va por caminos diferentes.\n\nNos considera moneda falsa\n\n     y nos esquiva como a impuros.\n\nProclama dichoso el destino de los justos,\n\n     y presume de tener por padre a Dios.\n\nVeamos si es verdad Jo que dice,\n\n     comprobando cómo es su muerte.\n\nSi el justo es hijo de Dios, él lo auxiliará\n\n     y lo librará de las manos de sus enemigos.\n\nLo someteremos a ultrajes y torturas,\n\n     para conocer su temple y comprobar su resistencia.\n\nLo condenaremos a muerte ignominiosa,\n\n     pues, según dice, Dios lo salvará».\n\nAsí discurren, pero se equivocan,\n\n     pues los ciega su maldad.\n\nDesconocen los misterios de Dios,\n\n     no esperan el premio de la santidad,\n\n     ni creen en la recompensa de una vida intachable.','\n',char(10)),'Sal 33,17-18.19-20,21.23',replace('R/. El Señor está cerca de los atribulados\nV/.   El Señor se enfrenta con los malhechores,\n\n                para borrar de la tierra su memoria.\n\n                Cuando uno grita, el Señor lo escucha\n\n                y lo libra de sus angustias.   R/.\nV/.   El Señor está cerca de los atribulados,\n\n                salva a los abatidos.\n\n                Aunque el justo sufra muchos males,\n\n                de todos lo libra el Señor.   R/.\nV/.   Él cuida de todos sus huesos,\n\n                y ni uno solo se quebrará.\n\n                El Señor redime a sus siervos,\n\n                no será castigado quien se acoge a él.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (7,1-2.10.25-30)',replace('EN aquel tiempo, recorría Jesús Galilea, pues no quería andar por Judea porque los judíos trataban de matarlo. Se acercaba la fiesta judía de las Tiendas.\n\nUna vez que sus hermanos se hubieron marchado a la fiesta, entonces subió él también, no abiertamente, sino a escondidas.\n\nEntonces algunos que eran de Jerusalén dijeron:\n\n    «¿No es este el que intentan matar? Pues mirad cómo habla abiertamente, y no le dicen nada. ¿Será que los jefes se han convencido de que este es el Mesías? Pero este sabemos de dónde viene, mientras que el Mesías, cuando llegue, nadie sabrá de dónde viene».\n\nEntonces Jesús, mientras enseñaba en el templo, gritó:\n\n    «A mí me conocéis, y conocéis de dónde vengo. Sin embargo, yo no vengo por mi cuenta, sino que el Verdadero es el que me envía; a ese vosotros no lo conocéis; yo lo conozco, porque procedo de él y él me ha enviado».\n\nEntonces intentaban agarrarlo; pero nadie le pudo echar mano, porque todavía no había llegado su hora.','\n',char(10)),'2026-03-17 00:26:15','2026-03-17 00:26:15');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(102,'2026-03-16',NULL,'Lunes de la IV Semana de Cuaresma','Lectura del libro de Isaías (65,17-21)',replace('ESTO dice el Señor:\n\n«Mirad: voy a crear un nuevo cielo\n\ny una nueva tierra:\n\nde las cosas pasadas\n\nni habrá recuerdo ni vendrá pensamiento.\n\nRegocijaos, alegraos por siempre\n\n     por lo que voy a crear:\n\n     yo creo a Jerusalén “alegría”,\n\n     y a su pueblo, “júbilo”.\n\nMe alegraré por Jerusalén\n\n     y me regocijaré con mi pueblo,\n\n     ya no se oirá en ella ni llanto ni gemido;\n\n     ya no habrá allí niño\n\n     que dure pocos días,\n\n     ni adulto que no colme sus años,\n\n     pues será joven quien muera a los cien años,\n\n     y quien no los alcance se tendrá por maldito.\n\nConstruirán casas y las habitarán,\n\n     plantarán viñas y comerán los frutos».','\n',char(10)),'Sal 29,2.4.5-6.11-12',replace('R/. Te ensalzaré, Señor, porque me has librado\nV/.   Te ensalzaré, Señor, porque me has librado\n\n                y no has dejado que mis enemigos se rían de mí.\n\n                Señor, sacaste mi vida del abismo,\n\n                me hiciste revivir cuando bajaba a la fosa.   R/.\nV/.   Tañed para el Señor, fieles suyos,\n\n                celebrad el recuerdo de su nombre santo;\n\n                su cólera dura un instante;\n\n                su bondad, de por vida;\n\n                al atardecer nos visita el llanto;\n\n                por la mañana, el júbilo.   R/.\nV/.   Escucha, Señor, y ten piedad de mí;\n\n                Señor, socórreme.\n\n                Cambiaste mi luto en danzas.\n\n                Señor, Dios mío, te daré gracias por siempre.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (4,43-54)',replace('EN aquel tiempo, salió Jesús de Samaría para Galilea. Jesús mismo había atestiguado:\n\n    «Un profeta no es estimado en su propia patria».\n\nCuando llegó a Galilea, los galileos lo recibieron bien, porque habían visto todo lo que había hecho en Jerusalén durante la fiesta, pues también ellos habían ido a la fiesta.\n\nFue Jesús otra vez a Caná de Galilea, donde había convertido el agua en vino.\n\nHabía un funcionario real que tenía un hijo enfermo en Cafarnaún. Oyendo que Jesús había llegado de Judea a Galilea, fue a verlo, y le pedía que bajase a curar a su hijo que estaba muriéndose.\n\nJesús le dijo:\n\n    «Si no veis signos y prodigios, no creéis».\n\nEl funcionario insiste:\n\n    «Señor, baja antes de que se muera mi niño».\n\nJesús le contesta:\n\n    «Anda, tu hijo vive».\n\nEl hombre creyó en la palabra de Jesús y se puso en camino. Iba ya bajando, cuando sus criados vinieron a su encuentro diciéndole que su hijo vivía. Él les preguntó a qué hora había empezado la mejoría. Y le contestaron:\n\n    «Ayer a la hora séptima lo dejó la fiebre».\n\nEl padre cayó en la cuenta de que esa era la hora en que Jesús le había dicho: «Tu hijo vive». Y creyó él con toda su familia. Este segundo signo lo hizo Jesús al llegar de Judea a Galilea.','\n',char(10)),'2026-03-17 00:26:55','2026-03-17 00:26:55');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(103,'2026-03-25',NULL,'La Anunciación del Señor','Lectura del libro de Isaías (7,10-14;8,10)',replace('En aquel tiempo, el Señor habló a Acaz: «Pide una señal al Señor, tu Dios: en lo hondo del abismo o en lo alto del cielo.»\n\nRespondió Acaz: «No la pido, no quiero tentar al Señor.»\n\nEntonces dijo Dios: «Escucha, casa de David: ¿No os basta cansar a los hombres, que cansáis incluso a mi Dios? Pues el Señor, por su cuenta, os dará una señal: Mirad: la virgen está encinta y da a luz un hijo, y le pondrá por nombre Emmanuel, que significa «Dios-con-nosotros».»','\n',char(10)),'Sal 39,7-8',replace('R/. Aquí estoy, Señor, para hacer tu voluntad\nTú no quieres sacrificios ni ofrendas,\n\ny, en cambio, me abriste el oído;\n\nno pides sacrificio expiatorio,\n\nentonces yo digo: «Aquí estoy.» R/.\n«Como está escrito en mi libro\n\npara hacer tu voluntad.»\n\nDios mío, lo quiero,\n\ny llevo tu ley en las entrañas. R/.\nHe proclamado tu salvación\n\nante la gran asamblea;\n\nno he cerrado los labios:\n\nSeñor, tú lo sabes. R/.\nNo me he guardado en el pecho tu defensa,\n\nhe contado tu fidelidad y tu salvación,\n\nno he negado tu misericordia\n\ny tu lealtad ante la gran asamblea. R/.','\n',char(10)),'Lectura de la carta a los Hebreos (10,4-10)','Es imposible que la sangre de los toros y de los machos cabríos quite los pecados. Por eso, cuando Cristo entró en el mundo dijo: «Tú no quieres sacrificios ni ofrendas, pero me has preparado un cuerpo; no aceptas holocaustos ni víctimas expiatorias. Entonces yo dije lo que está escrito en el libro: «Aquí estoy, oh Dios, para hacer tu voluntad.»» Primero dice: «No quieres ni aceptas sacrificios ni ofrendas, holocaustos ni victimas expiatorias», que se ofrecen según la Ley. Después añade: «Aquí estoy yo para hacer tu voluntad.» Niega lo primero, para afirmar lo segundo. Y conforme a esa voluntad todos quedamos santificados por la oblación del cuerpo de Jesucristo, hecha una vez para siempre.','Lectura del santo evangelio según san Lucas (1,26-38)',NULL,'2026-03-17 01:48:15','2026-03-17 01:48:15');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(105,'2026-03-24',NULL,'Martes de la V Semana de Cuaresma','Lectura del libro de los Números (21,4-9)',replace('EN aquellos días, desde el monte Hor se encaminaron los hebreos hacia el mar Rojo, rodeando el territorio de Edón.\n\nEl pueblo se cansó de caminar y habló contra Dios y contra Moisés:\n\n    «¿Por qué nos has sacado de Egipto para morir en el desierto? No tenemos ni pan ni agua, y nos da náuseas ese pan sin sustancia».\n\nEl Señor envió contra el pueblo serpientes abrasadoras, que los mordían, y murieron muchos de Israel.\n\nEntonces el pueblo acudió a Moisés, diciendo:\n\n    «Hemos pecado hablando contra el Señor y contra ti; reza al Señor para que aparte de nosotros las serpientes».\n\nMoisés rezó al Señor por el pueblo y el Señor le respondió:\n\n    «Haz una serpiente abrasadora y colócala en un estandarte: los mordidos de serpientes quedarán sanos al mirarla».\n\nMoisés hizo una serpiente de bronce y la colocó en un estandarte. Cuando una serpiente mordía a alguien, este miraba a la serpiente de bronce y salvaba la vida.','\n',char(10)),'Sal 101,2-3.16-18.19-21',replace('R/. Señor, escucha mi oración,\n\nque mi grito llegue hasta ti\nV/.   Señor, escucha mi oración,\n\n                que mi grito llegue hasta ti;\n\n                no me escondas tu rostro\n\n                el día de la desgracia.\n\n                Inclina tu oído hacia mí;\n\n                cuando te invoco,\n\n                escúchame enseguida.   R/.\nV/.   Los gentiles temerán tu nombre,\n\n                los reyes del mundo, tu gloria.\n\n                Cuando el Señor reconstruya Sión\n\n                y aparezca en su gloria,\n\n                y se vuelva a las súplicas de los indefensos,\n\n                y no desprecie sus peticiones.   R/.\nV/.   Quede esto escrito para la generación futura,\n\n                y el pueblo que será creado alabará al Señor.\n\n                Que el Señor ha mirado desde su excelso santuario,\n\n                desde el cielo se ha fijado en la tierra,\n\n                para escuchar los gemidos de los cautivos\n\n                y librar a los condenados a muerte.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (8,21-30)',replace('EN aquel tiempo, dijo Jesús a los fariseos:\n\n    «Yo me voy y me buscaréis, y moriréis por vuestro pecado. Donde yo voy no podéis venir vosotros».\n\nY los judíos comentaban:\n\n    «¿Será que va a suicidarse, y por eso dice: “Donde yo voy no podéis venir vosotros”?».\n\nY él les dijo:\n\n    «Vosotros sois de aquí abajo, yo soy de allá arriba: vosotros sois de este mundo, yo no soy de este mundo. Con razón os he dicho que moriréis en vuestros pecados: pues, si no creéis que Yo soy, moriréis en vuestros pecados».\n\nEllos le decían:\n\n    «¿Quién eres tú?».\n\nJesús les contestó:\n\n    «Lo que os estoy diciendo desde el principio. Podría decir y condenar muchas cosas en vosotros; pero el que me ha enviado es veraz, y yo comunico al mundo lo que he aprendido de él».\n\nEllos no comprendieron que les hablaba del Padre.\n\nY entonces dijo Jesús:\n\n    «Cuando levantéis en alto al Hijo del hombre, sabréis que “Yo soy”, y que no hago nada por mi cuenta, sino que hablo como el Padre me ha enseñado. El que me envió está conmigo, no me ha dejado solo; porque yo hago siempre lo que le agrada».\n\nCuando les exponía esto, muchos creyeron en él.','\n',char(10)),'2026-03-17 01:48:15','2026-03-17 01:48:15');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(106,'2026-03-27',NULL,'Viernes de la V Semana de Cuaresma','Lectura del libro de Jeremías (20,10-13)',replace('OÍA la acusación de la gente:\n\n«“Pavor-en-torno”,\n\ndelatadlo, vamos a delatarlo».\n\nMis amigos acechaban mi traspié:\n\n     «A ver si, engañado, lo sometemos\n\n     y podemos vengarnos de él».\n\nPero el Señor es mi fuerte defensor:\n\n     me persiguen, pero tropiezan impotentes.\n\nAcabarán avergonzados de su fracaso,\n\n     con sonrojo eterno que no se olvidará.\n\nSeñor del universo, que examinas al honrado\n\n     y sondeas las entrañas y el corazón,\n\n     ¡que yo vea tu venganza sobre ellos,\n\n     pues te he encomendado mi causa!\n\nCantad al Señor, alabad al Señor,\n\n     que libera la vida del pobre\n\n     de las manos de gente perversa.','\n',char(10)),'Sal 17,2-3',replace('R/. En el peligro invoqué al Señor, y me escuchó\nV/.   Yo te amo, Señor; tú eres mi fortaleza;\n\n                Señor, mi roca, mi alcázar, mi libertador.   R/.\nV/.   Dios mío, peña mía, refugio mío,\n\n                escudo mío, mi fuerza salvadora, mi baluarte.\n\n                Invoco al Señor de mi alabanza\n\n                y quedo libre de mis enemigos.   R/.\nV/.   Me cercaban olas mortales,\n\n                torrentes destructores me aterraban,\n\n                me envolvían las redes del abismo,\n\n                me alcanzaban los lazos de la muerte.   R/.\nV/.   En el peligro invoqué al Señor,\n\n                grité a mi Dios:\n\n                desde su templo él escuchó mi voz,\n\n                y mi grito llegó a sus oídos.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (10,31-42)',replace(replace('EN aquel tiempo, los judíos agarraron piedras para apedrear a Jesús.\n\nElles replicó:\n\n     «Os he hecho ver muchas obras buenas por encargo de mi Padre: ¿por cuál de ellas me apedreáis?».\n\nLos judíos le contestaron:\n\n     «No te apedreamos por una obra buena, sino por una blasfemia: porque tú, siendo un hombre, te haces Dios».\n\nJesús les replicó:\n\n     «¿No está escrito en vuestra ley: “Yo os digo: sois dioses”? Si la Escritura llama dioses a aquellos a quienes vino la palabra de Dios, y no puede fallar la Escritura, a quien el Padre consagró y envió al mundo, ¿decís vosotros: “¡Blasfemas!” Porque he dicho: “Soy Hijo de Dios”? Si no hago las obras de mi Padre, no me creáis, pero si las hago, aunque no me creáis a mí, creed a las obras, para que comprendáis y sepáis que el Padre está en mí, y yo en el Padre».\n\nIntentaron de nuevo detenerlo, pero se les escabulló de las manos. Se marchó de nuevo al otro lado del Jordán, al lugar donde antes había bautizado Juan, y se quedó allí.\n\nMuchos acudieron a él y decían:\n\n     «Juan no hizo ningún signo; pero todo lo que Juan dijo de este era verdad».\n\nY muchos creyeron en él allí.\nPalabra del Señor\nEvangelio de hoy\n						\n					\n				 \n			 \n			 \n				\n				\n				\n				\n				\n				\n					\n					\n						Calendario\n						\n					\n				 \n			 \n			 \n				\n				\n				\n				\n				\n				\n					\n					\n						Evangelio en audio\n						\n					\n				 \n			 \n			 \n				\n				\n			 \n				\n				\n			 \n			 \n			 \n				\n				\n				\n				\n				\n				\r\n\r\n    \r\n            \r\n        \r\n	\r\n		\r\n            \r\n                        \r\n                                                        \r\n                        \r\n                        \r\n                            \r\n                                                                                                Martes de la IV Semana de Cuaresma. San Patricio, obispo\r\n                                Juan 5,1-16. Al momento aquel hombre quedó sano\r\n                            \r\n                        \r\n                        \r\n                            \r\n                                \r\n                                                                            17 Mar\r\n                                                                    \r\n                                                                Evento de todo el día                                                                                                \r\n                                                                        PD-CU04M\r\n                                                                    \r\n                                                                                                                                                                \r\n                                                            \r\n                        \r\n                    \r\n                    \r\n                                                \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                            \r\n                            \r\n                                \r\n                                    FacebookTwitterWhatsAppCorreo electrónico                                \r\n                            \r\n                        \r\n                                                                                                                        Ver detalle                    \r\n                            \r\n            			\r\n\r\n\r\n    \r\n    \r\n        ¡No hay eventos!    \r\n    \r\n    \r\n\r\n\n			 \n				\n				\n				\n				\n				\n				\n				\n				\n				\n				\n					&#xe022;\n					\n						Lecturas\n						\n					\n				 \n			 \n				\n				\n				\n					&#x76;\n					\n						Comentario\n						\n					\n				 \n			 \n			 \n				\n				\n				\n				\n				\n				\n					&#xe01c;\n					\n						Liturgia\n						\n					\n				 \n			 \n				\n				\n				\n					&#xe023;\n					\n						Calendario','\r',char(13)),'\n',char(10)),'2026-03-17 01:48:15','2026-03-17 01:48:15');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(108,'2026-03-26',NULL,'Jueves de la V Semana de Cuaresma','Lectura del libro del Génesis (17,3-9)',replace('EN aquellos días, Abrán cayó rostro en tierra y Dios le habló así:\n\n    «Por mi parte, esta es mi alianza contigo: serás padre de muchedumbre de pueblos.\n\nYa no te llamarás Abrán, sino Abrahán, porque te hago padre de muchedumbre de pueblos. Te haré fecundo sobremanera: sacaré pueblos de ti, y reyes nacerán de ti.\n\nMantendré mi alianza contigo y con tu descendencia en futuras generaciones, como alianza perpetua. Seré tu Dios y el de tus descendientes futuros. Os daré a ti y a tu descendencia futura la tierra en que peregrinas, la tierra de Canaán, como posesión perpetua, y seré su Dios».\n\nEl Señor añadió a Abrahán:\n\n    «Por tu parte, guarda mi alianza, tú y tus descendientes en sucesivas generaciones».','\n',char(10)),'Sal 104,4-5.6-7.8-9',replace('R/. El Señor se acuerda de su alianza eternamente\nV/.   Recurrid al Señor y a su poder,\n\n                buscad continuamente su rostro.\n\n                Recordad las maravillas que hizo,\n\n                sus prodigios, las sentencias de su boca.   R/.\nV/.   ¡Estirpe de Abrahán, su siervo;\n\n                hijos de Jacob, su elegido!\n\n                El Señor es nuestro Dios,\n\n                él gobierna toda la tierra.   R/.\nV/.   Se acuerda de su alianza eternamente,\n\n                de la palabra dada, por mil generaciones;\n\n                de la alianza sellada con Abrahán,\n\n                del juramento hecho a Isaac.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (8,51-59)',replace('EN aquel tiempo, dijo Jesús a los judíos:\n\n    «En verdad, en verdad os digo: quien guarda mi palabra no verá la muerte para siempre».\n\nLos judíos le dijeron:\n\n    «Ahora vemos claro que estás endemoniado; Abrahán murió, los profetas también, ¿y tú dices: “Quien guarde mi palabra no gustará la muerte para siempre”? ¿Eres tú más que nuestro padre Abrahán, que murió? También los profetas murieron, ¿por quién te tienes?».\n\nJesús contestó:\n\n    «Si yo me glorificara a mí mismo, mi gloria no valdría nada. El que me glorifica es mi Padre, de quien vosotros decís: “Es nuestro Dios”, aunque no lo conocéis. Yo sí lo conozco, y si dijera “No lo conozco” sería, como vosotros, un embustero; pero yo lo conozco y guardo su palabra. Abrahán, vuestro padre, saltaba de gozo pensando ver mi día; lo vio, y se llenó de alegría».\n\nLos judíos le dijeron:\n\n    «No tienes todavía cincuenta años, ¿y has visto a Abrahán?».\n\nJesús les dijo:\n\n    «En verdad, en verdad os digo: antes de que Abrahán existiera, yo soy».\n\nEntonces cogieron piedras para tirárselas, pero Jesús se escondió y salió del templo.','\n',char(10)),'2026-03-17 01:48:16','2026-03-17 01:48:16');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(109,'2026-03-21',NULL,'Sábado de la IV Semana de Cuaresma','Lectura del libro de Jeremías (11,18-20)',NULL,'Sal 7,2-3.9',replace('R/. Señor, Dios. mío, a ti me acojo\n\nV/.   Señor, Dios mío, a ti me acojo,\n\n                líbrame de mis perseguidores y sálvame;\n\n                que no me atrapen como leones\n\n                y me desgarren sin remedio.   R/.\n\nV/.   Júzgame, Señor, según mi justicia,\n\n                según la inocencia que hay en mí.\n\n                Cese la maldad de los culpables,\n\n                y apoya tú al inocente,\n\n                tú que sondeas el corazón y las entrañas,\n\n                tú, el Dios justo.   R/.\n\nV/.   Mi escudo es Dios,\n\n                que salva a los rectos de corazón.\n\n                Dios es un juez justo,\n\n                Dios amenaza cada día.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (7,40-53)',replace('EN aquel tiempo, algunos de entre la gente, que habían oído los discursos de Jesús, decían:\n\n    «Este es de verdad el profeta».\n\nOtros decían:\n\n    «Este es el Mesías».\n\nPero otros decían:\n\n    «¿Es que de Galilea va a venir el Mesías? ¿No dice la Escritura que el Mesías vendrá del linaje de David, y de Belén, el pueblo de David?».\n\nY así surgió entre la gente una discordia por su causa.\n\nAlgunos querían prenderlo, pero nadie le puso la mano encima.\n\nLos guardias del templo acudieron a los sumos sacerdotes y fariseos, y estos les dijeron:\n\n    «¿Por qué no lo habéis traído?».\n\nLos guardias respondieron:\n\n    «Jamás ha hablado nadie como ese hombre».\n\nLos fariseos les replicaron:\n\n    «También vosotros os habéis dejado embaucar? ¿Hay algún jefe o fariseo que haya creído en él? Esa gente que no entiende de la ley son unos malditos».\n\nNicodemo, el que había ido en otro tiempo a visitarlo y que era fariseo, les dijo:\n\n    «¿Acaso nuestra ley permite juzgar a nadie sin escucharlo primero y averiguar lo que ha hecho?».\n\nEllos le replicaron:\n\n    «¿También tú eres galileo? Estudia y verás que de Galilea no salen profetas».\n\nY se volvieron cada uno a su casa.','\n',char(10)),'2026-03-21 03:45:44','2026-03-21 03:45:44');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(110,'2026-03-22',NULL,'V Domingo de Cuaresma','Lectura de la profecía de Ezequiel (37,12-14)','Así dice el Señor: «Yo mismo abriré vuestros sepulcros, y os haré salir de vuestros sepulcros, pueblo mío, y os traeré a la tierra de Israel. Y, cuando abra vuestros sepulcros y os saque de vuestros sepulcros, pueblo mío, sabréis que soy el Señor. Os infundiré mi espíritu, y viviréis; os colocaré en vuestra tierra y sabréis que yo, el Señor, lo digo y lo hago.» Oráculo del Señor.','Sal 129,1-2.3-4',replace('R/. Del Señor viene la misericordia,\n\nla redención copiosa\n\nDesde lo hondo a ti grito, Señor;\n\nSeñor, escucha mi voz,\n\nestén tus oídos atentos\n\na la voz de mi súplica. R/.\n\nSi llevas cuentas de los delitos, Señor,\n\n¿quién podrá resistir?\n\nPero de ti procede el perdón,\n\ny así infundes respeto. R/.\n\nMi alma espera en el Señor,\n\nespera en su palabra;\n\nmi alma aguarda al Señor,\n\nmás que el centinela la aurora.\n\nAguarde Israel al Señor,\n\ncomo el centinela la aurora. R/.\n\nPorque del Señor viene la misericordia,\n\nla redención copiosa;\n\ny él redimirá a Israel\n\nde todos sus delitos. R/.','\n',char(10)),'Lectura de la carta del apóstol san Pablo a los Romanos (8,8-11)','Los que viven sujetos a la carne no pueden agradar a Dios. Pero vosotros no estáis sujetos a la carne, sino al espíritu, ya que el Espíritu de Dios habita en vosotros. El que no tiene el Espíritu de Cristo no es de Cristo. Pues bien, si Cristo está en vosotros, el cuerpo está muerto por el pecado, pero el espíritu vive por la justificación obtenida. Si el Espíritu del que resucitó a Jesús de entre los muertos habita en vosotros, el que resucitó de entre los muertos a Cristo Jesús vivificará también vuestros cuerpos mortales, por el mismo Espíritu que habita en vosotros.','Lectura del santo evangelio según san Juan (11,3-7.17.20-27.33b-45)',replace('En aquel tiempo, las hermanas de Lázaro mandaron recado a Jesús, diciendo: «Señor, tu amigo está enfermo.»\n\nJesús, al oírlo, dijo: «Esta enfermedad no acabará en la muerte, sino que servirá para la gloria de Dios, para que el Hijo de Dios sea glorificado por ella.»\n\nJesús amaba a Marta, a su hermana y a Lázaro. Cuando se enteró de que estaba enfermo, se quedó todavía dos días en donde estaba.\n\nSólo entonces dice a sus discípulos: «Vamos otra vez a Judea.»\n\nCuando Jesús llegó, Lázaro llevaba ya cuatro días enterrado. Cuando Marta se enteró de que llegaba Jesús, salió a su encuentro, mientras María se quedaba en casa.\n\nY dijo Marta a Jesús: «Señor, si hubieras estado aquí no habría muerto mi hermano. Pero aún ahora sé que todo lo que pidas a Dios, Dios te lo concederá.»\n\nJesús le dijo: «Tu hermano resucitará.»\n\nMarta respondió: «Sé que resucitará en la resurrección del último día.»\n\nJesús le dice: «Yo soy la resurrección y la vida: el que cree en mí, aunque haya muerto, vivirá; y el que está vivo y cree en mí, no morirá para siempre. ¿Crees esto?»\n\nElla le contestó: «Sí, Señor: yo creo que tú eres el Mesías, el Hijo de Dios, el que tenía que venir al mundo.»\n\nJesús sollozó y, muy conmovido, preguntó: «¿Dónde lo habéis enterrado?»\n\nLe contestaron: «Señor, ven a verlo.»\n\nJesús se echó a llorar. Los judíos comentaban: «¡Cómo lo quería!»\n\nPero algunos dijeron: «Y uno que le ha abierto los ojos a un ciego, ¿no podía haber impedido que muriera éste?»\n\nJesús, sollozando de nuevo, llega al sepulcro. Era una cavidad cubierta con una losa.\n\nDice Jesús: «Quitad la losa.»\n\nMarta, la hermana del muerto, le dice: «Señor, ya huele mal, porque lleva cuatro días.»\n\nJesús le dice: «¿No te he dicho que si crees verás la gloria de Dios?»\n\nEntonces quitaron la losa.\n\nJesús, levantando los ojos a lo alto, dijo: «Padre, te doy gracias porque me has escuchado; yo sé que tú me escuchas siempre; pero lo digo por la gente que me rodea, para que crean que tú me has enviado.»\n\nY dicho esto, gritó con voz potente: «Lázaro, ven afuera.»\n\nEl muerto salió, los pies y las manos atados con vendas, y la cara envuelta en un sudario.\n\nJesús les dijo: «Desatadlo y dejadlo andar.»\n\nY muchos judíos que habían venido a casa de María, al ver lo que había hecho Jesús, creyeron en él.','\n',char(10)),'2026-03-21 03:45:51','2026-03-21 03:45:51');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(111,'2026-03-23',NULL,'Lunes de la V Semana de Cuaresma','Lectura del libro de Daniel (13,1-9.15-17.19-30.33-62)',replace('EN aquellos días, vivía en Babilonia un hombre llamado Joaquín, casado con Susana, hija de Jelcías, mujer muy bella y temerosa del Señor.\n\nSus padres eran justos y habían educado a su hija según la ley de Moisés. Joaquín era muy rico y tenía un jardín junto a su casa; y como era el más respetado de todos, los judíos solían reunirse allí.\n\nAquel año fueron designados jueces dos ancianos del pueblo, de esos que el Señor denuncia diciendo:\n\n    «En Babilonia la maldad ha brotado de los viejos jueces, que pasan por guías del pueblo».\n\nSolían ir a casa de Joaquín, y los que tenían pleitos que resolver acudían a ellos.\n\nA mediodía, cuando la gente se marchaba, Susana salía a pasear por el jardín de su marido. Los dos ancianos la veían a diario, cuando salía a pasear, y sintieron deseos de ella.\n\nPervirtieron sus pensamientos y desviaron los ojos para no mirar al cielo, ni acordarse de sus justas leyes.\n\nSucedió que, mientras aguardaban ellos el día conveniente, salió ella como los tres días anteriores sola con dos criadas, y tuvo ganas de bañarse en el jardín, porque hacía mucho calor. No había allí nadie, excepto los dos ancianos escondidos y acechándola.\n\nSusana dijo a las criadas:\n\n    «Traedme el perfume y las cremas y cerrad la puerta del jardín mientras me baño».\n\nApenas salieron las criadas, se levantaron los dos ancianos, corrieron hacia ella y le dijeron:\n\n    «Las puertas del jardín están cerradas, nadie nos ve, y nosotros sentimos deseos de ti; así que consiente y acuéstate con nosotros. Si no, daremos testimonio contra ti diciendo que un joven estaba contigo y que por eso habías despachado a las criadas».\n\nSusana lanzó un gemido y dijo:\n\n    «No tengo salida: si hago eso, mereceré la muerte; si no lo hago, no escaparé de vuestras manos. Pero prefiero no hacerlo y caer en vuestras manos antes que pecar delante del Señor».\n\nSusana se puso a gritar, y los dos ancianos, por su parte, se pusieron también a gritar contra ella. Uno de ellos fue corriendo y abrió la puerta del jardín.\n\nAl oír los gritos en el jardín, la servidumbre vino corriendo por la puerta lateral a ver qué le había pasado. Cuando los ancianos contaron su historia, los criados quedaron abochornados, porque Susana nunca había dado que hablar.\n\nAl día siguiente, cuando la gente vino a casa de Joaquín, su marido, vinieron también los dos ancianos con el propósito criminal de hacer morir a Susana. En presencia del pueblo ordenaron:\n\n    «Id a buscar a Susana, hija de Jelcías, mujer de Joaquín».\n\nFueron a buscarla, y vino ella con sus padres, hijos y parientes.\n\nToda su familia y cuantos la veían lloraban.\n\nEntonces los dos ancianos se levantaron en medio de la asamblea y pusieron las manos sobre la cabeza de Susana.\n\nElla, llorando, levantó la vista al cielo, porque su corazón confiaba en el Señor.\n\nLos ancianos declararon:\n\n    «Mientras paseábamos nosotros solos por el jardín, salió esta con dos criadas, cerró la puerta del jardín y despidió a las criadas. Entonces se le acercó un joven que estaba escondido y se acostó con ella.\n\nNosotros estábamos en un rincón del jardín y, al ver aquella maldad, corrimos hacia ellos. Los vimos abrazados, pero no pudimos sujetar al joven, porque era más fuerte que nosotros, y, abriendo la puerta, salió corriendo.\n\nEn cambio, a esta le echamos mano y le preguntamos quién era el joven, pero no quiso decírnoslo. Damos testimonio de ello».\n\nComo eran ancianos del pueblo y jueces, la asamblea los creyó y la condenó a muerte.\n\nSusana dijo gritando:\n\n    «Dios eterno, que ves lo escondido, que lo sabes todo antes de que suceda, tú sabes que han dado falso testimonio contra mí, y ahora tengo que morir, siendo inocente de lo que su maldad ha inventado contra mí».\n\nY el Señor escuchó su voz.\n\nMientras la llevaban para ejecutarla, Dios suscitó el espíritu santo en un muchacho llamado Daniel; y este dio una gran voz:\n\n    «Yo soy inocente de la sangre de esta».\n\nToda la gente se volvió a mirarlo, y le preguntaron:\n\n    «Qué es lo que estás diciendo?».\n\nÉl, plantado en medio de ellos, les contestó:\n\n    «Pero ¿estáis locos, hijos de Israel? ¿Conque, sin discutir la causa ni conocer la verdad condenáis a una hija de Israel? Volved al tribunal, porque esos han dado falso testimonio contra ella».\n\nLa gente volvió a toda prisa, y los ancianos le dijeron:\n\n    «Ven, siéntate con nosotros e infórmanos, porque Dios mismo te ha dado la ancianidad».\n\nDaniel les dijo:\n\n    «Separadlos lejos uno del otro, que los voy a interrogar».\n\nCuando estuvieron separados el uno del otro, él llamó a uno de ellos y le dijo:\n\n    «¡Envejecido en días y en crímenes! Ahora vuelven tus pecados pasados, cuando dabas sentencias injustas condenando inocentes y absolviendo culpables, contra el mandato del Señor: “No matarás al inocente ni al justo”. Ahora, puesto que tú la viste, dime debajo de qué árbol los viste abrazados».\n\nÉl contestó:\n\n    «Debajo de una acacia».\n\nRespondió Daniel:\n\n    «Tu calumnia se vuelve contra ti. Un ángel de Dios ha recibido ya la sentencia divina y te va a partir por medio».\n\nLo apartó, mandó traer al otro y le dijo:\n\n    «Hijo de Canaán, y no de Judá! La belleza te sedujo y la pasión pervirtió tu corazón. Lo mismo hacíais con las mujeres israelitas, y ellas por miedo se acostaban con vosotros; pero una mujer judía no ha tolerado vuestra maldad. Ahora dime: ¿bajo qué árbol los sorprendiste abrazados?».\n\nÉl contestó:\n\n    «Debajo de una encina».\n\nReplicó Daniel:\n\n    «Tu calumnia también se vuelve contra ti. el ángel de Dios aguarda con la espada para dividirte por medio. Y así acabará con vosotros».\n\nEntonces toda la asamblea se puso a gritar bendiciendo a Dios, que salva a los que esperan en él. Se alzaron contra los dos ancianos, a quienes Daniel había dejado convictos de falso testimonio por su propia confesión, e hicieron con ellos lo mismo que ellos habían tramado contra el prójimo. Les aplicaron la ley de Moisés y los ajusticiaron.\n\nAquel día se salvó una vida inocente.','\n',char(10)),'Sal 22,1-3',replace('R/. Aunque camine por cañadas oscuras,\n\nnada temo, porque tú vas conmigo\n\nV/.   El Señor es mi pastor, nada me falta:\n\n                en verdes praderas me hace recostar;\n\n                me conduce hacia fuentes tranquilas\n\n                y repara mis fuerzas.   R/.\n\nV/.   Me guía por el sendero justo,\n\n                por el honor de su nombre.\n\n                Aunque camine por cañadas oscuras,\n\n                nada temo, porque tú vas conmigo:\n\n                tu vara y tu cayado me sosiegan.   R/.\n\nV/.   Preparas una mesa ante mí,\n\n                enfrente de mis enemigos;\n\n                me unges la cabeza con perfume,\n\n                y mí copa rebosa.   R/.\n\nV/.   Tu bondad y tu misericordia me acompañan\n\n                todos los días de mi vida,\n\n                y habitaré en la casa del Señor\n\n                por años sin término.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (8,1-11)',replace('EN aquel tiempo, Jesús se retiró al monte de los Olivos. Al amanecer se presentó de nuevo en el templo, y todo el pueblo acudía a él, y, sentándose, les enseñaba.\n\nLos escribas y los fariseos le traen una mujer sorprendida en adulterio, y, colocándola en medio, le dijeron:\n\n    «Maestro, esta mujer ha sido sorprendida en flagrante adulterio. La ley de Moisés nos manda apedrear a las adúlteras; tú, ¿qué dices?».\n\nLe preguntaban esto para comprometerlo y poder acusarlo.\n\nPero Jesús, inclinándose, escribía con el dedo en el suelo.\n\nComo insistían en preguntarle, se incorporó y les dijo:\n\n    «El que esté sin pecado, que le tire la primera piedra».\n\nE inclinándose otra vez, siguió escribiendo.\n\nEllos, al oírlo, se fueron escabullendo uno a uno, empezando por los más viejos.\n\nY quedó solo Jesús, con la mujer en medio, que seguía allí delante.\n\nJesús se incorporó y le preguntó:\n\n    «Mujer, ¿dónde están tus acusadores?; ¿ninguno te ha condenado?».\n\nElla contestó:\n\n    «Ninguno, Señor».\n\nJesús dijo:\n\n    «Tampoco yo te condeno. Anda, y en adelante no peques más».','\n',char(10)),'2026-03-21 03:45:58','2026-03-21 03:45:58');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(112,'2026-04-03',NULL,'Viernes Santo en la Pasión del Señor','Lectura del libro de Isaías (52,13–53,12)','Mirad, mi siervo tendrá éxito, subirá y crecerá mucho. Como muchos se espantaron de él, porque desfigurado no parecía hombre, ni tenía aspecto humano, así asombrará a muchos pueblos, ante él los reyes cerrarán la boca, al ver algo inenarrable y contemplar algo inaudito. ¿Quién creyó nuestro anuncio? ¿A quién se reveló el brazo del Señor. Creció en su presencia como brote, como raíz en tierra árida, sin figura, sin belleza. Lo vimos sin aspecto atrayente, despreciado y evitado de los hombres, como un hombre de dolores, acostumbrado a sufrimientos, ante el cual se ocultan los rostros, despreciado y desestimado. Él soportó nuestros sufrimientos y aguantó nuestros dolores; nosotros lo estimamos leproso, herido de Dios y humillado pero él fue traspasado por nuestras rebeliones, triturado por nuestros crímenes. Nuestro castigo saludable cayó sobre él, sus cicatrices nos curaron. Todos errábamos como ovejas, cada uno siguiendo su camino; y el Señor cargó sobre él todos nuestros crímenes. Maltratado, voluntariamente se humillaba y no abría la boca; como cordero llevado al matadero, como oveja ante el esquilador, enmudecía y no abría la boca. Sin defensa, sin justicia, se lo llevaron, ¿quién meditó en su destino? Lo arrancaron de la tierra de los vivos, por los pecados de mi pueblo lo hirieron. Le dieron sepultura con los malvados, y una tumba con los malhechores, aunque no había cometido crímenes ni hubo engaño en su boca. El Señor quiso triturarlo con el sufrimiento, y entregar su vida como expiación; verá su descendencia, prolongará sus años, lo que el Señor quiere prosperará por su mano. Por los trabajos de su alma verá la luz, el justo se saciará de conocimiento. Mi siervo justificará a muchos, porque cargó con los crímenes de ellos. Le daré una multitud como parte, y tendrá como despojo una muchedumbre. Porque expuso su vida a la muerte y fue contado entre los pecadores, él tomó el pecado de muchos e intercedió por los pecadores.','Sal 30,2.6.12-13.15-16.17.25',replace('R/. Padre, a tus manos encomiendo mi espíritu\n\nA ti , Señor, me acojo:\n\nno quede yo nunca defraudado;\n\ntú, que eres justo, ponme a salvo.\n\nA tus manos encomiendo mi espíritu:\n\ntú, el Dios leal, me librarás. R/.\n\nSoy la burla de todos mis enemigos,\n\nla irrisión de mis vecinos,\n\nel espanto de mis conocidos;\n\nme ven por la calle, y escapan de mí.\n\nMe han olvidado como a un muerto,\n\nme han desechado como a un cacharro inútil.  R/.\n\nPero yo confío en ti, Señor,\n\nte digo: «Tú eres mi Dios.»\n\nEn tu mano están mis azares;\n\nlíbrame de los enemigos que me persiguen. R/.\n\nHaz brillar tu rostro sobre tu siervo,\n\nsálvame por tu misericordia.\n\nSed fuertes y valientes de corazón,\n\nlos que esperáis en el Señor. R/.','\n',char(10)),'Lectura de la carta a los Hebreos (4,14-16;5,7-9)','Mantengamos la confesión de la fe, ya que tenemos un sumo sacerdote grande, que ha atravesado el cielo, Jesús, Hijo de Dios. No tenemos un sumo sacerdote incapaz de compadecerse de nuestras debilidades, sino que ha sido probado en todo exactamente como nosotros, menos en el pecado. Por eso, acerquémonos con seguridad al trono de la gracia, para alcanzar misericordia y encontrar gracia que nos auxilie oportunamente. Cristo, en los días de su vida mortal, a gritos y con lágrimas, presentó oraciones y súplicas al que podía salvarlo de la muerte, cuando en su angustia fue escuchado. Él, a pesar de ser Hijo, aprendió, sufriendo, a obedecer. Y, llevado a la consumación, se ha convertido para todos los que le obedecen en autor de salvación eterna.','Pasión de nuestro Señor Jesucristo según san Juan (18,1–19,42)',replace('Pasión de nuestro Señor Jesucristo según san Juan (18,1–19,42):\nC. En aquel tiempo, salió Jesús con sus discípulos al otro lado del torrente Cedrón, donde había un huerto, y entraron allí él y sus discípulos. Judas, el traidor, conocía también el sitio, porque Jesús se reunía a menudo allí con sus discípulos. Judas entonces, tomando la patrulla y unos guardias de los sumos sacerdotes y de los fariseos, entró allá con faroles, antorchas y armas. Jesús, sabiendo todo lo que venía sobre él, se adelantó y les dijo:\n\n+ «¿A quién buscáis?»\n\nC. Le contestaron:\n\nS. «A Jesús, el Nazareno.»\n\nC. Les dijo Jesús:\n\n+ «Yo soy.»\n\nC. Estaba también con ellos Judas, el traidor. Al decirles: «Yo soy», retrocedieron y cayeron a tierra. Les preguntó otra vez:\n\n+ «¿A quién buscáis?»\n\nC. Ellos dijeron:\n\nS. «A Jesús, el Nazareno.»\n\nC. Jesús contestó:\n\n+ «Os he dicho que soy yo. Si me buscáis a mí, dejad marchar a éstos»\n\nC. Y así se cumplió lo que había dicho: «No he perdido a ninguno de los que me diste.» Entonces Simón Pedro, que llevaba una espada, la sacó e hirió al criado del sumo sacerdote, cortándole la oreja derecha. Este criado se llamaba Malco. Dijo entonces Jesús a Pedro:\n\n+ «Mete la espada en la vaina. El cáliz que me ha dado mi Padre, ¿no lo voy a beber?»\n\nC. La patrulla, el tribuno y los guardias de los judíos prendieron a Jesús, lo ataron y lo llevaron primero a Anás, porque era suegro de Caifás, sumo sacerdote aquel año; era Caifás el que había dado a los judíos este consejo: «Conviene que muera un solo hombre por el pueblo.» Simón Pedro y otro discípulo seguían a Jesús. Este discípulo era conocido del sumo sacerdote y entró con Jesús en el palacio del sumo sacerdote, mientras Pedro se quedó fuera a la puerta. Salió el otro discípulo, el conocido del sumo sacerdote, habló a la portera e hizo entrar a Pedro. La criada que hacía de portera dijo entonces a Pedro:\n\nS. «¿No eres tú también de los discípulos de ese hombre?»\n\nC. Él dijo:\n\nS. «No lo soy.»\n\nC. Los criados y los guardias habían encendido un brasero, porque hacía frío, y se calentaban. También Pedro estaba con ellos de pie, calentándose. El sumo sacerdote interrogó a Jesús acerca de sus discípulos y de la doctrina. Jesús le contestó:\n\n+ «Yo he hablado abiertamente al mundo; yo he enseñado continuamente en la sinagoga y en el templo, donde se reúnen todos los judíos, y no he dicho nada a escondidas. ¿Por qué me interrogas a mí? Interroga a los que me han oído, de qué les he hablado. Ellos saben lo que he dicho yo.»\n\nC. Apenas dijo esto, uno de los guardias que estaban allí le dio una bofetada a Jesús, diciendo:\n\nS. «¿Así contestas al sumo sacerdote?»\n\nC. Jesús respondió:\n\n+ «Si he faltado al hablar, muestra en qué he faltado; pero si he hablado como se debe, ¿por qué me pegas?»\n\nC. Entonces Anás lo envió atado a Caifás, sumo sacerdote. Simón Pedro estaba en pie, calentándose, y le dijeron:\n\nS. «¿No eres tú también de sus discípulos?»\n\nC. Él lo negó, diciendo:\n\nS. «No lo soy.»\n\nC. Uno de los criados del sumo sacerdote, pariente de aquel a quien Pedro le cortó la oreja, le dijo:\n\nS. «¿No te he visto yo con él en el huerto?»\n\nC. Pedro volvió a negar, y enseguida cantó un gallo. Llevaron a Jesús de casa de Caifás al pretorio. Era el amanecer, y ellos no entraron en el pretorio para no incurrir en impureza y poder así comer la Pascua. Salió Pilato afuera, adonde estaban ellos, y dijo:\n\nS. «¿Qué acusación presentáis contra este hombre?»\n\nC. Le contestaron:\n\nS. «Si éste no fuera un malhechor, no te lo entregaríamos.»\n\nC. Pilato les dijo:\n\nS. «Lleváoslo vosotros y juzgadlo según vuestra ley.»\n\nC. Los judíos le dijeron:\n\nS. «No estamos autorizados para dar muerte a nadie.»\n\nC. Y así se cumplió lo que había dicho Jesús, indicando de qué muerte iba a morir. Entró otra vez Pilato en el pretorio, llamó a Jesús y le dijo:\n\nS. «¿Eres tú el rey de los judíos?»\n\nC. Jesús le contestó:\n\n+ «¿Dices eso por tu cuenta o te lo han dicho otros de mí?»\n\nC. Pilato replicó:\n\nS. «¿Acaso soy yo judío? Tu gente y los sumos sacerdotes te han entregado a mí; ¿qué has hecho?»\n\nC. Jesús le contestó:\n\n+ «Mi reino no es de este mundo. Si mi reino fuera de este mundo, mi guardia habría luchado para que no cayera en manos de los judíos. Pero mi reino no es de aquí.»\n\nC. Pilato le dijo:\n\nS. «Conque, ¿tú eres rey?»\n\nC. Jesús le contestó:\n\n+ «Tú lo dices: soy rey. Yo para esto he nacido y para esto he venido al mundo: para ser testigo de la verdad. Todo el que es de la verdad escucha mi voz.»\n\nC. Pilato le dijo:\n\nS. «Y, ¿qué es la verdad?»\n\nC. Dicho esto, salió otra vez adonde estaban los judíos y les dijo:\n\nS. «Yo no encuentro en él ninguna culpa. Es costumbre entre vosotros que por Pascua ponga a uno en libertad. ¿Queréis que os suelte al rey de los judíos?»\n\nC. Volvieron a gritar:\n\nS. «A ése no, a Barrabás.»\n\nC. El tal Barrabás era un bandido. Entonces Pilato tomó a Jesús y lo mandó azotar. Y los soldados trenzaron una corona de espinas, se la pusieron en la cabeza y le echaron por encima un manto color púrpura; y, acercándose a él, le decían:\n\nS. «¡Salve, rey de los judíos!»\n\nC. Y le daban bofetadas. Pilato salió otra vez afuera y les dijo:\n\nS. «Mirad, os lo saco afuera, para que sepáis que no encuentro en él ninguna culpa.»\n\nC. Y salió Jesús afuera, llevando la corona de espinas y el manto color púrpura. Pilato les dijo:\n\nS. «Aquí lo tenéis.»\n\nC. Cuando lo vieron los sumos sacerdotes y los guardias, gritaron:\n\nS. «¡Crucifícalo, crucíficalo!»\n\nC. Pilato les dijo:\n\nS «Lleváoslo vosotros y crucificadlo, porque yo no encuentro culpa en él.»\n\nC. Los judíos le contestaron:\n\nS «Nosotros tenemos una ley, y según esa ley tiene que morir, porque se ha declarado Hijo de Dios.»\n\nC. Cuando Pilato oyó estas palabras, se asustó aún más y, entrando otra vez en el pretorio, dijo a Jesús:\n\nS. «¿De dónde eres tú?»\n\nC. Pero Jesús no le dio respuesta. Y Pilato le dijo:\n\nS. «¿A mí no me hablas? ¿No sabes que tengo autoridad para soltarte y autoridad para crucificarte?»\n\nC. Jesús le contestó:\n\n+ «No tendrías ninguna autoridad sobre mí, si no te la hubieran dado de lo alto. Por eso el que me ha entregado a ti tiene un pecado mayor.»\n\nC. Desde este momento Pilato trataba de soltarlo, pero los judíos gritaban:\n\nS. «Si sueltas a ése, no eres amigo del César. Todo el que se declara rey está contra el César.»\n\nC. Pilato entonces, al oír estas palabras, sacó afuera a Jesús y lo sentó en el tribunal, en el sitio que llaman «el Enlosado» (en hebreo Gábbata). Era el día de la Preparación de la Pascua, hacia el mediodía. Y dijo Pilato a los judíos:\n\nS. «Aquí tenéis a vuestro rey.»\n\nC. Ellos gritaron:\n\nS. «¡Fuera, fuera; crucifícalo!»\n\nC. Pilato les dijo:\n\nS. «¿A vuestro rey voy a crucificar?»\n\nC. Contestaron los sumos sacerdotes:\n\nS. «No tenemos más rey que al César.»\n\nC. Entonces se lo entregó para que lo crucificaran. Tomaron a Jesús, y él, cargando con la cruz, salió al sitio llamado «de la Calavera» (que en hebreo se dice Gólgota), donde lo crucificaron; y con él a otros dos, uno a cada lado, y en medio, Jesús. Y Pilato escribió un letrero y lo puso encima de la cruz; en él estaba escrito: «Jesús, el Nazareno, el rey de los judíos.» Leyeron el letrero muchos judíos, porque estaba cerca el lugar donde crucificaron a Jesús, y estaba escrito en hebreo, latín y griego. Entonces los sumos sacerdotes de los judíos dijeron a Pilato:\n\nS. «No, escribas: «El rey de los judíos», sino: «Éste ha dicho: Soy el rey de los judíos.»»\n\nC. Pilato les contestó:\n\nS. «Lo escrito, escrito está.»\n\nC. Los soldados, cuando crucificaron a Jesús, cogieron su ropa, haciendo cuatro partes, una para cada soldado, y apartaron la túnica. Era una túnica sin costura, tejida toda de una pieza de arriba abajo. Y se dijeron:\n\nS. «No la rasguemos, sino echemos a suerte, a ver a quién le toca.»\n\nC. Así se cumplió la Escritura: «Se repartieron mis ropas y echaron a suerte mi túnica». Esto hicieron los soldados. Junto a la cruz de Jesús estaban su madre, la hermana de María, la Magdalena. Jesús, al ver a su madre y cerca al discípulo que tanto quería, dijo a su madre:\n\n+ «Mujer, ahí tienes a tu hijo.»\n\nC. Luego, dijo al discípulo:\n\n+ «Ahí tienes a tu madre.»\n\nC. Y desde aquella hora, el discípulo la recibió en su casa. Después de esto, sabiendo Jesús que todo había llegado a su término, para que se cumpliera la Escritura dijo:\n\n+ «Tengo sed.»\n\nC. Había allí un jarro lleno de vinagre. Y, sujetando una esponja empapada en vinagre a una caña de hisopo, se la acercaron a la boca. Jesús, cuando tomó el vinagre, dijo:\n\n+ «Está cumplido.»\n\nC. E, inclinando la cabeza, entregó el espíritu. Los judíos entonces, como era el día de la Preparación, para que no se quedaran los cuerpos en la cruz el sábado, porque aquel sábado era un día solemne, pidieron a Pilato que les quebraran las piernas y que los quitaran. Fueron los soldados, le quebraron las piernas al primero y luego al otro que habían crucificado con él; pero al llegar a Jesús, viendo que ya había muerto, no le quebraron las piernas, sino que uno de los soldados, con la lanza, le traspasó el costado, y al punto salió sangre y agua. El que lo vio da testimonio, y su testimonio es verdadero, y él sabe que dice verdad, para que también vosotros creáis. Esto ocurrió para que se cumpliera la Escritura: «No le quebrarán un hueso»; y en otro lugar la Escritura dice: «Mirarán al que atravesaron.» Después de esto, José de Arimatea, que era discípulo clandestino de Jesús por miedo a los judíos, pidió a Pilato que le dejara llevarse el cuerpo de Jesús. Y Pilato lo autorizó. Él fue entonces y se llevó el cuerpo. Llegó también Nicodemo, el que había ido a verlo de noche, y trajo unas cien libras de una mixtura de mirra y áloe. Tomaron el cuerpo de Jesús y lo vendaron todo, con los aromas, según se acostumbra a enterrar entre los judíos. Había un huerto en el sitio donde lo crucificaron, y en el huerto un sepulcro nuevo donde nadie había sido enterrado todavía. Y como para los judíos era el día de la Preparación, y el sepulcro estaba cerca, pusieron allí a Jesús.','\n',char(10)),'2026-03-23 22:00:34','2026-03-23 22:00:34');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(113,'2026-04-01',NULL,'Miércoles Santo','Lectura del libro de IsaIas (50,4-9a)','Mi Señor me ha dado una lengua de iniciado, para saber decir al abatido una palabra de aliento. Cada mañana me espabila el oído, para que escuche como los iniciados. El Señor me abrió el oído; yo no resistí ni me eché atrás: ofrecí la espalda a los que me apaleaban, las mejillas a los que mesaban mi barba; no me tapé el rostro ante ultrajes ni salivazos. El Señor me ayuda, por eso no sentía los ultrajes; por eso endurecí el rostro como pedernal, sabiendo que no quedaría defraudado. Tengo cerca a mi defensor, ¿quién pleiteará contra mí? Comparezcamos juntos. ¿Quién tiene algo contra mí? Que se me acerque. Mirad, el Señor me ayuda, ¿quién me condenará?','Sal 68,8-10.21-22.31.33-34',replace('R/. Señor, que me escuche tu gran bondad el día de tu favor\n\nPor ti he aguantado afrentas,\n\nla vergüenza cubrió mi rostro.\n\nSoy un extraño para mis hermanos,\n\nun extranjero para los hijos de mi madre;\n\nporque me devora el celo de tu templo,\n\ny las afrentas con que te afrentan caen sobre mí. R/.\n\nLa afrenta me destroza el corazón, y desfallezco.\n\nEspero compasión, y no la hay;\n\nconsoladores, y no los encuentro.\n\nEn mi comida me echaron hiel,\n\npara mi sed me dieron vinagre. R/.\n\nAlabaré el nombre de Dios con cantos,\n\nproclamaré su grandeza con acción de gracias.\n\nMiradlo, los humildes, y alegraos,\n\nbuscad al Señor, y revivirá vuestro corazón.\n\nQue el Señor escucha a sus pobres,\n\nno desprecia a sus cautivos. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio segun san Mateo (26,14-25)',replace('En aquel tiempo, uno de los Doce, llamado Judas Iscariote, a los sumos sacerdotes y les propuso: «¿Qué estáis dispuestos a darme, si os lo entrego?»\n\nEllos se ajustaron con él en treinta monedas. Y desde entonces andaba buscando ocasión propicia para entregarlo.\n\nEl primer día de los Ázimos se acercaron los discípulos a Jesús y le preguntaron: «¿Dónde quieres que te preparemos la cena de Pascua?»\n\nÉl contestó: «ld a la ciudad, a casa de Fulano, y decidle: «El Maestro dice: Mi momento está cerca; deseo celebrar la Pascua en tu casa con mis discípulos.»»\n\nLos discípulos cumplieron las instrucciones de Jesús y prepararon la Pascua. Al atardecer se puso a la mesa con los Doce.\n\nMientras comían dijo: «Os aseguro que uno de vosotros me va a entregar.»\n\nEllos, consternados, se pusieron a preguntarle uno tras otro: «¿Soy yo acaso, Señor?»\n\nÉl respondió: «El que ha mojado en la misma fuente que yo, ése me va a entregar. El Hijo del hombre se va, como está escrito de él; pero, ¡ay del que va a entregar al Hijo del hombre!; más le valdría no haber nacido.»\n\nEntonces preguntó Judas, el que lo iba a entregar: «¿Soy yo acaso, Maestro?»\n\nÉl respondió: «Tú lo has dicho.»','\n',char(10)),'2026-03-23 22:00:34','2026-03-23 22:00:34');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(114,'2026-04-02',NULL,'Jueves Santo en la Cena del Señor','Lectura del libro del Éxodo (12.1-8.11-14)','En aquellos días, dijo el Señor a Moisés y a Aarón en tierra de Egipto: «Este mes será para vosotros el principal de los meses; será para vosotros el primer mes del año. Decid a toda la asamblea de Israel: «El diez de este mes cada uno procurará un animal para su familia, uno por casa. Si la familia es demasiado pequeña para comérselo, que se junte con el vecino de casa, hasta completar el número de personas; y cada uno comerá su parte hasta terminarlo. Será un animal sin defecto, macho, de un año, cordero o cabrito. Lo guardaréis hasta el día catorce del mes, y toda la asamblea de Israel lo matará al atardecer. Tomaréis la sangre y rociaréis las dos jambas y el dintel de la casa donde lo hayáis comido. Esa noche comeréis la carne, asada a fuego, comeréis panes sin fermentar y verduras amargas. Y lo comeréis así: la cintura ceñida, las sandalias en los pies, un bastón en la mano; y os lo comeréis a toda prisa, porque es la Pascua, el paso del Señor. Esta noche pasaré por todo el país de Egipto, dando muerte a todos sus primogénitos, de hombres y de animales; y haré justicia de todos los dioses de Egipto. Yo soy el Señor. La sangre será vuestra señal en las casas donde estéis: cuando vea la sangre, pasaré de largo; no os tocará la plaga exterminadora, cuando yo pase hiriendo a Egipto. Este día será para vosotros memorable, en él celebraréis la fiesta al Señor, ley perpetua para todas las generaciones.»»','Sal 115,12-13.15-16',replace('R/. El cáliz de la bendición es comunión con la sangre de Cristo\n\n¿Cómo pagaré al Señor\n\ntodo el bien que me ha hecho?\n\nAlzaré la copa de la salvación,\n\ninvocando su nombre.  R/.\n\nMucho le cuesta al Señor\n\nla muerte de sus fieles.\n\nSeñor, yo soy tu siervo,\n\nhijo de tu esclava;\n\nrompiste mis cadenas. R/.\n\nTe ofreceré un sacrificio de alabanza,\n\ninvocando tu nombre, Señor.\n\nCumpliré al Señor mis votos\n\nen presencia de todo el pueblo. R/.','\n',char(10)),'Lectura de la primera carta del apóstol san Pablo a los Corintios (11,23-26)','Yo he recibido una tradición, que procede del Señor y que a mi vez os he transmitido: Que el Señor Jesús, en la noche en que iban a entregarlo, tomó pan y, pronunciando la acción de gracias, lo partió y dijo: «Esto es mi cuerpo, que se entrega por vosotros. Haced esto en memoria mía.» Lo mismo hizo con el cáliz, después de cenar, diciendo: «Este cáliz es la nueva alianza sellada con mi sangre; haced esto cada vez que lo bebáis, en memoria mía.» Por eso, cada vez que coméis de este pan y bebéis del cáliz, proclamáis la muerte del Señor, hasta que vuelva.','Lectura del santo evangelio según san Juan (13,1-15)',replace('Antes de la fiesta de la Pascua, sabiendo Jesús que había llegado la hora de pasar de este mundo al Padre, habiendo amado a los suyos que estaban en el mundo, los amó hasta el extremo. Estaban cenando, ya el diablo le había metido en la cabeza a Judas Iscariote, el de Simón, que lo entregara, y Jesús, sabiendo que el Padre había puesto todo en sus manos, que venía de Dios y a Dios volvía, se levanta de la cena, se quita el manto y, tomando una toalla, se la ciñe; luego echa agua en la jofaina y se pone a lavarles los pies a los discípulos, secándoselos con la toalla que se había ceñido.\n\nLlegó a Simón Pedro, y éste le dijo: «Señor, ¿lavarme los pies tú a mí?»\n\nJesús le replicó: «Lo que yo hago tú no lo entiendes ahora, pero lo comprenderás más tarde.»\n\nPedro le dijo: «No me lavarás los pies jamás.»\n\nJesús le contestó: «Si no te lavo, no tienes nada que ver conmigo.»\n\nSimón Pedro le dijo: «Señor, no sólo los pies, sino también las manos y la cabeza.»\n\nJesús le dijo: «Uno que se ha bañado no necesita lavarse más que los pies, porque todo él está limpio. También vosotros estáis limpios, aunque no todos.»\n\nPorque sabía quién lo iba a entregar, por eso dijo: «No todos estáis limpios.» Cuando acabó de lavarles los pies, tomó el manto, se lo puso otra vez y les dijo: «¿Comprendéis lo que he hecho con vosotros? Vosotros me llamáis «el Maestro» y «el Señor», y decís bien, porque lo soy. Pues si yo, el Maestro y el Señor, os he lavado los pies, también vosotros debéis lavaros los pies unos a otros; os he dado ejemplo para que lo que yo he hecho con vosotros, vosotros también lo hagáis.»','\n',char(10)),'2026-03-23 22:00:34','2026-03-23 22:00:34');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(119,'2026-03-28',NULL,'Sábado de la V Semana de Cuaresma','Lectura de la profecía de Ezequiel (37,21-28)',replace('ESTO dice el Señor Dios:\n\n    «Recogeré a los hijos de Israel de entre las naciones adonde han ido, los reuniré de todas partes para llevarlos a su tierra. Los hará una sola nación en mi tierra, en los montes de Israel. Un solo rey reinará sobre todos ellos. Ya no serán dos naciones ni volverán a dividirse en dos reinos.\n\nNo volverán a contaminarse con sus ídolos, sus acciones detestables y todas sus transgresiones. Los liberaré de los lugares donde habitan y en los cuales pecaron. Los purificaré; ellos serán mi pueblo y yo seré su Dios.\n\nMi siervo David será su rey, el único pastor de todos ellos. Caminarán según mis preceptos, cumplirán mis prescripciones y las pondrán en práctica. Habitarán en la tierra que yo di a mi siervo Jacob, en la que habitaron sis padres: allí habitarán ellos, sus hijos y los hijos de sus hijos para siempre, y mi siervo David será su príncipe para siempre.\n\nHaré con ellos una alianza de paz, una alianza eterna. Los estableceré, los multiplicaré y pondré entre ellos mi santuario para siempre; tendré mi morada junto a ellos, yo seré su Dios, y ellos serán mi pueblo. Y reconocerán las naciones que yo soy el Señor que consagra Israel, cuando esté mi santuario en medio de ellos para siempre».','\n',char(10)),NULL,replace('Jr 31,10.11-12ab.13\n\nR/. El Señor nos guardará como un pastor a su rebaño\n\nV/.   Escuchad, pueblos, la palabra del Señor,\n\n                anunciadla a las islas remotas:\n\n                «El que dispersó a Israel lo reunirá,\n\n                lo guardará como un pastor a su rebaño.   R/.\n\nV/.   Porque el Señor redimió a Jacob,\n\n                lo rescató de una mano más fuerte».\n\n                Vendrán con aclamaciones a la altura de Sión,\n\n                afluirán hacia los bienes del Señor.   R/.\n\nV/.   Entonces se alegrará la doncella en la danza,\n\n                gozarán los jóvenes y los viejos;\n\n                convertiré su tristeza en gozo,\n\n                los alegraré y aliviaré sus penas.   R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (11,45-57)',replace('EN aquel tiempo,muchos judíos que habían venido a casa de María, al ver lo que había hecho Jesús, creyeron en él. Pero algunos acudieron a los fariseos y les contaron lo que había hecho Jesús.\n\nLos sumos sacerdotes y los fariseos convocaron el Sanedrín y dijeron:\n\n    «¿Qué hacemos? Este hombre hace muchos signos. Si lo dejamos seguir, todos creerán en él, y vendrán los romanos y nos destruirán el lugar santo y la nación».\n\nUno de ellos, Caifás, que era sumo sacerdote aquel año, les dijo:\n\n    «Vosotros no entendéis ni palabra; no comprendéis que os conviene que uno muera por el pueblo, y que no perezca la nación entera».\n\nEsto no lo dijo por propio impulso, sino que, por ser sumo sacerdote aquel año, habló proféticamente, anunciando que Jesús iba a morir por la nación; y no solo por la nación, sino también para reunir a los hijos de Dios dispersos.\n\nY aquel día decidieron darle muerte. Por eso Jesús ya no andaba públicamente entre los judíos, sino que se retiró a la región vecina al desierto, a una ciudad llamada Efraín, y pasaba allí el tiempo con los discípulos.\n\nSe acercaba la Pascua de los judíos, y muchos de aquella región subían a Jerusalén, antes de la Pascua, para purificarse. Buscaban a Jesús y, estando en el templo, se preguntaban:\n\n    «¿Qué os parece? ¿Vendrá a la fiesta?».\n\nLos sumos sacerdotes y fariseos habían mandado que el que se enterase de dónde estaba les avisara para prenderlo.','\n',char(10)),'2026-03-28 20:32:37','2026-03-28 20:32:37');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(120,'2026-03-29',NULL,'Domingo de Ramos en la Pasión del Señor','Lectura del libro de Isaías (50,4-7)','Mi Señor me ha dado una lengua de iniciado, para saber decir al abatido una palabra de aliento. Cada mañana me espabila el oído, para que escuche como los iniciados. El Señor me abrió el oído. Y yo no resistí ni me eché atrás: ofrecí la espalda a los que me apaleaban, las mejillas a los que mesaban mi barba; no me tapé el rostro ante ultrajes ni salivazos. El Señor me ayuda, por eso no sentía los ultrajes; por eso endurecí el rostro como pedernal, sabiendo que no quedaría defraudado.','Sal 21,8-9.17-18',replace('R/. Dios mío, Dios mío, ¿por qué me has abandonado?\n\nAl verme, se burlan de mí,\n\nhacen visajes, menean la cabeza:\n\n«Acudió al Señor, que lo ponga a salvo;\n\nque lo libre, si tanto lo quiere.» R/.\n\nMe acorrala una jauría de mastines,\n\nme cerca una banda de malhechores;\n\nme taladran las manos y los pies,\n\npuedo contar mis huesos. R/.\n\nSe reparten mi ropa,\n\nechan a suertes mi túnica.\n\nPero tú, Señor, no te quedes lejos;\n\nfuerza mía, ven corriendo a ayudarme. R/.\n\nContaré tu fama a mis hermanos,\n\nen medio de la asamblea te alabaré.\n\nFieles del Señor, alabadlo;\n\nlinaje de Jacob, glorificadlo;\n\ntemedlo, linaje de Israel. R/.','\n',char(10)),'Lectura de la carta del apóstol san Pablo a los Filipenses (2,6-11)','Cristo, a pesar de su condición divina, no hizo alarde de su categoría de Dios; al contrario, se despojó de su rango y tomó la condición de esclavo, pasando por uno de tantos. Y así, actuando como un hombre cualquiera, se rebajó hasta someterse incluso a la muerte, y una muerte de cruz. Por eso Dios lo levantó sobre todo y le concedió el «Nombre-sobre-todo-nombre»; de modo que al nombre de Jesús toda rodilla se doble en el cielo, en la tierra, en el abismo, y toda lengua proclame: Jesucristo es Señor, para gloria de Dios Padre.','Pasión de nuestro Señor Jesucristo según San Mateo (26,14–27,66)',replace('Pasión de nuestro Señor Jesucristo según San Mateo (26,14–27,66):\nC. En aquel tiempo, uno de los Doce, llamado Judas Iscariote, fue a los sumos sacerdotes y les propuso:\n\nS. «¿Qué estáis dispuestos a darme, si os lo entrego?»\n\nC. Ellos se ajustaron con él en treinta monedas. Y desde entonces andaba buscando ocasión propicia para entregarlo.\n\nC. El primer día de los Ázimos se acercaron los discípulos a Jesús y le preguntaron:\n\nS. -«¿Dónde quieres que te preparemos la cena de Pascua?»\n\nC. Él contestó:\n\n+ «Id a la ciudad, a casa de Fulano, y decidle: «El Maestro dice: Mi momento está cerca; deseo celebrar la Pascua en tu casa con mis discípulos.»»\n\nC. Los discípulos cumplieron las instrucciones de Jesús y prepararon la Pascua.\n\nC. Al atardecer se puso a la mesa con los Doce. Mientras comían dijo:\n\n+ «Os aseguro que uno de vosotros me va a entregar.»\n\nC. Ellos, consternados, se pusieron a preguntarle uno tras otro:\n\nS. «¿Soy yo acaso, Señor?»\n\nC. Él respondió:\n\n+ «El que ha mojado en la misma fuente que yo, ése me va a entregar. El Hijo del hombre se va, como está escrito de él; pero, ¡ay del que va a entregar al Hijo del hombre!; más le valdría no haber nacido.»\n\nC. Entonces preguntó Judas, el que lo iba a entregar:\n\nS. «¿Soy yo acaso, Maestro?»\n\nC. Él respondió:\n\n+ «Tú lo has dicho.»\n\nC. Durante la cena, Jesús cogió pan, pronunció la bendición, lo partió y lo dio a sus discípulos, diciendo:\n\n+ «Tomad, comed: esto es mi cuerpo.»\n\nC.. Y, cogiendo una copa, pronunció la acción de gracias y se la dio diciendo:\n\n+ «Bebed todos; porque ésta es mi sangre, sangre de la alianza, derramada por todos para el perdón de los pecados. Y os digo que no beberé más del fruto de la vid, hasta el día que beba con vosotros el vino nuevo en el reino de mi Padre.»\n\nC. Cantaron el salmo y salieron para el monte de los Olivos.\n\nC. Entonces Jesús les dijo:\n\n+ «Esta noche vais a caer todos por mi causa, porque está escrito: «Heriré al pastor, y se dispersarán las ovejas del rebaño.» Pero cuando resucite, iré antes que vosotros a Galilea.»\n\nC. Pedro replicó:\n\nS. «Aunque todos caigan por tu causa, yo jamás caeré.»\n\nC. Jesús le dijo:\n\n+ «Te aseguro que esta noche, antes que el gallo cante, me negarás tres veces.»\n\nC . Pedro le replicó:\n\nS. «Aunque tenga que morir contigo, no te negaré. »\n\nC. Y lo mismo decían los demás discípulos.\n\nC. Entonces Jesús fue con ellos a un huerto, llamado Getsemaní, y les dijo:\n\n+ «Sentaos aquí, mientras voy allá a orar.»\n\nC. Y, llevándose a Pedro y a los dos hijos de Zebedeo, empezó a entristecerse y a angustiarse. Entonces dijo:\n\n+ «Me muero de tristeza: quedaos aquí y velad conmigo.»\n\nC. Y, adelantándose un poco, cayó rostro en tierra y oraba diciendo:\n\n+ «Padre mío, si es posible, que pase y se aleje de mí ese cáliz. Pero no se haga lo que yo quiero, sino lo que tú quieres.»\n\nC. Y se acercó a los discípulos y los encontró dormidos. Dijo a Pedro:\n\n+ «¿No habéis podido velar una hora conmigo? Velad y orad para no caer en la tentación, pues el espíritu es decidido, pero la carne es débil.»\n\nC. De nuevo se apartó por segunda vez y oraba diciendo:\n\n+ «Padre mío, si este cáliz no puede pasar sin que yo lo beba, hágase tu voluntad.»\n\nC. Y, viniendo otra vez, los encontró dormidos, porque tenían los ojos cargados. Dejándolos de nuevo, por tercera vez oraba, repitiendo las mismas palabras. Luego se acercó a sus discípulos y les dijo:\n\n+ «Ya podéis dormir y descansar. Mirad, está cerca la hora, y el Hijo del hombre va a ser entregado en manos de los pecadores. ¡Levantaos, vamos! Ya está cerca el que me entrega.»\n\nC. Todavía estaba hablando, cuando apareció Judas, uno de los Doce, acompañado de un tropel de gente, con espadas y palos, mandado por los sumos sacerdotes y los ancianos del pueblo. El traidor les había dado esta contraseña:\n\nS. «Al que yo bese, ése es; detenedlo.»\n\nC. Después se acercó a Jesús y le dijo:\n\nS. «¡Salve, Maestro!»\n\nC. Y lo besó. Pero Jesús le contestó:\n\n+ «Amigo, ¿a qué vienes?»\n\nC. Entonces se acercaron a Jesús y le echaron mano para detenerlo. Uno de los que estaban con él agarró la espada, la desenvainó y de un tajo le cortó la oreja al criado del sumo sacerdote. Jesús le dijo:\n\n+ «Envaina la espada; quien usa espada, a espada morirá. ¿Piensas tú que no puedo acudir a mi Padre? Él me mandaría en seguida más de doce legiones de ángeles. Pero entonces no se cumpliría la Escritura, que dice que esto tiene que pasar.»\n\nC. Entonces dijo Jesús a la gente:\n\n+ «¿Habéis salido a prenderme con espadas y palos, como a un bandido? A diario me sentaba en el templo a enseñar y, sin embargo, no me detuvisteis.»\n\nC. Todo esto ocurrió para que se cumpliera lo que escribieron los profetas. En aquel momento todos los discípulos lo abandonaron y huyeron. Los que detuvieron a Jesús lo llevaron a casa de Caifás, el sumo sacerdote, donde se habían reunido los escribas y los ancianos. Pedro lo seguía de lejos, hasta el palacio del sumo sacerdote, y, entrando dentro, se sentó con los criados para ver en qué paraba aquello. Los sumos sacerdotes y el sanedrín en pleno buscaban un falso testimonio contra Jesús para condenarlo a muerte y no lo encontraban, a pesar de los muchos falsos testigos que comparecían. Finalmente, comparecieron dos, que dijeron:\n\nS. «Éste ha dicho: «Puedo destruir el templo de Dios y reconstruirlo en tres días.»»\n\nC. El sumo sacerdote se puso en pie y le dijo:\n\nS. «¿No tienes nada que responder? ¿Qué son estos cargos que levantan contra ti?»\n\nC. Pero Jesús callaba. Y el sumo sacerdote le dijo:\n\nS. «Te conjuro por Dios vivo a que nos digas si tú eres el Mesías, el Hijo de Dios.»\n\nC. Jesús le respondió:\n\n+ «Tú lo has dicho. Más aún, yo os digo: Desde ahora veréis que el Hijo del hombre está sentado a la derecha del Todopoderoso y que viene sobre las nubes del cielo.»\n\nC. Entonces el sumo sacerdote rasgó sus vestiduras, diciendo:\n\nS. «Ha blasfemado. ¿Qué necesidad tenemos ya de testigos? Acabáis de oír la blasfemia. ¿Qué decidís?»\n\nC. Y ellos contestaron:\n\nS. «Es reo de muerte.»\n\nC. Entonces le escupieron a la cara y lo abofetearon; otros lo golpearon, diciendo:\n\nS. «Haz de profeta, Mesías; ¿quién te ha pegado?»\n\nC. Pedro estaba sentado fuera en el patio, y se le acercó una criada y le dijo:\n\nS. «También tú andabas con Jesús el Galileo.»\n\nC. Él lo negó delante de todos, diciendo:\n\nS. «No sé qué quieres decir.»\n\nC. Y, al salir al portal, lo vio otra y dijo a los que estaban allí:\n\nS. «Éste andaba con Jesús el Nazareno.»\n\nC. Otra vez negó él con juramento:\n\nS. «No conozco a ese hombre.»\n\nC. Poco después se acercaron los que estaban allí y dijeron a Pedro:\n\nS. «Seguro; tú también eres de ellos, te delata tu acento.»\n\nC. Entonces él se puso a echar maldiciones y a jurar, diciendo:\n\nS. «No conozco a ese hombre.»\n\nC. Y en seguida cantó un gallo. Pedro se acordó de aquellas palabras de Jesús: «Antes de que cante el gallo, me negarás tres veces.» Y, saliendo afuera, lloró amargamente. Al hacerse de día, todos los sumos sacerdotes y los ancianos del pueblo se reunieron para preparar la condena a muerte de Jesús. Y, atándolo, lo llevaron y lo entregaron a Pilato, el gobernador. Entonces Judas, el traidor, al ver que habían condenado a Jesús, sintió remordimiento y devolvió las treinta monedas de plata a los sumos sacerdotes y ancianos, diciendo:\n\nS. «He pecado, he entregado a la muerte a un inocente.»\n\nC. Pero ellos dijeron:\n\nS. «¿A nosotros qué? ¡Allá tú!»\n\nC. Él, arrojando las monedas en el templo, se marchó; y fue y se ahorcó. Los sumos sacerdotes, recogiendo las monedas, dijeron:\n\nS. «No es lícito echarlas en el arca de las ofrendas, porque son precio de sangre.»\n\nC. Y, después de discutirlo, compraron con ellas el Campo del Alfarero para cementerio de forasteros. Por eso aquel campo se llama todavía «Campo de Sangre». Así se cumplió lo escrito por Jeremías, el profeta: «Y tomaron las treinta monedas de plata, el precio de uno que fue tasado, según la tasa de los hijos de Israel, y pagaron con ellas el Campo del Alfarero, como me lo había ordenado el Señor.» Jesús fue llevado ante el gobernador, y el gobernador le preguntó:\n\nS. «¿Eres tú el rey de los judíos?»\n\nC. Jesús respondió:\n\n+ «Tú lo dices.»\n\nC. Y, mientras lo acusaban los sumos sacerdotes y los ancianos, no contestaba nada. Entonces Pilato le preguntó:\n\nS. «¿No oyes cuántos cargos presentan contra ti?»\n\nC. Como no contestaba a ninguna pregunta, el gobernador estaba muy extrañado. Por la fiesta, el gobernador solía soltar un preso, el que la gente quisiera. Había entonces un preso famoso, llamado Barrabás. Cuando la gente acudió, les dijo Pilato:\n\nS. «¿A quién queréis que os suelte, a Barrabás o a Jesús, a quien llaman el Mesías?»\n\nC. Pues sabía que se lo habían entregado por envidia. Y, mientras estaba sentado en el tribunal, su mujer le mandó a decir:\n\nS. «No te metas con ese justo, porque esta noche he sufrido mucho soñando con él.»\n\nC. Pero los sumos sacerdotes y los ancianos convencieron a la gente que pidieran el indulto de Barrabás y la muerte de Jesús. El gobernador preguntó:\n\nS. «¿A cuál de los dos queréis que os suelte?»\n\nC. Ellos dijeron:\n\nS. «A Barrabás.»\n\nC. Pilato les preguntó:\n\nS. «¿Y qué hago con Jesús, llamado el Mesías?»\n\nC. Contestaron todos:\n\nS. «Que lo crucifiquen.»\n\nC. Pilato insistió:\n\nS. «Pues, ¿qué mal ha hecho?»\n\nC. Pero ellos gritaban más fuerte:\n\nS. «¡Que lo crucifiquen!»\n\nC. Al ver Pilato que todo era inútil y que, al contrario, se estaba formando un tumulto, tomó agua y se lavó las manos en presencia de la multitud, diciendo:\n\nS. «Soy inocente de esta sangre. ¡Allá vosotros!»\n\nC. Y el pueblo entero contestó:\n\nS. «¡Su sangre caiga sobre nosotros y sobre nuestros hijos!»\n\nC. Entonces les soltó a Barrabás; y a Jesús, después de azotarlo, lo entregó para que lo crucificaran. Los soldados del gobernador se llevaron a Jesús al pretorio y reunieron alrededor de él a toda la compañía; lo desnudaron y le pusieron un manto de color púrpura y, trenzando una corona de espinas, se la ciñeron a la cabeza y le pusieron una caña en la mano derecha. Y, doblando ante él la rodilla, se burlaban de él, diciendo:\n\nS. «¡Salve, rey de los judíos!»\n\nC. Luego le escupían, le quitaban la caña y le golpeaban con ella la cabeza. Y, terminada la burla, le quitaron el manto, le pusieron su ropa y lo llevaron a crucificar. Al salir, encontraron a un hombre de Cirene, llamado Simón, y lo forzaron a que llevara la cruz. Cuando llegaron al lugar llamado Gólgota (que quiere decir: «La Calavera»), le dieron a beber vino mezclado con hiel; él lo probó, pero no quiso beberlo. Después de crucificarlo, se repartieron su ropa, echándola a suertes, y luego se sentaron a custodiarlo. Encima de su cabeza colocaron un letrero con la acusación: «Éste es Jesús, el rey de los judíos.» Crucificaron con él a dos bandidos, uno a la derecha y otro a la izquierda. Los que pasaban lo injuriaban y decían, meneando la cabeza:\n\nS. «Tú que destruías el templo y lo reconstruías en tres días, sálvate a ti mismo; si eres Hijo de Dios, baja de la cruz.»\n\nC. Los sumos sacerdotes con los escribas y los ancianos se burlaban también, diciendo:\n\nS. «A otros ha salvado, y él no se puede salvar. ¿No es el rey de Israel? Que baje ahora de la cruz, y le creeremos. ¿No ha confiado en Dios? Si tanto lo quiere Dios, que lo libre ahora. ¿No decía que era Hijo de Dios?»\n\nC. Hasta los bandidos que estaban crucificados con él lo insultaban. Desde el mediodía hasta la media tarde, vinieron tinieblas sobre toda aquella región. A media tarde, Jesús gritó:\n\n+ «Elí, Elí, lamá sabaktaní.»\n\nC. (Es decir:\n\n+ «Dios mío, Dios mío, ¿por qué me has abandonado?»)\n\nC. Al oírlo, algunos de los que estaban por allí dijeron:\n\nS. «A Elías llama éste.»\n\nC. Uno de ellos fue corriendo; en seguida, cogió una esponja empapada en vinagre y, sujetándola en una caña, le dio a beber. Los demás decían:\n\nS. «Déjalo, a ver si viene Elías a salvarlo.»\n\nC. Jesús dio otro grito fuerte y exhaló el espíritu.\n\nTodos se arrodillan, y se hace una pausa\n\nC. Entonces, el velo del templo se rasgó en dos, de arriba abajo; la tierra tembló, las rocas se rajaron. Las tumbas se abrieron, y muchos cuerpos de santos que habían muerto resucitaron. Después que él resucitó, salieron de las tumbas, entraron en la Ciudad santa y se aparecieron a muchos. El centurión y sus hombres, que custodiaban a Jesús, el ver el terremoto y lo que pasaba, dijeron aterrorizados:\n\nS. «Realmente éste era Hijo de Dios.»\n\nC. Había allí muchas mujeres que miraban desde lejos, aquellas que habían seguido a Jesús desde Galilea para atenderlo; entre ellas, María Magdalena y María, la madre de Santiago y José, y la madre de los Zebedeos. Al anochecer, llegó un hombre rico de Arimatea, llamado José, que era también discípulo de Jesús. Éste acudió a Pilato a pedirle el cuerpo de Jesús. Y Pilato mandó que se lo entregaran. José, tomando el cuerpo de Jesús, lo envolvió en una sábana limpia, lo puso en el sepulcro nuevo que se había excavado en una roca, rodó una piedra grande a la entrada del sepulcro y se marchó. María Magdalena y la otra María se quedaron allí, sentadas enfrente del sepulcro. A la mañana siguiente, pasado el día de la Preparación, acudieron en grupo los sumos sacerdotes y los fariseos a Pilato y le dijeron:\n\nS. «Señor, nos hemos acordado que aquel impostor, estando en vida, anunció: «A los tres días resucitaré.» Por eso, da orden de que vigilen el sepulcro hasta el tercer día, no sea que vayan sus discípulos, roben el cuerpo y digan al pueblo: «Ha resucitado de entre los muertos.» La última impostura sería peor que la primera.»\n\nC. Pilato contestó:\n\nS. «Ahí tenéis la guardia. Id vosotros y asegurad la vigilancia como sabéis.»\n\nC. Ellos fueron, sellaron la piedra y con la guardia aseguraron la vigilancia del sepulcro.','\n',char(10)),'2026-03-28 20:32:46','2026-03-28 20:32:46');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(121,'2026-03-30',NULL,'Lunes Santo','Lectura del libro de Isaías (42,1-7)',replace('Así dice el Señor:\n\n«Mirad a mi siervo, a quien sostengo; mi elegido, en quien me complazco. He puesto mi espíritu sobre él, manifestará la justicia a las naciones. No gritará, no clamará, no voceará por las calles. La caña cascada no la quebrará, la mecha vacilante no la apagará. Manifestará la justicia con verdad. No vacilará ni se quebrará, hasta implantar la justicia en el país. En su ley esperan las islas.\n\nEsto dice el Señor, Dios, que crea y despliega los cielos, consolidó la tierra con su vegetación, da el respiro al pueblo que la habita y el aliento a quienes caminan por ella:\n\n«Yo, el Señor, te he llamado en mi justicia, te cogí de la mano, te he formé e hice de ti alianza de un pueblo y luz de las naciones, para que abras los ojos de los ciegos, saques a los cautivos de la cárcel, de la prisión a los que habitan en tinieblas».','\n',char(10)),'Sal 26,1.2.3.13-14',replace('R/. El Señor es mi luz y mi salvación\n\nEl Señor es la defensa de mí vida,\n\n¿quién me hará temblar? R.\n\nCuando me asaltan los malvados\n\npara devorar mi carne, ellos, enemigos y adversarios, tropiezan y caen. R.\n\nSi un ejército acampa contra mí,\n\nmi corazón no tiembla;\n\nsi me declaran la guerra,\n\nme siento tranquilo. R.\n\nEspero gozar de la dicha del Señor\n\nen el país de la vida.\n\nEspera en el Señor, sé valiente,\n\nten ánimo, espera en el Señor. R.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (12,1-11)',replace('Seis días antes de la Pascua, fue Jesús a Betania, donde vivía Lázaro, a quien había resucitado de entre los muertos. Allí le ofrecieron una cena; Marta servía, y Lázaro era uno de los que estaban con él a la mesa. María tomó una libra de perfume de nardo, auténtico y costoso, le ungió a Jesús los pies y se los enjugó con su cabellera. Y la casa se llenó de la fragancia del perfume.\n\nJudas Iscariote, uno de sus discípulos, el que lo iba a entregar, dice:\n\n«¿Por qué no se ha vendido este perfume por trescientos denarios para dárselos a los pobres?».\n\nEsto lo dijo, no porque le importasen los pobres, sino porque era un ladrón; y como tenía la bolsa, se llevaba de lo que iban echando.\n\nJesús dijo:\n\n&#8211; «Déjala; lo tenía guardado para el día de mi sepultura; porque a los pobres los tenéis siempre con vosotros, pero a mí no siempre me tenéis».\n\nUna muchedumbre de judíos se enteró de que estaba allí y fueron, no sólo por Jesús, sino también para ver a Lázaro, al que había resucitado de entre los muertos.\n\nLos sumos sacerdotes decidieron matar también a Lázaro, porque muchos judíos, por su causa, se les iban y creían en Jesús.','\n',char(10)),'2026-03-28 20:32:54','2026-03-28 20:32:54');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(122,'2026-03-31',NULL,'Martes Santo','Lectura del libro de Isaías (49,1-6)',replace('Escuchadme, islas; atended, pueblos lejanos:\n\nEl Señor me llamó desde el vientre materno, de las entrañas de mi madre, y pronunció mi nombre. Hizo de mi boca una espada afilada, me escondió en la sombra de su mano; me hizo flecha bruñida, me guardó en su aljaba y me dijo:\n\n&#8211; «Tú eres mi siervo, Israel, por medio de ti me glorificaré».\n\nY yo pensaba: «En vano me he cansado, en viento y en nada he gastado mis fuerzas». En realidad el Señor defendía mi causa, mi recompensa la custodiaba Dios. Y ahora dice el Señor,el que me formó desde el vientre como siervo suyo, para que le devolvise a Jacob, para que le reuniera a Israel; he sido glorificado a los ojos de Dios. Y mi Dios era mi fuerza:\n\n&#8211; «Es poco que seas mi siervo para restablecer las tribus de Jacob y traer de vuelta a los supervivientes de Israel. Te hago luz de las naciones, para que mi salvación alcance hasta el confín de la tierra».','\n',char(10)),'Sal 70,1-2.3-4',replace('R/. Mi boca contará tu salvación, Señor\n\nA ti, Señor, me acojo:\n\nno quede yo derrotado para siempre;\n\ntú que eres justo, líbrame y ponme a salvo,\n\ninclina a mí tu oído, y sálvame. R.\n\nSé tú mi roca de refugio,\n\nel alcázar donde me salve,\n\nporque mi peña y mi alcázar eres tú.\n\nDios mío, líbrame de la mano perversa. R.\n\nPorque tú, Señor, fuiste mi esperanza\n\ny mi confianza, Señor, desde mi juventud.\n\nEn el vientre materno ya me apoyaba en ti,\n\nen el seno tú me sostenías. R.\n\nMi boca contará tu justicia,\n\ny todo el día tu salvación.\n\nDios mío, me instruiste desde mi juventud,\n\ny hasta hoy relato tus maravillas. R.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (13,21-33.36-38)',replace('En aquel tiempo, estando Jesús a la mesa con sus discípulos, se turbó en su espíritu y dio testimonio diciendo:\n\n&#8211; «En verdad, en verdad os digo: uno de vosotros me va a entregar».\n\nLos discípulos se miraron unos a otros perplejos, por no saber de quién lo decía.\n\nUno de ellos, el que Jesús amaba, estaba reclinado a la mesa en el seno de Jesús. Simón Pedro le hizo señas para que averiguase por quién lo decía.\n\nEntonces él, apoyándose en el pecho de Jesús, le preguntó:\n\n&#8211; «Señor, ¿quién es?».\n\nLe contestó Jesús:\n\n&#8211; «Aquel a quien yo le dé este trozo de pan untado».\n\nY, untando el pan, se lo dio a Judas, hijo de Simón el Iscariote.\n\nDetrás del pan, entró en él Satanás. Entonces Jesús le dijo:\n\n&#8211; «Lo que vas hacer, hazlo pronto».\n\nNinguno de los comensales entendió a qué se refería. Como Judas guardaba la bolsa, algunos suponían que Jesús le encargaba comprar lo necesario para la fiesta o dar algo a los pobres. Judas, después de tomar el pan, salió inmediatamente. Era de noche.\n\nCuando salió, dijo Jesús:\n\n&#8211; «Ahora es glorificado el Hijo del hombre, y Dios es glorificado en él. Si Dios es glorificado en él, también Dios lo glorificará en sí mismo: pronto lo glorificará. Hijitos, me queda poco de estar con vosotros. Me busca¬réis, pero lo que dije a los judíos os lo digo ahora a vosotros:\n\n«Donde yo voy, vosotros no podéis ir»»\n\nSimón Pedro le dijo:\n\n&#8211; «Señor, ¿a dónde vas?».\n\nJesús le respondió:\n\n&#8211; «Adonde yo voy no me puedes seguir ahora, me seguirás más tarde».\n\nPedro replicó:\n\n&#8211; «Señor, ¿por qué no puedo seguirte ahora? Daré mi vida por ti».\n\nJesús le contestó:\n\n&#8211; «¿Con que darás tu vida por mí? En verdad, en verdad te digo: no cantará el gallo antes de que me hayas negado tres veces».','\n',char(10)),'2026-03-28 20:33:01','2026-03-28 20:33:01');
