INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(129,'2026-04-06',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-03-31 05:12:06','2026-03-31 05:12:06');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(130,'2026-04-05',NULL,'Domingo de Pascua de la Resurrección del Señor','Lectura del libro de los Hechos de los Apóstoles (10,34a.37-43)',replace('EN aquellos días, Pedro tomó la palabra y dijo:\n\n    «Vosotros conocéis lo que sucedió en toda Judea, comenzando por Galilea, después del bautismo que predicó Juan. Me refiero a Jesús de Nazaret, ungido por Dios con la fuerza del Espíritu Santo, que pasó haciendo el bien y curando a todos los oprimidos por el diablo, porque Dios estaba con él.\n\nNosotros somos testigos de todo lo que hizo en la tierra de los judíos y en Jerusalén. A este lo mataron, colgándolo de un madero. Pero Dios lo resucitó al tercer día y le concedió la gracia de manifestarse, no a todo el pueblo, sino a los testigos designados por Dios: a nosotros, que hemos comido y bebido con él después de su resurrección de entre los muertos.\n\nNos encargó predicar al pueblo, dando solemne testimonio de que Dios lo ha constituido juez de vivos y muertos. De él dan testimonio todos los profetas: que todos los que creen en él reciben, por su nombre, el perdón de los pecados».','\n',char(10)),'Sal 117,1-2.16',replace('R/. Éste es el día en que actuó el Señor:\n\nsea nuestra alegría y nuestro gozo\n\nDad gracias al Señor porque es bueno,\n\nporque es eterna su misericordia.\n\nDiga la casa de Israel:\n\neterna es su misericordia.  R/.\n\n«La diestra del Señor es poderosa,\n\nla diestra del Señor es excelsa».\n\nNo he de morir, viviré\n\npara contar las hazañas del Señor.   R/.\n\nLa piedra que desecharon los arquitectos\n\nes ahora la piedra angular.\n\nEs el Señor quien lo ha hecho,\n\nha sido un milagro patente.  R/.','\n',char(10)),'Lectura de la carta del apóstol san Pablo a los Colosenses (3,1-4)',replace('HERMANOS:\n\nSi habéis resucitado con Cristo, buscad los bienes de allá arriba, donde Cristo está sentado a la derecha de Dios; aspirad a los bienes de arriba, no a los de la tierra.\n\nPorque habéis muerto; y vuestra vida está con Cristo escondida en Dios. Cuando aparezca Cristo, vida vuestra, entonces también vosotros apareceréis gloriosos, juntamente con él.','\n',char(10)),'Lectura del santo evangelio según san Juan (20,1-9)',replace('EL primer día de la semana, María la Magdalena fue al sepulcro al amanecer, cuando aún estaba oscuro, y vio la losa quitada del sepulcro.\n\nEchó a correr y fue donde estaban Simón Pedro y el otro discípulo, a quien Jesús amaba, y les dijo:\n\n    «Se han llevado del sepulcro al Señor y no sabemos dónde lo han puesto».\n\nSalieron Pedro y el otro discípulo camino del sepulcro. Los dos corrían juntos, pero el otro discípulo corría más que Pedro; se adelantó y llegó primero al sepulcro; e, inclinándose, vio los lienzos tendidos; pero no entró.\n\nLlegó también Simón Pedro detrás de él y entró en el sepulcro: vio los lienzos tendidos y el sudario con que le habían cubierto la cabeza, no con los lienzos, sino enrollado en un sitio aparte.\n\nEntonces entró también el otro discípulo, el que había llegado primero al sepulcro; vio y creyó.\n\nPues hasta entonces no habían entendido la Escritura: que él había de resucitar de entre los muertos.','\n',char(10)),'2026-04-05 12:26:38','2026-04-05 12:26:38');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(131,'2026-04-04',NULL,'Sábado Santo de la Sepultura del Señor',NULL,replace('El Sábado Santo no hay liturgia, por eso no hay lecturas.\nPuede leer la reflexión para este día','\n',char(10)),NULL,NULL,NULL,NULL,NULL,replace(replace('Evangelio de hoy\n						\n					\n				 \n			 \n			 \n				\n				\n				\n				\n				\n				\n					\n					\n						Calendario\n						\n					\n				 \n			 \n			 \n				\n				\n				\n				\n				\n				\n					\n					\n						Evangelio en audio\n						\n					\n				 \n			 \n			 \n				\n				\n			 \n				\n				\n			 \n			 \n			 \n				\n				\n				\n				\n				\n				\r\n\r\n    \r\n            \r\n        \r\n	\r\n		\r\n            \r\n                        \r\n                                                        \r\n                        \r\n                        \r\n                            \r\n                                                                                                Domingo de Pascua de la Resurrección del Señor.\r\n                                Jn 20,1-9. Él había de resucitar de entre los muertos.\r\n                            \r\n                        \r\n                        \r\n                            \r\n                                \r\n                                                                            05 Abr\r\n                                                                    \r\n                                                                Evento de todo el día                                                                                                \r\n                                                                        PD-PA01D\r\n                                                                    \r\n                                                                                                                                                                \r\n                                                            \r\n                        \r\n                    \r\n                    \r\n                                                \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                            \r\n                            \r\n                                \r\n                                    FacebookTwitterWhatsAppCorreo electrónico                                \r\n                            \r\n                        \r\n                                                                                                                        Ver detalle                    \r\n                            \r\n            			\r\n\r\n\r\n    \r\n    \r\n        ¡No hay eventos!    \r\n    \r\n    \r\n\r\n\n			 \n				\n				\n				\n				\n				\n				\n				\n				\n				\n				\n					&#xe022;\n					\n						Lecturas\n						\n					\n				 \n			 \n				\n				\n				\n					&#x76;\n					\n						Comentario\n						\n					\n				 \n			 \n			 \n				\n				\n				\n				\n				\n				\n					&#xe01c;\n					\n						Liturgia\n						\n					\n				 \n			 \n				\n				\n				\n					&#xe023;\n					\n						Calendario','\r',char(13)),'\n',char(10)),'2026-04-05 12:27:13','2026-04-05 12:27:13');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(132,'2026-04-12',NULL,'II Domingo de Pascua o de la Divina Misericordia','Lectura del libro de los Hechos de los apóstoles (2,42-47)',replace('LOS hermanos perseveraban en la enseñanza de los apóstoles, en la comunión, en la fracción del pan y en las oraciones.\n\nTodo el mundo estaba impresionado, y los apóstoles hacían muchos prodigios y signos. Los creyentes vivían todos unidos y tenían todo en común; vendían posesiones y bienes y los repartían entre todos, según la necesidad de cada uno.\n\nCon perseverancia acudían a diario al templo con un mismo espíritu, partían el pan en las casas y tomaban el alimento con alegría y sencillez de corazón; alababan a Dios y eran bien vistos de todo el pueblo; y día tras día el Señor iba agregando a los que se iban salvando.','\n',char(10)),'Sal 117,2-4.13-15.22-24',replace('R/. Dad gracias al Señor porque es bueno,\n\nporque es eterna su misericordia\n\nDiga la casa de Israel:\n\neterna es su misericordia.\n\nDiga la casa de Aarón:\n\neterna es su misericordia.\n\nDigan los fieles del Señor:\n\neterna es su misericordia.  R/.\n\nEmpujaban y empujaban para derribarme,\n\npero el Señor me ayudó;\n\nel Señor es mi fuerza y mi energía,\n\nél es mi salvación.\n\nEscuchad: hay cantos de victoria\n\nen las tiendas de los justos.  R/.\n\nLa piedra que desecharon los arquitectos\n\nes ahora la piedra angular.\n\nEs el Señor quien lo ha hecho,\n\nha sido un milagro patente.\n\nÉste es el día que hizo el Señor:\n\nsea nuestra alegría y nuestro gozo.  R/.','\n',char(10)),'Lectura de la primera carta del apóstol san Pedro (1,3-9)',replace('BENDITO sea Dios, Padre de nuestro Señor, Jesucristo, que, por su gran misericordia, mediante la resurrección de Jesucristo de entre los muertos, nos ha regenerado para una esperanza viva; para una herencia incorruptible, intachable e inmarcesible, reservada en el cielo a vosotros, que, mediante la fe, estáis protegidos con la fuerza de Dios; para una salvación dispuesta a revelarse en el momento final.\n\nPor ello os alegráis, aunque ahora sea preciso padecer un Poco en pruebas diversas; así la autenticidad de vuestra fe, más preciosa que el oro, que, aunque es perecedero, se aquilata a fuego, merecerá premio, gloria y honor en la revelación de Jesucristo; sin haberlo visto lo amáis y, sin contemplarlo todavía, creéis en él y así os alegráis con un gozo inefable y radiante, alcanzando así la meta de vuestra fe: la salvación de vuestras almas.','\n',char(10)),'Lectura del santo evangelio según san Juan (20,19-31)',replace('AL anochecer de aquel día, el primero de la semana, estaban los discípulos en una casa, con las puertas cerradas por miedo a los judíos. Y en esto entró Jesús, se puso en\n\nmedio y les dijo:\n\n«Paz a vosotros».\n\nY, diciendo esto, les enseñó las manos y el costado. Y los discípulos se llenaron de alegría al ver al Señor. Jesús repitió:\n\n«Paz a vosotros. Como el Padre me ha enviado, así también os envío yo».\n\nY, dicho esto, sopló sobre ellos y les dijo:\n\n«Recibid el Espíritu Santo; a quienes les perdonéis los pecados, les quedan perdonados; a quienes se los retengáis, les quedan retenidos».\n\nTomás, uno de los Doce, llamado el Mellizo, no estaba con ellos cuando vino Jesús. Y los otros discípulos le decían:\n\n    «Hemos visto al Señor».\n\nPero él les contestó:\n\n    «Si no veo en sus manos la señal de los clavos, si no meto el dedo en el agujero de los clavos y no meto la mano en su costado, no lo creo».\n\nA los ocho días, estaban otra vez dentro los discípulos y Tomás con ellos. Llegó Jesús, estando cerradas las puertas, se puso en medio y dijo:\n\n«Paz a vosotros».\n\nLuego dijo a Tomás:\n\n«Trae tu dedo, aquí tienes mis manos; trae tu mano y métela en mi costado; y no seas incrédulo, sino creyente».\n\nContestó Tomás:\n\n    «¡Señor mío y Dios mío!».\n\nJesús le dijo:\n\n    «¿Porque me has visto has creído? Bienaventurados los que crean sin haber visto».\n\nMuchos otros signos, que no están escritos en este libro, hizo Jesús a la vista de los discípulos. Estos han sido escritos para que creáis que Jesús es el Mesías, el Hijo de Dios, y para que, creyendo, tengáis vida en su nombre.','\n',char(10)),'2026-04-07 00:24:09','2026-04-07 00:24:09');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(133,'2026-04-16',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-07 00:24:58','2026-04-07 00:24:58');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(134,'2026-04-14',NULL,'Martes de la II Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (4,32-37)',replace('EL grupo de los creyentes tenía un solo corazón y una sola alma: nadie llamaba suyo propio nada de lo que tenía, pues lo poseían todo en común.\n\nLos apóstoles daban testimonio de la resurrección del Señor Jesús con mucho valor. Y se los miraba a todos con mucho agrado. Entre ellos no había necesitados, pues los que poseían tierras o casas las vendían, traían el dinero de lo vendido y lo ponían a los pies de los apóstoles; luego se distribuía a cada uno según lo que necesitaba.\n\nJosé, a quien los apóstoles apellidaron Bernabé, que significa hijo de la consolación, que era levita y natural de Chipre, tenía un campo y lo vendió; llevó el dinero y lo puso a los pies de los apóstoles.','\n',char(10)),'Sal 92,1',replace('R/. El Señor reina, vestido de majestad\n\nEl Señor reina, vestido de majestad;\n\nel Señor, vestido y ceñido de poder. R/.\n\nAsí está firme el orbe y no vacila.\n\nTu trono está firme desde siempre,\n\ny tú eres eterno. R/.\n\nTus mandatos son fieles y seguros;\n\nla santidad es el adorno de tu casa,\n\nSeñor, por días sin término. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (3,5a.7b-15)',replace('EN aquel tiempo, dijo Jesús a Nicodemo:\n\n«Tenéis que nacer de nuevo; el viento sopla donde quiere y oyes su ruido, pero no sabes de dónde viene ni adónde va. Así es todo el que ha nacido del Espíritu».\n\nNicodemo le preguntó:\n\n«¿Cómo puede suceder eso?».\n\nLe contestó Jesús:\n\n«¿Tú eres maestro en Israel, y no lo entiendes? En verdad, en verdad te digo: hablamos de lo que sabemos y damos testimonio de lo que hemos visto, pero no recibís nuestro testimonio. Si os hablo de las cosas terrenas y no me creéis, ¿cómo creeréis si os hablo de las cosas celestiales? Nadie ha subido al cielo sino el que bajó del cielo, el Hijo del hombre.\n\nLo mismo que Moisés elevó la serpiente en el desierto, así tiene que ser elevado el Hijo del hombre, para que todo el que cree en él tenga vida eterna».','\n',char(10)),'2026-04-07 00:25:03','2026-04-07 00:25:03');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(135,'2026-04-18',NULL,'Sábado de la II Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (6,1-7)',replace('En aquellos días, al crecer el número de los discípulos, los de lengua griega se quejaron contra los de lengua hebrea, porque en el servicio diario no se atendía a sus viudas.\n\nLos Doce, convocando a la asamblea de los discípulos, dijeron:\n\n«No nos parece bien descuidar la palabra de Dios para ocuparnos del servicio de las mesas. Por tanto, hermanos, escoged a siete de vosotros, hombres de buena fama, llenos de espíritu y de sabiduría, y los encargaremos de esta tarea; nosotros nos dedicaremos a la oración y al servicio de la palabra».\n\nLa propuesta les pareció bien a todos y eligieron a Esteban, hombre lleno de fe y de Espíritu Santo; a Felipe, Prócoro, Nicanor, Timón, Parmenas y Nicolás, prosélito de Antioquía. Se los presentaron a los apóstoles y ellos les impusieron las manos orando.\n\nLa palabra de Dios iba creciendo y en Jerusalén se multiplicaba el número de discípulos; incluso muchos sacerdotes aceptaban la fe.','\n',char(10)),'Sal 32,1-2.4-5.18-19',replace('R/. Que tu misericordia, Señor, venga sobre nosotros, como lo esperamos de ti\n\nAclamad, justos, al Señor,\n\nque merece la alabanza de los buenos.\n\nDad gracias al Señor con la cítara,\n\ntocad en su honor el arpa de diez cuerdas. R/.\n\nLa palabra del Señor es sincera,\n\ny todas sus acciones son leales;\n\nél ama la justicia y el derecho,\n\ny su misericordia llena la tierra. R/.\n\nLos ojos del Señor están puestos en quien lo teme,\n\nen los que esperan su misericordia,\n\npara librar sus vidas de la muerte\n\ny reanimarlos en tiempo de hambre. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (6,16-21)',replace('AL oscurecer, los discípulos de Jesús bajaron al mar, embarcaron y empezaron la travesía hacia Cafarnaún. Era ya noche cerrada, y todavía Jesús no los había alcanzado; soplaba un viento fuerte, y el lago se iba encrespando. Habían remado unos veinticinco o treinta estadios, cuando vieron a Jesús que se acercaba a la barca, caminando sobre el mar, y se asustaron.\n\nPero él les dijo:\n\n«Soy yo, no temáis».\n\nQuerían recogerlo a bordo, pero la barca tocó tierra en seguida, en el sitio adonde iban.','\n',char(10)),'2026-04-07 00:25:03','2026-04-07 00:25:03');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(137,'2026-04-13',NULL,'Lunes de la II Semana de Pascua','Lectura del Libro de los Hechos de los apóstoles (4,23-31)',replace('EN aquellos días, Pedro y Juan, puestos en libertad, volvieron a los suyos y les contaron lo que les habían dicho los sumos sacerdotes y los ancianos.\n\nAl oírlo, todos invocaron a una a Dios en voz alta, diciendo:\n\n«Señor, tú que hiciste el cielo, la tierra, el mar y todo lo que hay en ellos; tú que por el Espíritu Santo dijiste, por boca de nuestro padre David, tu siervo:\n\n“¿Por qué se amotinan las naciones y los pueblos planean proyectos vanos? Se presentaron los reyes de la tierra, los príncipes conspiraron contra el Señor y contra su Mesías”.\n\nPues en verdad se aliaron en esta ciudad Herodes y Poncio Pilato con los gentiles y el pueblo de Israel contra tu santo siervo Jesús, a quien tú ungiste, para realizar cuanto tu mano y tu voluntad habían determinado que debía suceder. Ahora, Señor, fíjate en sus amenazas y concede a tus siervos predicar tu palabra con toda valentía; extiende tu mano para que realicen curaciones, signos y prodigios por el nombre de tu santo siervo Jesús».\n\nAl terminar la oración, tembló el lugar donde estaban reunidos; los llenó a todos el Espíritu Santo, y predicaban con valentía la palabra de Dios.','\n',char(10)),'Sal 2,1-3.4-6.7-9',replace('R/. Dichosos los que se refugian en ti, Señor\n\n¿Por qué se amotinan las naciones\n\ny los pueblos planean un fracaso?\n\nSe alían los reyes de la tierra,\n\nlos príncipes conspiran\n\ncontra el Señor y contra su Mesías:\n\n«Rompamos sus coyundas,\n\nsacudamos su yugo». R/.\n\nEl que habita en el cielo sonríe,\n\nel Señor se burla de ellos.\n\nLuego les habla con ira,\n\nlos espanta con su cólera:\n\n«Yo mismo he establecido a mi Rey\n\nen Sion, mi monte santo». R/.\n\nVoy a proclamar el decreto del Señor;\n\nél me ha dicho: «Tú eres mi hijo:\n\nyo te he engendrado hoy.\n\nPídemelo:\n\nte daré en herencia las naciones;\n\nen posesión, los confines de la tierra:\n\nlos gobernarás con cetro de hierro,\n\nlos quebrarás con jarro de loza». R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (3,1-8)',replace('HABÍA un hombre del grupo de los fariseos llamado Nicodemo, jefe judío. Este fue a ver a Jesús de noche y le dijo:\n\n«Rabí, sabemos que has venido de parte de Dios, como maestro; porque nadie puede hacer los signos que tú haces si Dios no está con él».\n\nJesús le contestó:\n\n«En verdad, en verdad te digo: el que no nazca de nuevo no puede ver el reino de Dios».\n\nNicodemo le pregunta:\n\n«¿Cómo puede nacer un hombre siendo viejo? ¿Acaso puede por segunda vez entrar en el vientre de su madre y nacer?».\n\nJesús le contestó:\n\n«En verdad, en verdad te digo: el que no nazca de agua y de Espíritu no puede entrar en el reino de Dios. Lo que nace de la carne es carne, lo que nace del Espíritu es espíritu. No te extrañes de que te haya dicho: “Tenéis que nacer de nuevo”; el viento sopla donde quiere y oyes su ruido, pero no sabemos de dónde viene ni adónde va. Así es todo lo que ha nacido del Espíritu».','\n',char(10)),'2026-04-07 00:25:03','2026-04-07 00:25:03');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(138,'2026-04-17',NULL,'Viernes de la II Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (5,34-42)',replace('EN aquellos días, un fariseo llamado Gamaliel, doctor de la ley, respetado por todo el pueblo, se levantó en el Sanedrín, mandó que sacaran fuera un momento a los apóstoles y dijo:\n\n«Israelitas, pensad bien lo que vais a hacer con esos hombres. Hace algún tiempo se levantó Teudas, dándoselas de hombre importante, y se le juntaron unos cuatrocientos hombres. Fue ejecutado, se dispersaron todos sus secuaces y todo acabó en nada.\n\nMás tarde, en los días del censo, surgió Judas el Galileo, arrastrando detrás de sí gente del pueblo; también pereció, y se disgregaron todos sus secuaces.\n\nEn el caso presente, os digo: no os metáis con esos hombres; soltadlos. Si su idea y su actividad son cosa de hombres, se disolverá; pero, si es cosa de Dios, no lograréis destruirlos, y os expondríais a luchar contra Dios».\n\nLe dieron la razón y, habiendo llamado a los apóstoles, los azotaron, les prohibieron hablar en nombre de Jesús, y los soltaron. Ellos, pues, salieron del Sanedrín contentos de haber merecido aquel ultraje por el Nombre. Ningún día dejaban de enseñar, en el templo y por las casas, anunciando la buena noticia acerca del Mesías Jesús.','\n',char(10)),'Sal 26,1.4.13-14',replace('R/. Una cosa pido al Señor: habitar en su casa\n\nEl Señor es mi luz y mi salvación,\n\n¿a quién temeré?\n\nEl Señor es la defensa de mi vida,\n\n¿quién me hará temblar? R/.\n\nUna cosa pido al Señor,\n\neso buscaré:\n\nhabitar en la casa del Señor\n\npor los días de mi vida;\n\ngozar de la dulzura del Señor,\n\ncontemplando su templo. R/.\n\nEspero gozar de la dicha del Señor\n\nen el país de la vida.\n\nEspera en el Señor, sé valiente,\n\nten ánimo, espera en el Señor. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (6,1-15)',replace('EN aquel tiempo, Jesús se marchó a la otra parte del mar de Galilea, o de Tiberíades. Lo seguía mucha gente, porque habían visto los signos que hacía con los enfermos.\n\nSubió Jesús entonces a la montaña y se sentó allí con sus discípulos.\n\nEstaba cerca la Pascua, la fiesta de los judíos. Jesús entonces levantó los ojos y, al ver que acudía mucha gente, dice a Felipe:\n\n«¿Con qué compraremos panes para que coman estos?».\n\nLo decía para probarlo, pues bien sabía él lo que iba a hacer.\n\nFelipe le contestó:\n\n«Doscientos denarios de pan no bastan para que a cada uno le toque un pedazo».\n\nUno de sus discípulos, Andrés, el hermano de Simón Pedro, le dice:\n\n«Aquí hay un muchacho que tiene cinco panes de cebada y dos peces; pero ¿qué es eso para tantos?».\n\nJesús dijo:\n\n«Decid a la gente que se siente en el suelo».\n\nHabía mucha hierba en aquel sitio. Se sentaron; solo los hombres eran unos cinco mil.\n\nJesús tomó los panes, dijo la acción de gracias y los repartió a los que estaban sentados, y lo mismo todo lo que quisieron del pescado.\n\nCuando se saciaron, dice a sus discípulos:\n\n«Recoged los pedazos que han sobrado; que nada se pierda».\n\nLos recogieron y llenaron doce canastos con los pedazos de los cinco panes de cebada que sobraron a los que habían comido. La gente entonces, al ver el signo que había hecho, decía:\n\n«Este es verdaderamente el Profeta que va a venir al mundo».\n\nJesús, sabiendo que iban a llevárselo para proclamarlo rey, se retiró otra vez a la montaña él solo.','\n',char(10)),'2026-04-07 00:25:04','2026-04-07 00:25:04');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(139,'2026-04-15',NULL,'Miércoles de la II Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (5,17-26)',replace('EN aquellos días, el sumo sacerdote y todos los suyos, que integran la secta de los saduceos, en un arrebato de celo, prendieron a los apóstoles y los metieron en la cárcel pública. Pero, por la noche, el ángel del Señor les abrió las puertas de la cárcel y los sacó fuera, diciéndoles:\n\n«Marchaos y, cuando lleguéis al templo, explicad al pueblo todas estas palabras de vida».\n\nEntonces ellos, al oírlo, entraron en el templo al amanecer y se pusieron a enseñar. Llegó entre tanto el sumo sacerdote con todos los suyos, convocaron el Sanedrín y el pleno de los ancianos de los hijos de Israel, y mandaron a la prisión para que los trajesen. Fueron los guardias, no los encontraron en la cárcel, y volvieron a informar, diciendo:\n\n«Hemos encontrado la prisión cerrada con toda seguridad, y a los centinelas en pie a las puertas; pero, al abrir, no encontramos a nadie dentro».\n\nAl oír estas palabras, ni el jefe de la guardia del templo ni los sumos sacerdotes atinaban a explicarse qué había pasado. Uno se presentó, avisando:\n\n«Mirad, los hombres que metisteis en la cárcel están en el templo, enseñando al pueblo».\n\nEntonces el jefe salió con los guardias y se los trajo, sin emplear la fuerza, por miedo a que el pueblo los apedrease.','\n',char(10)),'Sal 33,2-3.4-5.6-7.8-9',replace('R/. Si el afligido invoca al Señor, él lo escucha\n\nBendigo al Señor en todo momento,\n\nsu alabanza está siempre en mi boca;\n\nmi alma se gloría en el Señor:\n\nque los humildes lo escuchen y se alegren. R/.\n\nProclamad conmigo la grandeza del Señor,\n\nensalcemos juntos su nombre.\n\nYo consulté al Señor, y me respondió,\n\nme libró de todas mis ansias. R/.\n\nContempladlo, y quedaréis radiantes,\n\nvuestro rostro no se avergonzará.\n\nEl afligido invocó al Señor,\n\nél lo escuchó y lo salvó de sus angustias. R/.\n\nEl ángel del Señor acampa en torno a sus fieles\n\ny los protege.\n\nGustad y ved qué bueno es el Señor,\n\ndichoso el que se acoge a él. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (3,16-21)',replace('TANTO amó Dios al mundo, que entregó a su Unigénito, para que todo el que cree en él no perezca, sino que tenga vida eterna.\n\nPorque Dios no envió a su Hijo al mundo para juzgar al mundo, sino para que el mundo se salve por él.\n\nEl que cree en él no será juzgado; el que no cree ya está juzgado, porque no ha creído en el nombre del Unigénito de Dios.\n\nEste es el juicio: que la luz vino al mundo, y los hombres prefirieron la tiniebla a la luz, porque sus obras eran malas. Pues todo el que obra el mal detesta la luz, y no se acerca a la luz, para no verse acusado por sus obras.\n\nEn cambio, el que obra la verdad se acerca a la luz, para que se vea que sus obras están hechas según Dios.','\n',char(10)),'2026-04-07 00:25:04','2026-04-07 00:25:04');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(140,'2026-04-09',NULL,'Jueves de la Octava de Pascua','Lectura del libro de los Hechos de los apóstoles (3,11-26)',replace('EN aquellos días, mientras el paralítico curado seguía aún con Pedro y Juan, todo el pueblo, asombrado, acudió corriendo al pórtico llamado de Salomón, donde estaban ellos.\n\nAl verlo, Pedro dirigió la palabra a la gente:\n\n«Israelitas, ¿por qué os admiráis de esto? ¿Por qué nos miráis como si hubiéramos hecho andar a este con nuestro propio poder o virtud? El Dios de Abrahán, de Isaac y de Jacob, el Dios de nuestros padres, ha glorificado a su siervo Jesús, al que vosotros entregasteis y de quien renegasteis ante Pilato, cuando había decidido soltarlo.\n\nVosotros renegasteis del Santo y del Justo, y pedisteis el indulto de un asesino; matasteis al autor de la vida, pero Dios Jo resucitó de entre los muertos, y nosotros somos testigos de ello.\n\nPor la fe en su nombre, este, que veis aquí y que conocéis, ha recobrado el vigor por medio de su nombre; la fe que viene por medio de él le ha restituido completamente la salud, a la vista de todos vosotros.\n\nAhora bien, hermanos, sé que Jo hicisteis por ignorancia, al igual que vuestras autoridades; pero Dios cumplió de esta manera lo que había predicho por los profetas, que su Mesías tenía que padecer.\n\nPor tanto, arrepentíos y convertíos, para que se borren vuestros pecados; para que vengan tiempos de consuelo de parte de Dios, y envíe a Jesús, el Mesías que os estaba destinado, al que debe recibir el cielo hasta el tiempo de la restauración universal, de la que Dios habló desde antiguo por boca de sus santos profetas.\n\nMoisés dijo: “El Señor Dios vuestro hará surgir de entre vuestros hermanos un profeta como yo: escuchadle todo lo que os diga; y quien no escuche a ese profeta será excluido del pueblo”. Y, desde Samuel en adelante, todos los profetas que hablaron anunciaron también estos días.\n\nVosotros sois los hijos de los profetas, los hijos de la alianza que hizo Dios con vuestros padres, cuando le dijo a Abrahán: “En tu descendencia serán bendecidas todas las familias de la tierra”. Dios resucitó a su Siervo y os lo envía en primer lugar a vosotros para que os traiga la bendición, apartándoos a cada uno de vuestras maldades».','\n',char(10)),'Sal 8,2',replace('R/. Señor, dueño nuestro\n\n¡que admirable es tu nombre en toda la tierra!\n\nSeñor, Dios nuestro,\n\n¿qué es el hombre para que te acuerdes de él,\n\nel ser humano, para mirar por él?  R/.\n\nLo hiciste poco inferior a los ángeles,\n\nlo coronaste de gloria y dignidad,\n\nle diste el mando sobre las obras de tus manos.\n\nTodo lo sometiste bajo sus pies.  R/.\n\nRebaños de ovejas y toros,\n\ny hasta las bestias del campo,\n\nlas aves del cielo, los peces del mar,\n\nque trazan sendas por el mar.   R/.\n\nSecuencia\n\n(Opcional)\n\nOfrezcan los cristianos\n\nofrendas de alabanza\n\na gloria de la Víctima\n\npropicia de la Pascua.\n\nCordero sin pecado\n\nque a las ovejas salva,\n\na Dios y a los culpables\n\nunió con nueva alianza.\n\nLucharon vida y muerte\n\nen singular batalla,\n\ny, muerto el que es la Vida,\n\ntriunfante se levanta.\n\n«¿Qué has visto de camino,\n\nMaría, en la mañana?»\n\n«A mi Señor glorioso,\n\nla tumba abandonada,\n\nlos ángeles testigos,\n\nsudarios y mortaja.\n\n¡Resucitó de veras\n\nmi amor y mi esperanza!\n\nVenid a Galilea,\n\nallí el Señor aguarda;\n\nallí veréis los suyos\n\nla gloria de la Pascua.»\n\nPrimicia de los muertos,\n\nsabemos por tu gracia\n\nque estás resucitado;\n\nla muerte en ti no manda.\n\nRey vencedor, apiádate\n\nde la miseria humana\n\ny da a tus fieles parte\n\nen tu victoria santa.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Lucas (24,35-48)',replace('EN aquel tiempo, los discípulos de Jesús contaron lo que les había pasado por el camino y cómo lo habían reconocido al partir el pan.\n\nEstaban hablando de estas cosas, cuando él se presentó en medio de ellos y les dice:\n\n«Paz a vosotros».\n\nPero ellos, aterrorizados y llenos de miedo, creían ver un espíritu.\n\nY él les dijo:\n\n«¿Por qué os alarmáis?, ¿por qué surgen dudas en vuestro corazón? Mirad mis manos y mis pies: soy yo en persona. Palpadme y daos cuenta de que un espíritu no tiene carne y huesos, como veis que yo tengo».\n\nDicho esto, les mostró las manos y los pies. Pero como no acababan de creer por la alegría, y seguían atónitos, les dijo:\n\n«¿Tenéis ahí algo de comer?».\n\nEllos le ofrecieron un trozo de pez asado. Él lo tomó y comió delante de ellos.\n\nY les dijo:\n\n«Esto es lo que os dije mientras estaba con vosotros: que era necesario que se cumpliera todo lo escrito en la Ley de Moisés y en los Profetas y Salmos acerca de mí».\n\nEntonces les abrió el entendimiento para comprender las Escrituras.\n\nY les dijo:\n\n«Así está escrito: el Mesías padecerá, resucitará de entre los muertos al tercer día y en su nombre se proclamará la conversión para el perdón de los pecados a todos los pueblos, comenzando por Jerusalén. Vosotros sois testigos de esto».','\n',char(10)),'2026-04-09 20:15:20','2026-04-09 20:15:20');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(142,'2026-04-19',NULL,'III Domingo de Pascua','Lectura del libro de los Hechos de los Apóstoles (2,14.22-33)',replace('EL día de Pentecostés Pedro, poniéndose en pie junto a los Once, levantó su voz y con toda solemnidad declaró:\n\n«Judíos y vecinos todos de Jerusalén, enteraos bien y escuchad atentamente mis palabras.\n\nA Jesús el Nazareno, varón acreditado por Dios ante vosotros con los milagros, prodigios y signos que Dios realizó por medio de él, como vosotros mismos sabéis, a este, entregado conforme al plan que Dios tenía establecido y previsto, lo matasteis, clavándolo a una cruz por manos de hombres inicuos. Pero Dios lo resucitó, librándolo de los dolores de la muerte, por cuanto no era posible que esta lo retuviera bajo su dominio, pues David dice, refiriéndose a él:\n\n“Veía siempre al Señor delante de mí,\n\npues está a mi derecha para que no vacile.\n\nPor eso se me alegró el corazón,\n\nexultó mi lengua,\n\ny hasta mi carne descansará esperanzada.\n\nPorque no me abandonarás en el lugar de los muertos,\n\nni dejarás que tu Santo experimente corrupción.\n\nMe has enseñado senderos de vida,\n\nme saciarás de gozo con tu rostro”.\n\nHermanos, permitidme hablaros con franqueza: el patriarca David murió y lo enterraron, y su sepulcro está entre nosotros hasta el día de hoy. Pero como era profeta y sabía que Dios “le había jurado con juramento sentar en su trono a un descendiente suyo”, previéndolo, habló de la resurrección del Mesías cuando dijo que “no lo abandonará en el lugar de los muertos” y que “su carne no experimentará corrupción”. A este Jesús lo resucitó Dios, de lo cual todos nosotros somos testigos.\n\nExaltado, pues, por la diestra de Dios y habiendo recibido del Padre la promesa del Espíritu Santo, lo ha derramado. Esto es lo que estáis viendo y oyendo».','\n',char(10)),'Sal 15,1-2.5.7-8.9-10.11',replace('R/. Señor, me enseñarás el sendero de la vida\n\nProtégeme, Dios mío, que me refugio en ti.\n\nYo digo al Señor: «Tú eres mi Dios».\n\nEl Señor es el lote de mi heredad y mi copa,\n\nmi suerte está en tu mano. R/.\n\nBendeciré al Señor, que me aconseja,\n\nhasta de noche me instruye internamente.\n\nTengo siempre presente al Señor,\n\ncon él a mi derecha no vacilaré. R/.\n\nPor eso se me alegra el corazón,\n\nse gozan mis entrañas,\n\ny mi carne descansa esperanzada.\n\nPorque no me abandonarás en la región de los muertos,\n\nni dejarás a tu fiel ver la corrupción. R/.\n\nMe enseñarás el sendero de la vida,\n\nme saciarás de gozo en tu presencia,\n\nde alegría perpetua a tu derecha. R/.','\n',char(10)),'Lectura de la primera carta del apóstol san Pedro (1,17-21)',replace('QUERIDOS hermanos:\n\nPuesto que podéis llamar Padre al que juzga imparcialmente según las obras de cada uno, comportaos con temor durante el tiempo de vuestra peregrinación, pues ya sabéis que fuisteis liberados de vuestra conducta inútil, heredada de vuestros padres, pero no con algo corruptible, con oro o plata, sino con una sangre preciosa, como la de un cordero sin defecto y sin mancha, Cristo, previsto ya antes de la creación del mundo y manifestado en los últimos tiempos por vosotros, que, por medio de él, creéis en Dios, que lo resucitó de entre los muertos y le dio gloria, de manera que vuestra fe y vuestra esperanza estén puestas en Dios.','\n',char(10)),'Lectura del santo evangelio según san Lucas (24,13-35)',replace('AQUEL mismo día (el primero de la semana), dos de los discípulos de Jesús iban caminando a una aldea llamada Emaús, distante de Jerusalén unos sesenta estadios;\n\niban conversando entre ellos de todo lo que había sucedido. Mientras conversaban y discutían, Jesús en persona se acercó y se puso a caminar con ellos. Pero sus ojos no eran capaces de reconocerlo.\n\nÉl les dijo:\n\n«¿Qué conversación es esa que traéis mientras vais de camino?».\n\nEllos se detuvieron con aire entristecido, Y uno de ellos, que se llamaba Cleofás, le respondió:\n\n«Eres tú el único forastero en Jerusalén que no sabes lo que ha pasado allí estos días?».\n\nÉl les dijo:\n\n«¿Qué?».\n\nEllos le contestaron:\n\n«Lo de Jesús el Nazareno, que fue un profeta poderoso en obras y palabras, ante Dios y ante todo el pueblo; cómo lo entregaron los sumos sacerdotes y nuestros jefes para que lo condenaran a muerte, y lo crucificaron. Nosotros esperábamos que él iba a liberar a Israel, pero, con todo esto, ya estamos en el tercer día desde que esto sucedió. Es verdad que algunas mujeres de nuestro grupo nos han sobresaltado, pues habiendo ido muy de mañana al sepulcro, y no habiendo encontrado su cuerpo, vinieron diciendo que incluso habían visto una aparición de ángeles, que dicen que está vivo. Algunos de los nuestros fueron también al sepulcro y lo encontraron como habían dicho las mujeres; pero a él no lo vieron».\n\nEntonces él les dijo:\n\n«¡Qué necios y torpes sois para creer lo que dijeron los profetas! ¿No era necesario que el Mesías padeciera esto y entrara así en su gloria?».\n\nY, comenzando por Moisés y siguiendo por todos los profetas, les explicó lo que se refería a él en todas las Escrituras.\n\nLlegaron cerca de la aldea adonde iban y él simuló que iba a seguir caminando; pero ellos lo apremiaron, diciendo:\n\n«Quédate con nosotros, porque atardece y el día va de caída».\n\nY entró para quedarse con ellos. Sentado a la mesa con ellos, tomó el pan, pronunció la bendición, lo partió y se lo iba dando. A ellos se les abrieron los ojos y lo reconocieron.\n\nPero él desapareció de su vista.\n\nY se dijeron el uno al otro:\n\n«¿No ardía nuestro corazón mientras nos hablaba por el camino y nos explicaba las Escrituras?».\n\nY, levantándose en aquel momento, se volvieron a Jerusalén, donde encontraron reunidos a los Once con sus compañeros, que estaban diciendo:\n\n«Era verdad, ha resucitado el Señor y se ha aparecido a Simón».\n\nY ellos contaron lo que les había pasado por el camino y cómo lo habían reconocido al partir el pan.','\n',char(10)),'2026-04-19 14:29:21','2026-04-19 14:29:21');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(144,'2026-04-20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 00:30:37','2026-04-21 00:30:37');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(145,'2026-04-21',NULL,'Martes de la III Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (7,51–8,1a)',replace('EN aquellos días, dijo Esteban al pueblo y a los ancianos y escribas:\n\n«¡Duros de cerviz, incircuncisos de corazón y de oídos! Vosotros siempre resistís al Espíritu Santo, lo mismo que vuestros padres. ¿Hubo un profeta que vuestros padres no persiguieran? Ellos mataron a los que anunciaban la venida del Justo, y ahora vosotros lo habéis traicionado y asesinado; recibisteis la ley por mediación de ángeles y no la habéis observado».\n\nOyendo sus palabras se recomían en sus corazones y rechinaban los dientes de rabia. Esteban, lleno de Espíritu Santo, fijando la mirada en el cielo, vio la gloria de Dios, y a Jesús de pie a la derecha de Dios, y dijo:\n\n«Veo los cielos abiertos y al Hijo del hombre de pie a la derecha de Dios».\n\nDando un grito estentóreo, se taparon los oídos; y, como un solo hombre, se abalanzaron sobre él, lo empujaron fuera de la ciudad y se pusieron a apedrearlo. Los testigos dejaron sus capas a los pies de un joven llamado Saulo y se pusieron a apedrear a Esteban, que repetía esta invocación:\n\n«Señor Jesús, recibe mi espíritu».\n\nLuego, cayendo de rodillas y clamando con voz potente, dijo:\n\n«Señor, no les tengas en cuenta este pecado».\n\nY, con estas palabras, murió.\n\nSaulo aprobaba su ejecución.','\n',char(10)),'Sal 30,3',replace('R/. A tus manos, Señor, encomiendo mi espíritu\n\nSé la roca de mi refugio,\n\nun baluarte donde me salve,\n\ntú que eres mi roca y mi baluarte;\n\npor tu nombre dirígeme y guíame. R/.\n\nA tus manos encomiendo mi espíritu:\n\ntú, el Dios leal, me librarás.\n\nYo confío en el Señor.\n\nTu misericordia sea mi gozo y mi alegría. R/.\n\nHaz brillar tu rostro sobre tu siervo,\n\nsálvame por tu misericordia.\n\nEn el asilo de tu presencia los escondes\n\nde las conjuras humanas. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (6,30-35)',replace('EN aquel tiempo, el gentío dijo a Jesús:\n\n«¿Y qué signo haces tú, para que veamos y creamos en ti? ¿Cuál es tu obra? Nuestros padres comieron el maná en el desierto, como está escrito: “Pan del cielo les dio a comer”».\n\nJesús les replicó: «En verdad, en verdad os digo: no fue Moisés quien os dio pan del cielo, sino que es mi Padre el que os da el verdadero pan del cielo. Porque el pan de Dios es el que baja del cielo y da vida al mundo».\n\nEntonces le dijeron: «Señor, danos siempre de este pan».\n\nJesús les contestó: «Yo soy el pan de vida. El que viene a mí no tendrá hambre, y el que cree en mí no tendrá sed jamás».','\n',char(10)),'2026-04-21 00:30:40','2026-04-21 00:30:40');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(149,'2026-04-22',NULL,'Miércoles de la III Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (8,1b-8)','Aquel día, se desató una violenta persecución contra la Iglesia de Jerusalén; todos, menos los apóstoles, se dispersaron por Judea y Samaria. Unos hombres piadosos enterraron a Esteban e hicieron gran duelo por él. Saulo se ensañaba con la Iglesia; penetraba en las casas y arrastraba a la cárcel a hombres y mujeres. Al ir de un lugar para otro, los prófugos iban difundiendo el Evangelio. Felipe bajó a la ciudad de Samaria y predicaba allí a Cristo. El gentío escuchaba con aprobación lo que decía Felipe, porque habían oído hablar de los signos que hacía, y los estaban viendo: de muchos poseídos salían los espíritus inmundos lanzando gritos, y muchos paralíticos y lisiados se curaban. La ciudad se llenó de alegría.','Sal 65,1-3',replace('R/. Aclamad al Señor, tierra entera\n\nAclamad al Señor, tierra entera;\n\ntocad en honor de su nombre,\n\ncantad himnos a su gloria.\n\nDecid a Dios: «¡Qué terribles son tus obras!» R/.\n\nQue se postre ante ti la tierra entera,\n\nque toquen en tu honor,\n\nque toquen para tu nombre.\n\nVenid a ver las obras de Dios,\n\nsus temibles proezas en favor de los hombres. R/.\n\nTransformó el mar en tierra firme,\n\na pie atravesaron el río.\n\nAlegrémonos con Dios,\n\nque con su poder gobierna enteramente. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (6,35-40)','En aquel tiempo, dijo Jesús a la gente: «Yo soy el pan de la vida. El que viene a mí no pasará hambre, y el que cree en mí nunca pasará sed; pero, como os he dicho, me habéis visto y no creéis. Todo lo que me da el Padre vendrá a mí, y al que venga a mí no lo echaré afuera, porque he bajado del cielo, no para hacer mi voluntad, sino la voluntad del que me ha enviado. Ésta es la voluntad del que me ha enviado: que no pierda nada de lo que me dio, sino que lo resucite en el último día. Esta es la voluntad de mi Padre: que todo el que ve al Hijo y cree en él tenga vida eterna, y yo lo resucitaré en el último día.»','2026-04-21 00:30:41','2026-04-21 00:30:41');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(150,'2026-04-23',NULL,'Jueves de la III Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (8,26-40)',replace('EN aquellos días, un ángel del Señor habló a Felipe y le dijo:\n\n«Levántate y marcha hacia el sur, por el camino de Jerusalén a Gaza, que está desierto».\n\nSe levantó, se puso en camino y, de pronto, vio venir a un etíope; era un eunuco, ministro de Candaces, reina de Etiopía e intendente del tesoro, que había ido a Jerusalén para adorar. Iba de vuelta, sentado en su carroza, leyendo al profeta Isaías.\n\nEl Espíritu dijo a Felipe:\n\n«Acércate y pégate a la carroza».\n\nFelipe se acercó corriendo, le oyó leer el profeta Isaías, y le preguntó:\n\n«¿Entiendes lo que estás leyendo?».\n\nContestó:\n\n«Y cómo voy a entenderlo si nadie me guía?».\n\nE invitó a Felipe a subir y a sentarse con él. El pasaje de la Escritura que estaba leyendo era este:\n\n«Como cordero fue llevado al matadero,\n\ncomo oveja muda ante el esquilador,\n\nasí no abre su boca.\n\nEn su humillación no se le hizo justicia.\n\n¿Quién podrá contar su descendencia?\n\nPues su vida ha sido arrancada de la tierra».\n\nEl eunuco preguntó a Felipe:\n\n«Por favor, ¿de quién dice esto el profeta?; ¿de él mismo o de otro?».\n\nFelipe se puso a hablarle y, tomando píe de este pasaje, le anunció la Buena Nueva de Jesús. Continuando el camino, llegaron a un sitio donde había agua, y dijo el eunuco:\n\n«Mira, agua. ¿Qué dificultad hay en que me bautice?».\n\nMandó parar la carroza, bajaron los dos al agua, Felipe y el eunuco, y lo bautizó. Cuando salieron del agua, el Espíritu del Señor arrebató a Felipe. El eunuco no volvió a verlo, y siguió su camino lleno de alegría.\n\nFelipe se encontró en Azoto y fue anunciando la Buena Nueva en todos los poblados hasta que llegó a Cesarea.','\n',char(10)),'Sal 65,8-9.16-17.20',replace('R/. Aclamad al Señor, tierra entera\n\nBendecid, pueblos, a nuestro Dios,\n\nhaced resonar sus alabanzas,\n\nporque él nos ha devuelto la vida\n\ny no dejó que tropezaran nuestros pies. R/.\n\nLos que teméis a Dios, venid a escuchar,\n\nos contaré lo que ha hecho conmigo:\n\na él gritó mi boca\n\ny lo ensalzó mi lengua. R/.\n\nBendito sea Dios, que no rechazó mi súplica\n\nni me retiró su favor. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (6,44-51)',replace('EN aquel tiempo, dijo Jesús al gentío:\n\n«Nadie puede venir a mí si no lo atrae el Padre que me ha enviado, Y yo lo resucitaré en el último día.\n\nEstá escrito en los profetas: “Serán todos discípulos de Dios”. Todo el que escucha al Padre y aprende, viene a mí.\n\nNo es que alguien haya visto al Padre, a no ser el que está junto a Dios: ese ha visto al Padre. En verdad, en verdad os digo: el que cree tiene vida eterna.\n\nYo soy el pan de la vida. Vuestros padres comieron en el desierto el maná y murieron; este es el pan que baja del cielo, para que el hombre coma de él y no muera.\n\nYo soy el pan vivo que ha bajado del cielo; el que coma de este pan vivirá para siempre.\n\nY el pan que yo daré es mi carne por la vida del mundo».','\n',char(10)),'2026-04-23 20:57:21','2026-04-23 20:57:21');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(151,'2026-04-24',NULL,'Viernes de la III Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (9,1-20)',replace('EN aquellos días, Saulo, respirando todavía amenazas de muerte contra los discípulos del Señor, se presentó al sumo sacerdote y le pidió cartas para las sinagogas de Damasco, autorizándolo a traerse encadenados a Jerusalén a los que descubriese que pertenecían al Camino, hombres y mujeres.\n\nMientras caminaba, cuando ya estaba cerca de Damasco, de repente una luz celestial lo envolvió con su resplandor. Cayó a tierra y oyó una voz que le decía:\n\n«Saulo, Saulo, ¿por qué me persigues?».\n\nDijo él:\n\n«¿Quién eres, Señor?».\n\nRespondió:\n\n«Soy Jesús, a quien tú persigues. Pero levántate, entra en la ciudad, y allí se te dirá lo que tienes que hacer».\n\nSus compañeros de viaje se quedaron mudos de estupor, porque oían la voz, pero no veían a nadie. Saulo se levantó del suelo, y, aunque tenía los ojos abiertos, no veía nada. Lo llevaron de la mano hasta Damasco. Allí estuvo tres días ciego, sin comer ni beber.\n\nHabía en Damasco un discípulo, que se llamaba Ananías. El Señor lo llamó en una visión:\n\n«Ananías».\n\nRespondió él:\n\n«Aquí estoy, Señor».\n\nEl Señor le dijo:\n\n«Levántate y ve a la calle llamada Recta, y pregunta en casa de Judas por un tal Saulo de Tarso. Mira, está orando, y ha visto en visión a un cierto Ananías que entra y le impone las manos para que recobre la vista».\n\nAnanías contestó:\n\n«Señor, he oído a muchos hablar de ese individuo y del daño que ha hecho a tus santos en Jerusalén, y que aquí tiene autorización de los sumos sacerdotes para llevarse presos a todos los que invocan tu nombre».\n\nEl Señor le dijo:\n\n«Anda, ve; que ese hombre es un instrumento elegido por mí para llevar mi nombre a pueblos y reyes, y a los hijos de Israel. Yo le mostraré lo que tiene que sufrir por mi nombre».\n\nSalió Ananías, entró en la casa, le impuso las manos y dijo:\n\n«Hermano Saulo, el Señor Jesús, que se te apareció cuando venías por el camino, me ha enviado para que recobres la vista y seas lleno de Espíritu Santo».\n\nInmediatamente se le cayeron de los ojos una especie de escamas, y recobró la vista. Se levantó, y fue bautizado. Comió, y recobró las fuerzas.\n\nSe quedó unos días con los discípulos de Damasco, y luego se puso a anunciar en las sinagogas que Jesús es el Hijo de Dios.','\n',char(10)),'Sal 116,1.2',replace('R/. Ir al mundo entero y proclamad el Evangelio\n\nAlabad al Señor, todas las naciones,\n\naclamadlo, todos los pueblos. R/.\n\nFirme es su misericordia con nosotros,\n\nsu fidelidad dura por siempre. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (6,52-59)',replace('EN aquel tiempo, disputaban los judíos entre sí:\n\n«¿Cómo puede este darnos a comer su carne?».\n\nEntonces Jesús les dijo:\n\n«En verdad, en verdad os digo: si no coméis la carne del Hijo del hombre y no bebéis su sangre, no tenéis vida en vosotros. El que come mi carne y bebe mi sangre tiene vida eterna, y yo lo resucitaré en el último día.\n\nMi carne es verdadera comida, y mi sangre es verdadera bebida.\n\nEl que come mi carne y bebe mi sangre habita en mí y yo en él.\n\nComo el Padre que vive me ha enviado, y yo vivo por el Padre, así, del mismo modo, el que me come vivirá por mí.\n\nEste es el pan que ha bajado del cielo: no como el de vuestros padres, que lo comieron y murieron; el que come este pan vivirá para siempre».\n\nEsto lo dijo Jesús en la sinagoga, cuando enseñaba en Cafarnaún.','\n',char(10)),'2026-04-23 20:57:32','2026-04-23 20:57:32');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(152,'2026-04-25',NULL,'San Marcos, evangelista','Lectura de la primera carta del apóstol san Pedro (5,5b-14)','Tened sentimientos de humildad unos con otros, porque Dios resiste a los soberbios, pero da su gracia a los humildes. Inclinaos, pues, bajo la mano poderosa de Dios, para que, a su tiempo, os ensalce. Descargad en él todo vuestro agobio, que él se interesa por vosotros. Sed sobrios, estad alerta, que vuestro enemigo, el diablo, como león rugiente, ronda buscando a quién devorar. Resistidle firmes en la fe, sabiendo que vuestros hermanos en el mundo entero pasan por los mismos sufrimientos. Tras un breve padecer, el mismo Dios de toda gracia, que os ha llamado en Cristo a su eterna gloria, os restablecerá, os afianzará, os robustecerá. Suyo es el poder por los siglos. Amén. Os he escrito esta breve carta por mano de Silvano, al que tengo por hermano fiel, para exhortaros y atestiguaros que ésta es la verdadera gracia de Dios. Manteneos en ella. Os saluda la comunidad de Babilonia, y también Marcos, mi hijo. Saludaos entre vosotros con el beso del amor fraterno. Paz a todos vosotros, los cristianos.','Sal 88,2-3.6-7.16-17',replace('R/. Cantaré eternamente tus misericordias, Señor\n\nCantaré eternamente las misericordias del Señor,\n\nanunciaré tu fidelidad por todas las edades.\n\nPorque dije: «Tu misericordia es un edificio eterno,\n\nmás que el cielo has afianzado tu fidelidad.» R/.\n\nEl cielo proclama tus maravillas, Señor,\n\ny tu fidelidad, en la asamblea de los ángeles.\n\n¿Quién sobre las nubes se compara a Dios?\n\n¿Quién como el Señor entre los seres divinos? R/.\n\nDichoso el pueblo que sabe aclamarte:\n\ncaminará, oh Señor, a la luz de tu rostro;\n\ntu nombre es su gozo cada día,\n\ntu justicia es su orgullo. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Marcos (16,15-20)',replace('En aquel tiempo, se apareció Jesús a los Once y les dijo: «ld al mundo entero y proclamad el Evangelio a toda la creación. El que crea y se bautice se salvará; el que se resista a creer será condenado. A los que crean, les acompañarán estos signos: echarán demonios en mi nombre, hablarán lenguas nuevas, cogerán serpientes en sus manos y, si beben un veneno mortal, no les hará daño. Impondrán las manos a los enfermos, y quedarán sanos.»\n\nDespués de hablarles, el Señor Jesús subió al cielo y se sentó a la derecha de Dios. Ellos se fueron a pregonar el Evangelio por todas partes, y el Señor cooperaba confirmando la palabra con las señales que los acompañaban.','\n',char(10)),'2026-04-23 20:57:41','2026-04-23 20:57:41');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(154,'2026-05-03',NULL,'V Domingo de Pascua','Lectura del libro de los Hechos de los apóstoles (6,1-7)',replace('EN aquellos días, al crecer el número de los discípulos, los de lengua griega se quejaron contra los de lengua hebrea, porque en el servicio diario no se atendía a sus viudas. Los Doce, convocando a la asamblea de los discípulos, dijeron:\n\n«No nos parece bien descuidar la palabra de Dios para ocuparnos del servicio de las mesas. Por tanto, hermanos, escoged a siete de vosotros, hombres de buena fama, llenos de espíritu y de sabiduría, y los encargaremos de esta tarea; nosotros nos dedicaremos a la oración y al servicio de la palabra».\n\nLa propuesta les pareció bien a todos y eligieron a Esteban, hombre lleno de fe y de Espíritu Santo; a Felipe, Prócoro, Nicanor, Timón, Parmenas y Nicolás, prosélito de Antioquía. Se los presentaron a los apóstoles y ellos les impusieron las manos orando.\n\nLa palabra de Dios iba creciendo y en Jerusalén se multiplicaba el número de discípulos; incluso muchos sacerdotes aceptaban la fe.','\n',char(10)),'Sal 32,1-2.4-5.18-19',replace('R/. Que tu misericordia, Señor, venga sobre nosotros, como lo esperamos de ti\n\nAclamad, justos, al Señor,\n\nque merece la alabanza de los buenos.\n\nDad gracias al Señor con la cítara,\n\ntocad en su honor el arpa de diez cuerdas.   R/.\n\nLa palabra del Señor es sincera,\n\ny todas sus acciones son leales;\n\nél ama la justicia y el derecho,\n\ny su misericordia llena la tierra.   R/.\n\nLos ojos del Señor están puestos en quien lo teme,\n\nen los que esperan en su misericordia,\n\npara librar sus vidas de la muerte\n\ny reanimarlos en tiempo de hambre.   R/. R/.','\n',char(10)),'Lectura de la primera carta del apóstol san Pedro (2,4-9)',replace('QUERIDOS hermanos:\n\nAcercándoos al Señor, piedra viva rechazada por los hombres, pero elegida y preciosa para Dios, también vosotros, como piedras vivas, entráis en la construcción de una casa espiritual para un sacerdocio santo, a fin de ofrecer sacrificios espirituales agradables a Dios por medio de Jesucristo.\n\nPor eso se dice en la Escritura:\n\n«Mira, pongo en Sion una piedra angular, elegida y preciosa;\n\nquien cree en ella no queda defraudado».\n\nPara vosotros, pues, los creyentes, ella es el honor, pero para los incrédulos «la piedra que desecharon los arquitectos es ahora la piedra angular», y también «piedra de choque y roca de estrellarse»; y ellos chocan al despreciar la palabra. A eso precisamente estaban expuestos.\n\nVosotros, en cambio, sois un linaje elegido, un sacerdocio real, una nación santa, un pueblo adquirido por Dios para que anunciéis las proezas del que os llamó de las tinieblas a su luz maravillosa.','\n',char(10)),'Lectura del santo evangelio según san Juan (14,1-12)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«No se turbe vuestro corazón, creed en Dios y creed también en mí. En la casa de mi Padre hay muchas moradas; si no, os lo habría dicho, porque me voy a prepararos un lugar. Cuando vaya y os prepare un lugar, volveré y os llevaré conmigo, para que donde estoy yo estéis también vosotros. Y adonde yo voy, ya sabéis el camino».\n\nTomás le dice:\n\n«Señor, no sabemos adónde vas, ¿cómo podemos saber el camino?».\n\nJesús le responde:\n\n«Yo soy el camino y la verdad y la vida. Nadie va al Padre sino por mí. Si me conocierais a mí, conoceríais también a mi Padre. Ahora ya lo conocéis y lo habéis visto».\n\nFelipe le dice:\n\n«Señor, muéstranos al Padre y nos basta».\n\nJesús le replica:\n\n«Hace tanto que estoy con vosotros, ¿y no me conoces, Felipe? Quien me ha visto a mí ha visto al Padre. ¿Cómo dices tú: “Muéstranos al Padre”? ¿No crees que yo estoy en el Padre, y el Padre en mí? Lo que yo os digo no lo hablo por cuenta propia. El Padre, que permanece en mí, él mismo hace las obras. Creedme: yo estoy en el Padre y el Padre en mí. Si no, creed a las obras.\n\nEn verdad, en verdad os digo: el que cree en mí, también él hará las obras que yo hago, y aun mayores, porque yo me voy al Padre».','\n',char(10)),'2026-04-25 20:57:53','2026-04-25 20:57:53');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(155,'2026-04-30',NULL,'Jueves de la IV Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (13,13-25)',replace('PABLO y sus compañeros se hicieron a la mar en Pafos y llegaron a Perge de Panfilia. Juan los dejo y se volvio a Jerusalén; ellos, en cambio, continuaron y desde Perge llegaron a Antioquía de Pisidia. El sábado entraron en la sinagoga y tomaron asiento. Acabada la lectura de la Ley y de los Profetas, los jefes de la sinagoga les mandaron a unos que les dijeran:\n\n«Hermanos, si tenéis una palabra de exhortación para el pueblo, hablad».\n\nPablo se puso en pie y, haciendo seña con la mano de que se callaran, dijo:\n\n«Israelitas y los que teméis a Dios, escuchad: El Dios de este pueblo, Israel, eligió a nuestros padres y multiplicó al pueblo cuando vivían como forasteros en Egipto. Los sacó de allí con brazo poderoso; unos cuarenta años “los cuidó en el desierto”, “aniquiló siete naciones en la tierra de Canaán y les dio en herencia” su territorio; todo ello en el espacio de unos cuatrocientos cincuenta años. Luego les dio jueces hasta el profeta Samuel. Después pidieron un rey, y Dios les dio a Saúl, hijo de Quis, de la tribu de Benjamín, durante cuarenta años. Lo depuso y les suscitó como rey a David, en favor del cual dio testimonio, diciendo: “Encontré a David”, hijo de Jesé, “hombre conforme a mi corazón, que cumplirá todos mis preceptos”.\n\nSegún lo prometido, Dios sacó de su descendencia un salvador para Israel: Jesús. Juan predicó a todo Israel un bautismo de conversión antes de que llegara Jesús; y, cuando Juan estaba para concluir el curso de su vida, decía: “Yo no soy quien pensáis, pero, mirad, viene uno detrás de mí a quien no merezco desatarle las sandalias de los pies”».','\n',char(10)),'Sal 88,2-3.21-22.25.27',replace('R/. Cantaré eternamente tus misericordias, Señor\n\nCantaré eternamente las misericordias del Señor,\n\nanunciaré tu fidelidad por todas las edades.\n\nPorque dijieste: «La misericordia es un edificio eterno»,\n\nmás que el cielo has afianzado tu fidelidad. R/.\n\nEncontré a David, mi siervo,\n\ny lo he ungido con óleo sagrado;\n\npara que mi mano esté siempre con él\n\ny mi brazo lo haga valeroso. R/.\n\nMi fidelidad y misericordia lo acompañarán,\n\npor mi nombre crecerá su poder.\n\nÉl me invocará: «Tú eres mi padre,\n\nmi Dios, mi Roca salvadora». R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (13,16-20)',replace('CUANDO Jesús terminó de lavar los pies a sus discípulos les dijo:\n\n«En verdad, en verdad os digo: el criado no es más que su amo, ni el enviado es más que el que lo envía. Puesto que sabéis esto, dichosos vosotros si lo ponéis en práctica. No lo digo por todos vosotros; yo sé bien a quiénes he elegido, pero tiene que cumplirse la Escritura: “El que compartía mi pan me ha traicionado”. Os lo digo ahora, antes de que suceda, para que cuando suceda creáis que yo soy.\n\nEn verdad, en verdad os digo: el que recibe a quien yo envíe me recibe a mí; y el que me recibe a mí recibe al que me ha enviado».','\n',char(10)),'2026-04-25 20:57:53','2026-04-25 20:57:53');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(156,'2026-04-28',NULL,'Martes de la IV Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (11,19-26)',replace('EN aquellos días, los que se habían dispersado en la persecución provocada por lo de Esteban llegaron hasta Fenicia, Chipre y Antioquía, sin predicar la palabra más que a los judíos. Pero algunos, naturales de Chipre y de Cirene, al llegar a Antioquía, se pusieron a hablar también a los griegos, anunciándoles la Buena Nueva del Señor Jesús. Como la mano del Señor estaba con ellos, gran número creyó y se convirtió al Señor.\n\nLlegó la noticia a oídos de la Iglesia de Jerusalén, y enviaron a Bernabé a Antioquía; al llegar y ver la acción de la gracia de Dios, se alegró y exhortaba a todos a seguir unidos al Señor con todo empeño, porque era un hombre bueno, lleno de Espíritu Santo y de fe. Y una multitud considerable se adhirió al Señor.\n\nBernabé salió para Tarso en busca de Saulo; cuando lo encontró, se lo llevó a Antioquía. Durante todo un año estuvieron juntos en aquella Iglesia e instruyeron a muchos. Fue en Antioquía donde por primera vez los discípulos fueron llamados cristianos.','\n',char(10)),'Sal 86,1-3.4-5.6-7',replace('R/. Alabad al Señor, todas las naciones\n\nÉl la ha cimentado sobre el monte santo;\n\ny el Señor prefiere las puertas de Sión\n\na todas las moradas de Jacob.\n\n¡Qué pregón tan glorioso para ti,\n\nciudad de Dios! R/.\n\n«Contaré a Egipto y a Babilonia\n\nentre mis fieles;\n\nfilisteos, tirios y etíopes\n\nhan nacido allí».\n\nSe dirá de Sión: «Uno por uno\n\nodos han nacido en ella;\n\nel Altísimo en persona la ha fundado». R/.\n\nEl Señor escribirá en el registro de los pueblos:\n\n«Éste ha nacido allí».\n\nY cantarán mientras danzan:\n\n«Todas mis fuentes están en ti». R/.','\n',char(10)),NULL,NULL,'Lectura del evangelio según san Juan (10,22-30)',replace('SE celebraba en Jerusalén la fiesta de la Dedicación del templo. Era invierno, y Jesús se paseaba en el templo por el pórtico de Salomón.\n\nLos judíos, rodeándolo, le preguntaban:\n\n«¿Hasta cuándo nos vas a tener en suspenso? Si tú eres el Mesías, dínoslo francamente».\n\nJesús les respondió:\n\n«Os lo he dicho, y no creéis; las obras que yo hago en nombre de mi Padre, esas dan testimonio de mí. Pero vosotros no creéis, porque no sois de mis ovejas. Mis ovejas escuchan mi voz, y yo las conozco, y ellas me siguen, y yo les doy la vida eterna; no perecerán para siempre, y nadie las arrebatará de mi mano. Lo que mi Padre me ha dado es más que todas las cosas, y nadie puede arrebatar nada de la mano de mi Padre. Yo y el Padre somos uno».','\n',char(10)),'2026-04-25 20:57:53','2026-04-25 20:57:53');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(158,'2026-04-29',NULL,'Miércoles de la IV Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (12,24–13,5)',replace('EN aquellos días, la palabra de Dios iba creciendo y se multiplicaba. Cuando cumplieron su servicio, Bernabé y Saulo se volvieron de Jerusalén, llevándose con ellos a Juan, por sobrenombre Marcos.\n\nEn la Iglesia que estaba en Antioquía había profetas y maestros: Bernabé, Simeón, llamado Níger; Lucio, el de Cirene; Manahén, hermano de leche del tetrarca Herodes, y Saulo.\n\nUn día que estaban celebrando el culto al Señor y ayunaban, dijo el Espíritu Santo:\n\n«Apartadme a Bernabé y a Saulo para la obra a que los he llamado».\n\nEntonces, después de ayunar y orar, les impusieron las manos y los enviaron. Con esta misión del Espíritu Santo, bajaron a Seleucia y de allí zarparon para Chipre.\n\nLlegados a Salamina, anunciaron la palabra de Dios en las sinagogas de los judíos.','\n',char(10)),'Sal 66,2-3.5.6.8',replace('R/. Oh Dios, que te alaben los pueblos,\n\nque todos los pueblos te alaben\n\nQue Dios tenga piedad y nos bendiga,\n\nilumine su rostro sobre nosotros;\n\nconozca la tierra tus caminos,\n\ntodos los pueblos tu salvación. R/.\n\nQue canten de alegría las naciones,\n\nporque riges el mundo con justicia,\n\ny gobiernas las naciones de la tierra. R/.\n\nOh, Dios, que te alaben los pueblos,\n\nque todos los pueblos te alaben.\n\nQue Dios nos bendiga; que le teman\n\ntodos los confines de la tierra. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (12,44-50)',replace('EN aquel tiempo, Jesús gritó diciendo:\n\n«El que cree en mí, no cree en mí, sino en el que me ha enviado. Y el que me ve a mí, ve al que me ha enviado. Yo he venido al mundo como luz, y así, el que cree en mí no quedará en tinieblas.\n\nAl que oiga mis palabras y no las cumpla, yo no lo juzgo, porque no he venido para juzgar al mundo, sino para salvar al mundo. El que me rechaza y no acepta mis palabras tiene quien lo juzgue: la palabra que yo he pronunciado, esa lo juzgará en el último día. Porque yo no he hablado por cuenta mía; el Padre que me envió es quien me ha ordenado lo que he de decir y cómo he de hablar. Y sé que su mandato es vida eterna. Por tanto, lo que yo hablo, lo hablo como me ha encargado el Padre».','\n',char(10)),'2026-04-25 20:57:53','2026-04-25 20:57:53');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(159,'2026-05-01',NULL,'Viernes de la IV Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (13,26-33)',replace('EN aquellos días, cuando llegó Pablo a Antioquía de Pisidia, decía en la sinagoga:\n\n«Hermanos, hijos del linaje de Abrahán y todos vosotros los que teméis a Dios: a nosotros se nos ha enviado esta palabra de salvación. En efecto, los habitantes de Jerusalén y sus autoridades no reconocieron a Jesús ni entendieron las palabras de los profetas que se leen los sábados, pero las cumplieron al condenarlo. Y, aunque no encontraron nada que mereciera la muerte, le pidieron a Pilato que lo mandara ejecutar. Y, cuando cumplieron todo lo que estaba escrito de él, lo bajaron del madero y lo enterraron. Pero Dios lo resucitó de entre los muertos. Durante muchos días, se apareció a los que habían subido con él de Galilea a Jerusalén, y ellos son ahora sus testigos ante el pueblo. También nosotros os anunciamos la Buena Noticia de que la promesa que Dios hizo a nuestros padres, nos la ha cumplido a nosotros, sus hijos, resucitando a Jesús. Así está escrito en el salmo segundo:\n\n“Tú eres mi Hijo: yo te he engendrado hoy”».','\n',char(10)),'Sal 2,6-7.8-9.10-11',replace('R/. Tu eres mi Hijo: yo te he engendrado hoy\n\n«Yo mismo he establecido a mi Rey\n\nen Sión, mi monte santo».\n\nVoy a proclamar el decreto del Señor;\n\nél me ha dicho: «Tú eres mi Hijo:\n\nyo te he engendrado hoy. R/.\n\nPídemelo:\n\nte daré en herencia las naciones,\n\nen posesión, los confines de la tierra:\n\nlos gobernarás con cetro de hierro,\n\nlos quebrarás como jarro de loza». R/.\n\nY ahora, reyes, sed sensatos;\n\nescarmentad, los que regís la tierra:\n\nservid al Señor con temor,\n\nrendidle homenaje temblando. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (14,1-6)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«No se turbe vuestro corazón, creed en Dios y creed también en mí. En la casa de mi Padre hay muchas moradas; si no, os lo habría dicho, porque me voy a prepararos un lugar. Cuando vaya y os prepare un lugar, volveré y os llevaré conmigo, para que donde estoy yo estéis también vosotros. Y adonde yo voy, ya sabéis el camino».\n\nTomás le dice:\n\n«Señor, no sabemos adónde vas, ¿cómo podemos saber el camino?».\n\nJesús le responde:\n\n«Yo soy el camino y la verdad y la vida. Nadie va al Padre sino por mí».','\n',char(10)),'2026-04-25 20:57:53','2026-04-25 20:57:53');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(160,'2026-05-02',NULL,'Sábado de la IV Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (13,44-52)',replace('EL sábado siguiente, casi toda la ciudad acudió a oír la palabra del Señor. Al ver el gentío, los judíos se llenaron de envidia y respondían con blasfemias a las palabras de Pablo. Entonces Pablo y Bernabé dijeron con toda valentía:\n\n«Teníamos que anunciaros primero a vosotros la palabra de Dios; pero como la rechazáis y no os consideráis dignos de la vida eterna, sabed que nos dedicamos a los gentiles. Así nos lo ha mandado el Señor: “Yo te he puesto como luz de los gentiles, para que lleves la salvación hasta el confín de la tierra”».\n\nCuando los gentiles oyeron esto, se alegraron y alababan la palabra del Señor; y creyeron los que estaban destinados a la vida eterna.\n\nLa palabra del Señor se iba difundiendo por toda la región. Pero los judíos incitaron a las señoras distinguidas, adoradoras de Dios, y a los principales de la ciudad, provocaron una persecución contra Pablo y Bernabé y los expulsaron de su territorio.\n\nEstos sacudieron el polvo de los pies contra ellos y se fueron a Iconio. Los discípulos, por su parte, quedaban llenos de alegría y de Espíritu Santo.','\n',char(10)),'Sal 97,1-2',replace('R/. Los confines de la tierra han contemplado\n\nla victoria de nuestro Dios\n\nCantad al Señor un cántico nuevo,\n\nporque ha hecho maravillas.\n\nSu diestra le ha dado la victoria,\n\nsu santo brazo. R/.\n\nEl Señor da a conocer su salvación,\n\nrevela a las naciones su justicia:\n\nse acordó de su misericordia y su fidelidad\n\nen favor de la casa de Israel. R/.\n\nLos confines de la tierra han contemplado\n\nla victoria de nuestro Dios.\n\nAclama al Señor, tierra entera;\n\ngritad, vitoread, tocad. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (14,7-14)',replace('«Si me conocierais a mí, conoceríais también a mi Padre. Ahora ya lo conocéis y lo habéis visto».\n\nFelipe le dice:\n\n«Señor, muéstranos al Padre y nos basta».\n\nJesús le replica:\n\n«Hace tanto que estoy con vosotros, ¿y no me conoces, Felipe? Quien me ha visto a mí ha visto al Padre. ¿Cómo dices tú: “Muéstranos al Padre”? ¿No crees que yo estoy en el Padre, y el Padre en mí? Lo que yo os digo no lo hablo por cuenta propia. El Padre, que permanece en mí, él mismo hace las obras. Creedme: yo estoy en el Padre y el Padre en mí. Si no, creed a las obras.\n\nEn verdad, en verdad os digo: el que cree en mí, también él hará las obras que yo hago, y aun mayores, porque yo me voy al Padre. Y lo que pidáis en mi nombre, yo lo haré, para que el Padre sea glorificado en el Hijo. Si me pedís algo en mi nombre, yo lo haré».','\n',char(10)),'2026-04-25 20:57:53','2026-04-25 20:57:53');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(168,'2026-04-27',NULL,'Lunes de la IV Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (11,1-18)',replace('EN aquellos días, los apóstoles y los hermanos de Judea se enteraron de que también los gentiles habían recibido la palabra de Dios. Cuando Pedro subió a Jerusalén, los de la circuncisión le dijeron en son de reproche:\n\n«Has entrado en casa de incircuncisos y has comido con ellos».\n\nPedro entonces comenzó a exponerles los hechos por su orden, diciendo:\n\n«Estaba yo orando en la ciudad de Jafa, cuando tuve en éxtasis una visión: una especie de recipiente que bajaba, semejante a un gran lienzo que era descolgado del cielo sostenido por los cuatro extremos, hasta donde yo estaba. Miré dentro y vi cuadrúpedos de la tierra, fieras, reptiles y pájaros del cielo. Luego oí una voz que me decía: “Levántate, Pedro, mata y come”. Yo respondí:\n\n«De ningún modo, Señor, pues nunca entró en mi boca cosa profana o impura”. Pero la voz del cielo habló de nuevo: «Lo que Dios ha purificado, tú no lo consideres profano”. Esto sucedió hasta tres veces, y de un tirón lo subieron todo de nuevo al cielo.\n\nEn aquel preciso momento llegaron a la casa donde estábamos tres hombres enviados desde Cesarea en busca mía. Entonces el Espíritu me dijo que me fuera con ellos sin dudar. Me acompañaron estos seis hermanos, y entramos en casa de aquel hombre. Él nos contó que había visto en su casa al ángel que, en pie, le decía: “Manda recado a Jafa y haz venir a Simón, llamado Pedro; él te dirá palabras que traerán la salvación a ti y a tu casa”.\n\nEn cuanto empecé a hablar, bajó sobre ellos el Espíritu Santo, igual que había bajado sobre nosotros al principio; entonces me acordé de lo que el Señor había dicho: “Juan bautizó con agua, pero vosotros seréis bautizados con Espíritu Santo”. Pues, si Dios les ha dado a ellos el mismo don que a nosotros, por haber creído en el Señor Jesucristo, ¿quién era yo para oponerme a Dios?».\n\nOyendo esto, se calmaron y alabaron a Dios diciendo:\n\n«Así pues, también a los gentiles les ha otorgado Dios la conversión que lleva a la vida».','\n',char(10)),'Sal 41,2-3',replace('R/. Mi alma tiene sed de ti, Dios vivo\n\nComo busca la cierva corrientes de agua,\n\nasí mi alma te busca a ti, Dios mío;\n\nmi alma tiene sed de Dios, del Dios vivo:\n\n¿cuándo entraré a ver el rostro de Dios? R/.\n\nEnvía tu luz y tu verdad:\n\nque ellas me guíen\n\ny me conduzcan hasta tu monte santo,\n\nhasta tu morada. R/.\n\nMe acercaré al altar de Dios,\n\nal Dios de mi alegría,\n\ny te daré gracias al son de la cítara,\n\nDios, Dios mío. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (10,1-10)',replace('EN aquel tiempo, dijo Jesús:\n\n«En verdad, en verdad os digo: el que no entra por la puerta en el aprisco de las ovejas, sino que salta por otra parte, ese es ladrón y bandido; pero el que entra por la puerta es pastor de las ovejas. A este le abre el guarda y las ovejas atienden a su voz, y él va llamando por el nombre a sus ovejas y las saca fuera. Cuando ha sacado todas las suyas camina delante de ellas, y las ovejas lo siguen, porque conocen su voz: a un extraño no lo seguirán, sino que huirán de él, porque no conocen la voz de los extraños».\n\nJesús les puso esta comparación, pero ellos no entendieron de qué les hablaba. Por eso añadió Jesús:\n\n«En verdad, en verdad os digo: yo soy la puerta de las ovejas. Todos los que han venido antes de mí son ladrones y bandidos; pero las ovejas no los escucharon.\n\nYo soy la puerta: quien entre por mí se salvará y podrá entrar y salir, y encontrará pastos.\n\nEl ladrón no entra sino para robar y matar y hacer estragos; yo he venido para que tengan vida y la tengan abundante».','\n',char(10)),'2026-04-27 19:46:47','2026-04-27 19:46:47');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(169,'2026-04-26',NULL,'IV Domingo de Pascua','Lectura del libro de los Hechos de los apóstoles (2,14a.36-41)',replace('EL día de Pentecostés Pedro, poniéndose en pie junto a los Once, levantó su voz y declaró:\n\n«Con toda seguridad conozca toda la casa de Israel que al mismo Jesús, a quien vosotros crucificasteis, Dios lo ha constituido Señor y Mesías».\n\nAl oír esto, se les traspasó el corazón, y preguntaron a Pedro y a los demás apóstoles:\n\n«¿Qué tenemos que hacer, hermanos?»\n\nPedro les contestó:\n\n«Convertíos y sea bautizado cada uno de vosotros en el nombre de Jesús, el Mesías, para perdón de vuestros pecados, y recibiréis el don del Espíritu Santo. Porque la promesa vale para vosotros y para vuestros hijos, y para los que están lejos, para cuantos llamare a sí el Señor Dios nuestro».\n\nCon estas y otras muchas razones dio testimonio y los exhortaba diciendo:\n\n«Salvaos de esta generación perversa».\n\nLos que aceptaron sus palabras se bautizaron, y aquel día fueron agregadas unas tres mil personas.','\n',char(10)),'Sal 22,1-3',replace('R/. El Señor es mi pastor, nada me falta\n\nEl Señor es mi pastor, nada me falta:\n\nen verdes praderas me hace recostar;\n\nme conduce hacia fuentes tranquilas\n\ny repara mis fuerzas.   R/.\n\nMe guía por el sendero justo,\n\npor el honor de su nombre.\n\nAunque camine por cañadas oscuras,\n\nnada temo, porque tú vas conmigo:\n\ntu vara y tu cayado me sosiegan.   R/.\n\nPreparas una mesa ante mi,\n\nenfrente de mis enemigos;\n\nme unges la cabeza con perfume,\n\ny mi copa rebosa.   R/.\n\nTu bondad y tu misericordia me acompañan\n\ntodos los días de mi vida,\n\ny habitaré en la casa del Señor\n\npor años sin término.   R/.','\n',char(10)),'Lectura de la primera carta del apóstol san Pedro (2,20-25)',replace('QUERIDOS hermanos:\n\nQue aguantéis cuando sufrís por hacer el bien,\n\neso es una gracia de parte de Dios.\n\nPues para esto habéis sido llamados,\n\nporque también Cristo padeció por vosotros,\n\ndejándoos un ejemplo para que sigáis sus huellas.\n\nÉl no cometió pecado\n\nni encontraron engaño en su boca.\n\nÉl no devolvía el insulto cuando lo insultaban;\n\nsufriendo no profería amenazas;\n\nsino que se entregaba al que juzga rectamente.\n\nÉl llevó nuestros pecados en su cuerpo hasta el leño,\n\npara que, muertos a los pecados, vivamos para la justicia.\n\nCon sus heridas fuisteis curados.\n\nPues andabais errantes como ovejas,\n\npero ahora os habéis convertido\n\nal pastor y guardián de vuestras almas.','\n',char(10)),'Lectura del santo evangelio según san Juan (10,1-10)',replace('EN aquel tiempo, dijo Jesús:\n\n«En verdad, en verdad os digo: el que no entra por la puerta en el aprisco de las ovejas, sino que salta por otra parte, ese es ladrón y bandido; pero el que entra por la puerta es pastor de las ovejas. A este le abre el guarda y las ovejas atienden a su voz, y él va llamando por el nombre a sus ovejas y las saca fuera. Cuando ha sacado todas las suyas camina delante de ellas, y las ovejas lo siguen, porque conocen su voz; a un extraño no lo seguirán, sino que huirán de él, porque no conocen la voz de los extraños».\n\nJesús les puso esta comparación, pero ellos no entendieron de qué les hablaba. Por eso añadió Jesús:\n\n«En verdad, en verdad os digo: yo soy la puerta de las ovejas. Todos los que han venido antes de mí son ladrones y bandidos; pero las ovejas no los escucharon.\n\nYo soy la puerta: quien entre por mí se salvará y podrá entrar y salir, y encontrará pastos.\n\nEl ladrón no entra sino para robar y matar y hacer estragos; yo he venido para que tengan vida y la tengan abundante».','\n',char(10)),'2026-04-27 19:49:28','2026-04-27 19:49:28');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(170,'2026-05-04',NULL,'Lunes de la V Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (14,5-18)',replace('EN aquellos días, cuando en Iconio se produjeron conatos de violencia de parte de los gentiles y de los judíos, con sus autoridades, para maltratar a Pablo y a Bernabé y apedrearlos; al darse cuenta de la situación, huyeron a las ciudades de Licaonia, a Listra y Derbe y alrededores, donde se pusieron a predicar el Evangelio.\n\nHabía en Listra, sentado, un hombre impedido de pies; cojo desde el seno de su madre, nunca había podido andar. Estaba escuchando las palabras de Pablo, y este, fijando en él la vista y viendo que tenía una fe capaz de obtener la salud, le dijo en voz alta:\n\n«Levántate, ponte derecho sobre tus pies».\n\nEl hombre dio un salto y echó a andar. Al ver lo que Pablo había hecho, el gentío exclamó en la lengua de Licaonia:\n\n«Los dioses en figura de hombres han bajado a visitarnos».\n\nA Bernabé lo llamaban Zeus, y a Pablo, Hermes, porque se encargaba de hablar. El sacerdote del templo de Zeus que estaba a la entrada de la ciudad trajo a las puertas toros y guirnaldas y, con la gente, quería ofrecerles un sacrificio.\n\nAl oírlo los apóstoles Bernabé y Pablo, se rasgaron el manto e irrumpieron por medio del gentío, gritando y diciendo:\n\n«Hombres, ¿qué hacéis? También nosotros somos humanos de vuestra misma condición; os anunciamos esta Buena Noticia: que dejéis los ídolos vanos y os convirtáis al Dios vivo “que hizo el cielo, la tierra y el mar y todo lo que contienen”. En las generaciones pasadas, permitió que cada pueblo anduviera su camino; aunque no ha dejado de dar testimonio de sí mismo con sus beneficios, mandándoos desde el cielo la lluvia y las cosechas a sus tiempos, dándoos comida y alegría en abundancia».\n\nCon estas palabras, a dura penas disuadieron al gentío de que les ofrecieran un sacrificio.','\n',char(10)),'Sal 113',replace('R/. No a nosotros, Señor, no a nosotros,\n\nsino a tu nombre da la gloria\n\nNo a nosotros, Señor, no a nosotros,\n\nsino a tu nombre da la gloria,\n\npor tu bondad, por tu lealtad.\n\n¿Por qué han de decir las naciones:\n\n«Dónde está su Dios»? R/.\n\nNuestro Dios está en el cielo,\n\nlo que quiere lo hace.\n\nSus ídolos, en cambio, son plata y oro,\n\nhechura de manos humanas. R/.\n\nBenditos seáis del Señor,\n\nque hizo el cielo y la tierra.\n\nEl cielo pertenece al Señor,\n\nla tierra se la ha dado a los hombres. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (14,21-26)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«El que acepta mis mandamientos y los guarda, ese me ama; al que me ama será amado mi Padre, y yo también lo amaré y me manifestaré a él».\n\nLe dijo Judas, no el Iscariote:\n\n«Señor, ¿qué ha sucedido para que te reveles a nosotros y no al mundo?»\n\nRespondió Jesús y le dijo:\n\n«El que me ama guardará mi palabra, y mi Padre lo amará, y vendremos a él y haremos morada en él.\n\nEl que no me ama no guardará mis palabras. Y la palabra que estáis oyendo no es mía, sino del Padre que me envió.\n\nOs he hablado de esto ahora que estoy a vuestro lado, pero el Paráclito, el Espíritu Santo, que enviará el Padre en mi nombre, será quien os lo enseñe todo y os vaya recordando todo lo que os he dicho».','\n',char(10)),'2026-05-05 01:21:00','2026-05-05 01:21:00');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(171,'2026-05-05',NULL,'Martes de la V Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (14,19-28)',replace('EN aquellos días, llegaron unos judíos de Antioquía y de Iconio y se ganaron a la gente; apedrearon a Pablo y lo arrastraron fuera de la ciudad, dejándolo ya por muerto. Entonces lo rodearon los discípulos; él se levantó y volvió a la ciudad.\n\nAl día siguiente, salió con Bernabé para Derbe. Después de predicar el Evangelio en aquella ciudad y de ganar bastantes discípulos, volvieron a Listra, a Iconio y a Antioquia, animando a los discípulos y exhortándolos a perseverar en la fe, diciéndoles que hay que pasar muchas tribulaciones para entrar en el reino de Dios.\n\nEn cada Iglesia designaban presbíteros, oraban, ayunaban y los encomendaban al Señor, en quien habían creído. Atravesaron Pisidia y llegaron a Panfilia. Y después de predicar la Palabra en Perge, bajaron a Atalía y allí se embarcaron para Antioquia, de donde los habían encomendado a la gracia de Dios para la misión que acababan de cumplir. Al llegar, reunieron a la Iglesia, les contaron lo que Dios había hecho por medio de ellos y cómo había abierto a los gentiles la puerta de la fe. Se quedaron allí bastante tiempo con los discípulos.','\n',char(10)),'Sal 144,10-11.12-13',replace('R/. Que tus fieles, Señor, proclamen la gloria de tu reinado\n\nQue todas tus criaturas te den gracias, Señor,\n\nque te bendigan tus fieles.\n\nQue proclamen la gloria de tu reinado,\n\nque hablen de tus hazañas. R/.\n\nExplicando tus hazañas a los hombres,\n\nla gloria y majestad de tu reinado.\n\nTu reinado es un reinado perpetuo,\n\ntu gobierno va de edad en edad. R/.\n\nPronuncie mi boca la alabanza del Señor,\n\ntodo viviente bendiga su santo nombre\n\npor siempre jamás. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (14,27-31a)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«La paz os dejo, mi paz os doy; no os la doy yo como la da el mundo. Que no turbe vuestro corazón ni se acobarde. Me habéis oído decir: “Me voy y vuelvo a vuestro lado”. Si me amarais, os alegraríais de que vaya al Padre, porque el Padre es más que yo. Os lo he dicho ahora, antes de que suceda, para que cuando suceda creáis.\n\nYa no hablaré mucho con vosotros, pues se acerca el príncipe del mundo; no es que él tenga poder sobre mi, pero es necesario que el mundo comprenda que yo amo al Padre, y que, como el Padre me ha ordenado, así actúo yo».','\n',char(10)),'2026-05-05 01:21:06','2026-05-05 01:21:06');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(172,'2026-05-06',NULL,'Miércoles de la V Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (15,1-6)',replace('EN aquellos días, unos que bajaron de Judea se pusieron a enseñar a los hermanos que, si no se circuncidaban conforme al uso de Moisés, no podían salvarse. Esto provocó un altercado y una violenta discusión con Pablo y Bernabé; y se decidió que Pablo, Bernabé y algunos más de entre ellos subieran a Jerusalén a consultar a los apóstoles y presbíteros sobre esta controversia. Ellos, pues, enviados por la Iglesia provistos de lo necesario, atravesaron Fenicia y Samaría, contando cómo se convertían los gentiles, con lo que causaron gran alegría a todos los hermanos. Al llegar a Jerusalén, fueron acogidos por la Iglesia, los apóstoles y los presbíteros; ellos contaron lo que Dios había hecho con ellos.\n\nPero algunos de la secta de los fariseos, que habían abrazado la fe, se levantaron, diciendo:\n\n«Es necesario circuncidarlos y ordenarles que guarden la ley de Moisés».\n\nLos apóstoles y los presbíteros se reunieron a examinar el asunto.','\n',char(10)),'Sal 121,1-2.4-5',replace('R/. Vamos alegres a la casa del Señor\n\n¡Qué alegría cuando me dijeron:\n\n«Vamos a la casa del Señor»!\n\nYa están pisando nuestro pies\n\ntus umbrales, Jerusalén. R/.\n\nJerusalén está fundada\n\ncomo ciudad bien compacta.\n\nAllá suben las tribus,\n\nlas tribus del Señor. R/.\n\nSegún la costumbre de Israel,\n\na celebrar el nombre del Señor;\n\nen ella están los tribunales de justicia,\n\nen el palacio de David. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (15,1-8)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Yo soy la verdadera vid, y mi Padre es el labrador. A todo sarmiento que no da fruto en mí lo arranca, y a todo el que da fruto lo poda, para que dé más fruto.\n\nVosotros ya estáis limpios por la palabra que os he hablado; permaneced en mí, y yo en vosotros.\n\nComo el sarmiento no puede dar fruto por sí, si no permanece en la vid, así tampoco vosotros, si no permanecéis en mí.\n\nYo soy la vid, vosotros los sarmientos; el que permanece en mí y yo en él, ese da fruto abundante; porque sin mí no podéis hacer nada. Al que no permanece en mí lo tiran fuera, como el sarmiento, y se seca; luego los recogen y los echan al fuego, y arden.\n\nSi permanecéis en mí y mis palabras permanecen en vosotros, pedid lo que deseáis, y se realizará.\n\nCon esto recibe gloria mi Padre, con que deis fruto abundante; así seréis discípulos míos».','\n',char(10)),'2026-05-05 01:21:13','2026-05-05 01:21:13');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(173,'2026-05-07',NULL,'Jueves de la V Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (15,7-21)',replace('EN aquellos días, después de una larga discusión, se levantó Pedro y dijo a los apóstoles y a los presbíteros:\n\n«Hermanos, vosotros sabéis que, desde los primeros días, Dios me escogió entre vosotros para que los gentiles oyeran de mi boca la palabra del Evangelio, y creyeran. Y Dios, que penetra los corazones, ha dado testimonio a favor de ellos dándoles el Espíritu Santo igual que a nosotros. No hizo distinción entre ellos y nosotros, pues ha purificado sus corazones con la fe. ¿Por qué, pues, ahora intentáis tentar a Dios, queriendo poner sobre el cuello de esos discípulos un yugo que ni nosotros ni nuestros padres hemos podido soportar? No; creemos que lo mismo ellos que nosotros nos salvamos por la gracia del Señor Jesús».\n\nToda la asamblea hizo silencio para escuchar a Bernabé y Pablo, que les contaron los signos y prodigios que Dios había hecho por medio de ellos entre los gentiles. Cuando terminaron de hablar, Santiago tomó la palabra y dijo:\n\n«Escuchadme, hermanos: Simón ha contado cómo Dios por primera vez se ha dignado escoger para su nombre un pueblo de entre los gentiles. Con esto concuerdan las palabras de los profetas, como está escrito:\n\n“Después de esto volveré\n\ny levantaré de nuevo la choza caída de David;\n\nlevantaré sus ruinas y la pondré en pie,\n\npara que los demás hombres busquen al Señor,\n\ny todos los gentiles sobre los que ha sido invocado mi nombre:\n\nlo dice el Señor, el que hace que esto sea conocido desde antiguo”.\n\nPor eso, a mi parecer, no hay que molestar a los gentiles que se convierten a Dios; basta escribirles que se abstengan de la contaminación de los ídolos, de las uniones ilegítimas, de animales estrangulados y de la sangre. Porque desde tiempos antiguos Moisés tiene en cada ciudad quienes lo predican, ya que es leído cada sábado en las sinagogas».','\n',char(10)),'Sal 95,1-2',replace('R/. Contad las maravillas del Señor\n\na todas las naciones\n\nCantad al Señor un cántico nuevo,\n\ncantad al Señor, toda la tierra;\n\ncantad al Señor, bendecid su nombre. R/.\n\nProclamad día tras día su victoria.\n\nContad a los pueblos su gloria,\n\nsus maravillas a todas las naciones. R/.\n\nDecid a los pueblos: «El Señor es rey,\n\nél afianzó el orbe, y no se moverá;\n\nél gobierna a los pueblos rectamente». R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (15,9-11)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Como el Padre me ha amado, así os he amado yo; permaneced en mi amor.\n\nSi guardáis mis mandamientos, permaneceréis en mi amor; lo mismo que yo he guardado los mandamientos de mi Padre y permanezco en su amor.\n\nOs he hablado de esto para que mi alegría esté en vosotros, y vuestra alegría llegue a plenitud».','\n',char(10)),'2026-05-05 01:21:19','2026-05-05 01:21:19');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(174,'2026-05-08',NULL,'Viernes de la V Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (15,22-31)',replace('EN aquellos días, los apóstoles y los presbíteros con toda la Iglesia acordaron elegir algunos de ellos para mandarlos a Antioquía con Pablo y Bernabé. Eligieron a Judas, llamado Barsabá, y a Silas, miembros eminentes entre los hermanos, y enviaron por medio de ellos esta carta:\n\n«Los apóstoles y los presbíteros hermanos saludan a los hermanos de Antioquía, Siria y Cilicia provenientes de la gentilidad. Habiéndonos enterado de que algunos de aquí, sin encargo nuestro, os han alborotado con sus palabras, desconcertando vuestros ánimos, hemos decidido, por unanimidad, elegir a algunos y enviároslos con nuestros queridos Bernabé y Pablo, hombres que han entregado su vida al nombre de nuestro Señor Jesucristo. Os mandamos, pues, a Silas y a Judas, que os referirán de palabra lo que sigue: Hemos decidido, el Espíritu Santo y nosotros, no imponeros más cargas que las indispensables: que os abstengáis de carne sacrificada a los ídolos, de sangre, de animales estrangulados y de uniones ilegítimas. Haréis bien en apartaros de todo esto. Saludos».\n\nLos despidieron, y ellos bajaron a Antioquía, donde reunieron a la comunidad y entregaron la carta. Al leerla, se alegraron mucho por aquellas palabras alentadoras.','\n',char(10)),'Sal 56,8-9.10-12',replace('R/. Te daré gracias ante los pueblos, Señor\n\nMi corazón está firme, Dios mío,\n\nmi corazón está firme.\n\nVoy a cantar y a tocar:\n\ndespierta, gloria mía;\n\ndespertad, cítara y arpa;\n\ndespertaré a la aurora. R/.\n\nTe daré gracias ante los pueblos, Señor;\n\ntocaré para ti ante las naciones:\n\npor tu bondad, que es más grande que los cielos;\n\npor tu fidelidad, que alcanza las nubes.\n\nElévate sobre el cielo, Dios mío,\n\ny llene la tierra tu gloria. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (15,12-17)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Este es mí mandamiento: que os améis unos a otros como yo os he amado.\n\nNadie tiene amor más grande que el que da la vida por sus amigos.\n\nVosotros sois mis amigos si hacéis lo que yo os mando.\n\nYa no os llamo siervos, porque el siervo no sabe lo que hace su señor: a vosotros os llamo amigos, porque todo lo que he oído a mi Padre os lo he dado a conocer.\n\nNo sois vosotros los que me habéis elegido, soy yo quien os he elegido y os he destinado para que vayáis y deis fruto, y vuestro fruto permanezca.\n\nDe modo que lo que pidáis al Padre en mi nombre os lo dé. Esto os mando: que os améis unos a otros».','\n',char(10)),'2026-05-05 01:21:25','2026-05-05 01:21:25');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(175,'2026-05-09',NULL,'Sábado de la V Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (16,1-10)',replace('EN aquellos días, Pablo llegó a Derbe y luego a Listra. Había alli un discipulo que se llamaba Timoteo, hijo de una judía creyente, pero de padre griego. Los hermanos de Listra y de Iconio daban buenos informes de él. Pablo quiso que fuera con él y, puesto que todos sabían que su padre era griego, por consideración a los judíos de la región, lo tomó y lo hizo circuncidar.\n\nAl pasar por las ciudades, comunicaban las decisiones de los apóstoles y presbíteros de Jerusalén, para que las observasen. Las iglesias se robustecían en la fe y crecían en número de día en día.\n\nAtravesaron Frigia y la región de Galacia, al haberles impedido el Espíritu Santo anunciar la palabra en Asia. Al llegar cerca de Misia, intentaron entrar en Bitinia, pero el Espíritu de Jesús no se lo consintió. Entonces dejaron Misia a un lado y bajaron a Tróade.\n\nAquella noche Pablo tuvo una visión: se le apareció un macedonio, de pie, que le rogaba: «Pasa a Macedonia y ayúdanos».\n\nApenas tuvo la visión, inmediatamente tratamos de salir para Macedonia, seguros de que Dios nos llamaba a predicarles el Evangelio.','\n',char(10)),'Sal 99,1-2.3-5',replace('R/. Aclama al Señor, tierra entera\n\nAclama al Señor, tierra entera,\n\nservid al Señor con alegría,\n\nentrad en su presencia con vítores. R/.\n\nSabed que el Señor es Dios:\n\nque él nos hizo y somos suyos,\n\nsu pueblo y ovejas de su rebaño. R/.\n\nEl Señor es bueno,\n\nsu misericordia es eterna,\n\nsu fidelidad por todas las edades. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (15,18-21)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Si el mundo os odia, sabed que me ha odiado a mí antes que a vosotros.\n\nSi fuerais del mundo, el mundo os amaría como cosa suya, pero como no sois del mundo, sino que yo os he escogido sacándoos del mundo, por eso el mundo os odia.\n\nRecordad lo que os dije: “No es el siervo más que su amo”. Si a mí me han perseguido, también a vosotros os perseguirán; si han guardado mi palabra, también guardarán la vuestra.\n\nY todo eso lo harán con vosotros a causa de mi nombre, porque no conocen al que me envió».','\n',char(10)),'2026-05-05 01:21:31','2026-05-05 01:21:31');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(176,'2026-05-10',NULL,'VI Domingo de Pascua','Lectura del libro de los Hechos de los apóstoles (8,5-8.14-17)','EN aquellos días, Felipe bajó a la ciudad de Samaría y les predicaba a Cristo. El gentío unánimemente escuchaba con atención lo que decía Felipe, porque habían oído hablar de los signos que hacía, y los estaban viendo: de muchos poseídos salían los espíritus inmundos lanzando gritos, y muchos paralíticos y lisiados se curaban. La ciudad se llenó de alegría. Cuando los apóstoles, que estaban en Jerusalén, se enteraron de que Samaría había recibido la palabra de Dios, enviaron a Pedro y a Juan; ellos bajaron hasta allí y oraron por ellos, para que recibieran el Espíritu Santo; pues aún no había bajado sobre ninguno; estaban solo bautizados en el nombre del Señor Jesús. Entonces les imponían las manos y recibían el Espíritu Santo.','Sal 65,1-3',replace('R/. Aclamad al Señor, tierra entera\n\nAclamad al Señor, tierra entera;\n\ntocad en honor de su nombre,\n\ncantad himnos a su gloria.\n\nDecid a Dios: «¡Qué temibles son tus obras!».  R/.\n\nQue se postre ante ti la tierra entera,\n\nque toquen en tu honor,\n\nque toquen para tu nombre.\n\nVenid a ver las obras de Dios,\n\nsus temibles proezas en favor de los hombres.   R/.\n\nTransformó el mar en tierra firme,\n\na pie atravesaron el río.\n\nAlegrémonos en él.\n\nCon su poder gobierna eternamente.   R/.\n\nLos que teméis a Dios, venid a escuchar,\n\nos contaré lo que ha hecho conmigo.\n\nBendito sea Dios, que no rechazó mi súplica\n\nni me retiró su favor.   R/.','\n',char(10)),'Lectura de la primera carta del apóstol san Pedro (3,1.15-18)',replace('QUERIDOS hermanos:\n\nGlorificad a Cristo el Señor en vuestros corazones, dispuestos siempre para dar explicación a todo el que os pida una razón de vuestra esperanza, pero con delicadeza y con respeto, teniendo buena conciencia, para que, cuando os calumnien, queden en ridículo los que atentan contra vuestra buena conducta en Cristo.\n\nPues es mejor sufrir haciendo el bien, si así lo quiere Dios, que sufrir haciendo el mal.\n\nPorque también Cristo sufrió su pasión, de una vez para siempre, por los pecados, el justo por los injustos, para conduciros a Dios. Muerto en la carne pero vivificado en el Espíritu.','\n',char(10)),'Lectura del santo evangelio según san Juan (14,15-21)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Si me amáis, guardaréis mis mandamientos. Y yo le pediré al Padre que os dé otro Paráclito, que esté siempre con vosotros, el Espíritu de la verdad. El mundo no puede recibirlo, porque. no lo ve ni lo conoce; vosotros, en cambio, lo conocéis, porque mora con vosotros y está en vosotros. No os dejaré huérfanos, volveré a vosotros. Dentro de poco el mundo no me verá, pero vosotros me veréis y viviréis, porque yo sigo viviendo. Entonces sabréis que yo estoy en mi Padre, y vosotros en mí y yo en vosotros. El que acepta mis mandamientos y los guarda, ese me ama; y el que me ama será amado por mi Padre, y yo también lo amaré y me manifestaré a él».','\n',char(10)),'2026-05-05 01:21:37','2026-05-05 01:21:37');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(177,'2026-05-11',NULL,'Lunes de la VI Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (16,11-15)',replace('NOS hicimos a la mar en Tróade y pusimos rumbo hacia Samotracia; al día siguiente salimos para Neápolis y de allí para Filipos, primera ciudad del distrito de Macedonia y colonia romana. Allí nos detuvimos unos días.\n\nEl sábado salimos de la ciudad y fuimos a un sitio junto al río, donde pensábamos que había un lugar de oración; nos sentamos y trabamos conversación con las mujeres que habían acudido. Una de ellas, que se llamaba Lidia, natural de Tiatira, vendedora de púrpura, que adoraba al verdadero Dios, estaba escuchando; y el Señor le abrió el corazón para que aceptara lo que decía Pablo.\n\nSe bautizó con toda su familia y nos invitó:\n\n«Si estáis convencidos de que creo en el Señor, venid a hospedaros en mi casa».\n\nY nos obligó a aceptar.','\n',char(10)),'Sal 149,1-2.3-4.5-6',replace('R/. El Señor ama a su pueblo\n\nCantad al Señor un cántico nuevo,\n\nresuene su alabanza en la asamblea de los fieles;\n\nque se alegre Israel por su Creador,\n\nlos hijos de Sión por su Rey. R/.\n\nAlabad su nombre con danzas,\n\ncantadle con tambores y cítaras;\n\nporque el Señor ama a su pueblo\n\ny adorna con la victoria a los humildes. R/.\n\nQue los fieles festejen su gloria\n\ny canten jubilosos en filas:\n\ncon vítores a Dios en la boca.\n\nEs un honor para todos sus fieles. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (15,26–16,4a)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Cuando venga el Paráclito, que os enviaré desde el Padre, el Espíritu de la verdad, que procede del Padre, él dará testimonio de mí; y también vosotros daréis testimonio, porque desde el principio estáis conmigo.\n\nOs he hablado de esto, para que no os escandalicéis. Os excomulgarán de la sinagoga; más aún, llegará incluso una hora cuando el que os dé muerte pensará que da culto a Dios. Y esto lo harán porque no han conocido ni al Padre ni a mí.\n\nOs he hablado de esto para que, cuando llegue la hora, os acordéis de que yo os lo había dicho».','\n',char(10)),'2026-05-05 01:31:07','2026-05-05 01:31:07');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(179,'2026-05-13',NULL,'Miércoles de la VI Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (17,15.22–18,1)',replace('EN aquellos días, los que conducían a Pablo lo llevaron hasta Atenas, y se volvieron con el encargo de que Silas y Timoteo se reuniesen con él cuánto antes.\n\nPablo, de pie en medio del Areópago, dijo:\n\n«Atenienses, veo que sois en todo extremadamente religiosos. Porque, paseando y contemplando vuestros monumentos sagrados, encontré incluso un altar con esta inscripción: “Al Dios desconocido”.\n\nPues eso que veneráis sin conocerlo os lo anuncio yo. “El Dios que hizo el mundo y todo lo que contiene”, siendo como es Señor de cielo y tierra, no habita en templos construidos por manos humanas, ni lo sirven manos humanas, como si necesitara de alguien, él que a todos da la vida y el aliento, y todo.\n\nDe uno solo creó el género humano para que habitara la tierra entera, determinando fijamente los tiempos y las fronteras de los lugares que habían de habitar, con el fin de que lo buscasen a él, a ver si, al menos a tientas, lo encontraban; aunque no está lejos de ninguno de nosotros, pues en él vivimos, nos movemos y existimos; así lo han dicho incluso algunos de vuestros poetas: “Somos estirpe suya”.\n\nPor tanto, si somos estirpe de Dios, no debemos pensar que la divinidad se parezca a imágenes de oro o de plata o de piedra, esculpidas por la destreza y la fantasía de un hombre. Así pues, pasando por alto aquellos tiempos de ignorancia, Dios anuncia ahora en todas partes a todos los humanos que se conviertan. Porque tiene señalado un día en que juzgará el universo con justicia, por medio del hombre a quien él ha designado; y ha dado a todos la garantía de esto, resucitándolo de entre los muertos».\n\nAl oír «resurrección de entre los muertos», unos lo tomaban a broma, otros dijeron:\n\n«De esto te oiremos hablar en otra ocasión».\n\nAsí salió Pablo de en medio de ellos. Algunos se le juntaron y creyeron, entre ellos Dionisio el areopagita, una mujer llamada Dámaris y algunos más con ellos.\n\nDespués de esto, dejó Atenas y se fue a Corinto.','\n',char(10)),'Sal 148,1-2.11-12.13.14',replace('R/. Llenos están el cielo y la tierra de tu gloria\n\nAlabad al Señor en el cielo,\n\nalabad al Señor en lo alto.\n\nAlabadlo todos sus ángeles;\n\nalabadlo todos sus ejércitos. R/.\n\nReyes del orbe y todos los pueblos,\n\npríncipes y jueces del mundo,\n\nlos jóvenes y también las doncellas,\n\nlos ancianos junto con los niños. R/.\n\nAlaben el nombre del Señor,\n\nel único nombre sublime.\n\nSu majestad sobre el cielo y la tierra. R/.\n\nÉl acrece el vigor de su pueblo.\n\nAlabanza de todos sus fieles,\n\nde Israel, su pueblo escogido. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (16,12-15)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Muchas cosas me quedan por deciros, pero no podéis cargar con ellas por ahora; cuando venga él, el Espíritu de la verdad, os guiará hasta la verdad plena. Pues no hablará por cuenta propia, sino que hablará de lo que oye y os comunicará lo que está por venir.\n\nÉl me glorificará, porque recibirá de lo mío y os lo anunciará.\n\nTodo lo que tiene el Padre es mío. Por eso os he dicho que recibirá y tomará de lo mío y os lo anunciará».','\n',char(10)),'2026-05-05 01:31:08','2026-05-05 01:31:08');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(181,'2026-05-12',NULL,'Martes de la VI Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (16,22-34)',replace('EN aquellos días, la plebe de Filipos se amotinó contra Pablo y Silas, y los magistrados ordenaron que les arrancaran y que los azotaran con varas; después de molerlos a palos, los metieron en la cárcel, encargando al carcelero que los vigilara bien; según la orden recibida, él los cogió, los metió en la mazmorra y les sujetó los pies en el cepo.\n\nA eso de media noche, Pablo y Silas oraban cantando himnos a Dios. Los presos los escuchaban. De repente, vino un terremoto tan violento que temblaron los cimientos de la cárcel. Al momento se abrieron todas las puertas, y a todos se les soltaron las cadenas. El carcelero se despertó y, al ver las puertas de la cárcel de par en par, sacó la espada para suicidarse, imaginando que los presos se habían fugado. Pero Pablo lo llamó a gritos, diciendo:\n\n«No te hagas daño alguno, que estamos todos aquí».\n\nEl carcelero pidió una lámpara, saltó dentro, y se echó temblando a los pies de Pablo y Silas; los sacó fuera y les preguntó:\n\n«Señores, ¿qué tengo que hacer para salvarme?»\n\nLe contestaron:\n\n«Cree en el Señor Jesús y te salvarás tú y tu familia».\n\nY le explicaron la palabra del Señor, a él y a todos los de su casa.\n\nA aquellas horas de la noche, el carcelero los tomó consigo, les lavó las heridas, y se bautizó en seguida con todos los suyos; los subió a su casa, les preparó la mesa, y celebraron una fiesta de familia por haber creído en Dios.','\n',char(10)),'Sal 137,1-2',replace('R/. Señor, tu derecha me salva\n\nTe doy gracias, Señor, de todo corazón,\n\nporque escuchaste las palabras de mi boca;\n\ndelante de los ángeles tañeré para ti;\n\nme postraré hacia tu santuario. R/.\n\nDaré gracias a tu nombre\n\npor tu misericordia y tu lealtad.\n\nCuando te invoqué, me escuchaste,\n\nacreciste el valor en mi alma. R/.\n\nTu derecha me salva.\n\nEl Señor completará sus favores conmigo.\n\nSeñor, tu misericordia es eterna,\n\nno abandones la obra de tus manos. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (16,5-11)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«Ahora me voy al que me envió, y ninguno de vosotros me pregunta: “¿Adónde vas?”. Sino que, por haberos dicho esto, la tristeza os ha llenado el corazón. Sin embargo, os digo es la verdad: os conviene que yo me vaya; porque si no me voy, no vendrá a vosotros el Paráclito. En cambio, si me voy, os lo enviaré.\n\nY cuando venga, dejará convicto al mundo acerca de un pecado, de una justicia y de una condena. De un pecado, porque no creen en mí; de una justicia, porque me voy al Padre, y no me veréis; de una condena, porque el príncipe de este mundo está condenado».','\n',char(10)),'2026-05-05 01:31:08','2026-05-05 01:31:08');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(184,'2026-05-14',NULL,'San Matías, apóstol','Lectura del libro de los Hechos de los apóstoles (1,15-17.20-26)',replace('Uno de aquellos días, Pedro se puso en pie en medio de los hermanos y dijo (había reunidas unas ciento veinte personas): «Hermanos, tenía que cumplirse lo que el Espíritu Santo, por boca de David, había predicho en la Escritura acerca de Judas, que hizo de guía a los que arrestaron a Jesús. Era uno de nuestro grupo y compartía el mismo ministerio. En el libro de los Salmos está escrito: «Que su morada quede desierta, y que nadie habite en ella,» y también: «Que su cargo lo ocupe otro.» Hace falta, por tanto, que uno se asocie a nosotros como testigo de la resurrección de Jesús, uno de los que nos acompañaron mientras convivió con nosotros el Señor Jesús, desde que Juan bautizaba, hasta el día de su ascensión.»\n\nPropusieron dos nombres: José, apellidado Barsabá, de sobrenombre Justo, y Matías.\n\nY rezaron así: «Señor, tú penetras el corazón de todos; muéstranos a cuál de los dos has elegido para que, en este ministerio apostólico, ocupe el puesto que dejó Judas para marcharse al suyo propio.» Echaron suertes, le tocó a Matías, y lo asociaron a los once apóstoles.','\n',char(10)),'Sal 112,1-2.3-4.5-6.7-8',replace('R/. El Señor lo sentó con los príncipes de su pueblo\n\nAlabad, siervos del Señor,\n\nalabad el nombre del Señor.\n\nBendito sea el nombre del Señor,\n\nahora y por siempre. R/.\n\nDe la salida del sol hasta su ocaso,\n\nalabado sea el nombre del Señor.\n\nEl Señor se eleva sobre todos los pueblos,\n\nsu gloria sobre los cielos. R/.\n\n¿Quién como el Señor, Dios nuestro,\n\nque se eleva en su trono\n\ny se abaja para mirar\n\nal cielo y a la tierra? R/.\n\nLevanta del polvo al desvalido,\n\nalza de la basura al pobre,\n\npara sentarlo con los príncipes,\n\nlos príncipes de su pueblo. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (15,9-17)','En aquel tiempo, dijo Jesús a sus discípulos: «Como el Padre me ha amado, así os he amado yo; permaneced en mi amor. Si guardáis mis mandamientos, permaneceréis en mi amor; lo mismo que yo he guardado los mandamientos de mi Padre y permanezco en su amor. Os he hablado de esto para que mi alegría esté en vosotros, y vuestra alegría llegue a plenitud. Éste es mi mandamiento: que os améis unos a otros como yo os he amado. Nadie tiene amor más grande que el que da la vida por sus amigos. Vosotros sois mis amigos, si hacéis lo que yo os mando. Ya no os llamo siervos, porque el siervo no sabe lo que hace su señor: a vosotros os llamo amigos, porque todo lo que he oído a mi Padre os lo he dado a conocer. No sois vosotros los que me habéis elegido, soy yo quien os he elegido y os he destinado para que vayáis y deis fruto, y vuestro fruto dure. De modo que lo que pidáis al Padre en mi nombre os lo dé. Esto os mando: que os améis unos a otros.»','2026-05-13 17:46:13','2026-05-13 17:46:13');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(185,'2026-05-15',NULL,'Viernes de la VI Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (18,9-18)',replace('CUANDO estaba Pablo en Corinto, una noche le dijo el Señor en una visión:\n\n«No temas, sigue hablando y no te calles, pues yo estoy contigo, y nadie te pondrá la mano encima para hacerte daño, porque tengo un pueblo numeroso en esta ciudad».\n\nSe quedó, pues, allí un año y medio, enseñando entre ellos la palabra de Dios.\n\nPero, siendo Gallón procónsul de Acaya, los judíos se abalanzaron de común acuerdo contra Pablo y lo condujeron al tribunal diciendo:\n\n«Este induce a la gente a dar a Dios un culto contrario a la ley».\n\nIba Pablo a tomar la palabra, cuando Gallón dijo a los judíos:\n\n«Judíos, si se tratara de un crimen o de un delito grave, sería razón escucharos con paciencia; pero, si discutís de palabras, de nombres y de vuestra ley, vedlo vosotros. Yo no quiero ser juez de esos asuntos».\n\nY les ordenó despejar el tribunal.\n\nEntonces agarraron a Sóstenes, jefe de la sinagoga, y le dieron una paliza delante del tribunal, sin que Galión se preocupara de ello.\n\nPablo se quedó allí todavía bastantes días; luego se despidió de los hermanos y se embarco para Siria con Priscila y Aquila. En Cencreas se había hecho rapar la cabeza, porque había hecho un voto.','\n',char(10)),'Sal 46,2-3,4-5.6-7',replace('R/. Dios es el rey del mundo\n\nPueblos todos, batid palmas,\n\naclamad a Dios con gritos de júbilo;\n\nporque el Señor altísimo es terrible,\n\nemperador de toda la tierra. R/.\n\nÉl nos somete los pueblos\n\ny nos sojuzga las naciones;\n\nél nos escogió por heredad suya:\n\ngloria de Jacob, su amado. R/.\n\nDios asciende entre aclamaciones;\n\nel Señor, al son de trompetas:\n\ntocad para Dios, tocad;\n\ntocad para nuestro Rey, tocad. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (16,20-23a)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«En verdad, en verdad os digo: vosotros lloraréis y os lamentaréis, mientras el mundo estará alegre; vosotros estaréis tristes, pero vuestra tristeza se convertirá en alegría.\n\nLa mujer, cuando va a dar a luz, siente tristeza, porque ha llegado su hora; pero, en cuanto da a luz al niño, ni se acuerda del apuro, por la alegría de que al mundo le ha nacido un hombre.\n\nTambién vosotros ahora sentís tristeza; pero volveré a veros, y se alegrará vuestro corazón, y nadie os quitará vuestra alegría. Ese día no me preguntaréis nada».','\n',char(10)),'2026-05-13 17:46:20','2026-05-13 17:46:20');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(186,'2026-05-16',NULL,'Sábado de la VI Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (18,23-28)',replace('PASADO algún tiempo en Antioquía, Pablo marchó y recorrió sucesivamente Galacia y Frigia, animando a los discípulos.\n\nLlegó a Éfeso un judío llamado Apolo, natural de Alejandría, hombre elocuente y muy versado en las Escrituras. Lo habían instruido en el camino del Señor y exponía con entusiasmo y exactitud lo referente a Jesús, aunque no conocía más que el bautismo de Juan.\n\nApolo, pues, se puso a hablar públicamente en la sinagoga. Cuando lo oyeron Priscila y Áquila, lo tomaron por su cuenta y le explicaron con más detalle el camino de Dios. Decidió pasar a Acaya, y los hermanos lo animaron y escribieron a los discípulos de allí que lo recibieran bien. Una vez llegado, con la ayuda de la gracia, contribuyó mucho al provecho de los creyentes, pues rebatía vigorosamente en público a los judíos, demostrando con la Escritura que Jesús es el Mesías.','\n',char(10)),'Sal 46,2-18-9.10',replace('R/. Dios es el rey del mundo\n\nPueblos todos, batid palmas,\n\naclamad a Dios con gritos de júbilo;\n\nporque el Señor altísimo es terrible,\n\nemperador de toda la tierra. R/.\n\nPorque Dios es el rey del mundo:\n\ntocad con maestría.\n\nDios reina sobre las naciones,\n\nDios se sienta en su trono sagrado. R/.\n\nLos príncipes de los gentiles se reúnen\n\ncon el pueblo del Dios de Abrahán;\n\nporque de Dios son los grandes de la tierra,\n\ny él es excelso. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (16,23b-28)',replace('EN aquel tiempo, dijo Jesús a sus discípulos:\n\n«En verdad, en verdad os digo: si pedís algo al Padre en mi nombre, os lo dará.\n\nHasta ahora no habéis pedido nada en mi nombre; pedid, y recibiréis, para que vuestra alegría sea completa. Os he hablado de esto en comparaciones; viene la hora en que ya no hablaré en comparaciones, sino que os hablaré del Padre claramente.\n\nAquel día pediréis en mi nombre, y no os digo que yo rogaré al Padre por vosotros, pues el Padre mismo os quiere, porque vosotros me queréis y creéis que yo salí de Dios.\n\nSalí del Padre y he venido al mundo, otra vez dejo el mundo y me voy al Padre».','\n',char(10)),'2026-05-13 17:46:26','2026-05-13 17:46:26');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(187,'2026-05-17',NULL,'La Ascensión del Señor','Lectura del libro de los Hechos de los apóstoles (1,1-11)',replace('EN mi primer libro, Teófilo, escribí de todo lo que Jesús hizo y enseno desde el comienzo hasta el día en que fue llevado al cielo, después de haber dado instrucciones a los apóstoles que había escogido, movido por el Espíritu Santo. Se les presentó él mismo después de su pasión, dándoles numerosas pruebas de que estaba vivo, apareciéndoseles durante cuarenta días y hablándoles del reino de Dios.\n\nUna vez que comían juntos, les ordenó que no se alejaran de Jerusalén, sino: «aguardad que se cumpla la promesa del Padre, de la que me habéis oído hablar, porque Juan bautizó con agua, pero vosotros seréis bautizados con Espíritu Santo dentro de no muchos días».\n\nLos que se habían reunido, le preguntaron, diciendo:\n\n«Señor, ¿es ahora cuando vas a restaurar el reino a Israel?».\n\nLes dijo:\n\n«No os toca a vosotros conocer los tiempos o momentos que el Padre ha establecido con su propia autoridad; en cambio, recibiréis la fuerza del Espíritu Santo que va a venir sobre vosotros y seréis mis testigos en Jerusalén, en toda Judea y Samaría y “hasta el confín de la tierra”».\n\nDicho esto, a la vista de ellos, fue elevado al cielo, hasta que una nube se lo quitó de la vista. Cuando miraban fijos al cielo, mientras él se iba marchando, se les presentaron dos hombres vestidos de blanco, que les dijeron:\n\n«Galileos, ¿qué hacéis ahí plantados mirando al cielo? El mismo Jesús que ha sido tomado de entre vosotros y llevado al cielo, volverá como lo habéis visto marcharse al cielo».','\n',char(10)),'Sal 46,2-3.6-7.8-9',replace('R/. Dios asciende entre aclamaciones;\n\nel Señor, al son de trompetas\n\nPueblos todos, batid palmas,\n\naclamad a Dios con gritos de júbilo;\n\nporque el Señor altísimo es terrible,\n\nemperador de toda la tierra.  R/.\n\nDios asciende entre aclamaciones;\n\nel Señor, al son de trompetas:\n\ntocad para Dios, tocad;\n\ntocad para nuestro Rey, tocad.   R/.\n\nPorque Dios es el rey del mundo:\n\ntocad con maestría.\n\nDios reina sobre las naciones,\n\nDios se sienta en su trono sagrado.  R/.','\n',char(10)),'Lectura de la carta del apóstol san Pablo a los Efesios (1,17-23)',replace('HERMANOS:\n\nEl Dios de nuestro Señor Jesucristo, el Padre de la gloria, os dé espíritu de sabiduría y revelación para conocerlo, e ilumine los ojos de vuestro corazón para que comprendáis cuál es la esperanza a la que os llama, cuál la riqueza de gloria que da en herencia a los santos, y cuál la extraordinaria grandeza de su poder en favor de nosotros, los creyentes, según la eficacia de su fuerza poderosa, que desplegó en Cristo, resucitándolo de entre los muertos y sentándolo a su derecha en el cielo, por encima de todo principado, poder, fuerza y dominación, y por encima de todo nombre conocido, no solo en este mundo, sino en el futuro.\n\nY «todo lo puso bajo sus pies», y lo dio a la Iglesia, como Cabeza, sobre todo. Ella es su cuerpo, plenitud del que llena todo en todos.','\n',char(10)),'Conclusión del santo evangelio según san Mateo (28,16-20)',replace('EN aquel tiempo, los once discípulos se fueron a Galilea, al monte que Jesús les había indicado.\n\nAl verlo, ellos se postraron, pero algunos dudaron.\n\nAcercándose a ellos, Jesús les dijo:\n\n«Se me ha dado todo poder en el cielo y en la tierra. Id, pues, y haced discípulos a todos los pueblos, bautizándolos en el nombre del Padre y del Hijo y del Espíritu Santo; enseñándoles a guardar todo lo que os he mandado.\n\nY sabed que yo estoy con vosotros todos los días, hasta el final de los tiempos».','\n',char(10)),'2026-05-13 17:46:32','2026-05-13 17:46:32');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(188,'2026-05-18',NULL,'Lunes de la VII Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (19,1-8)',replace('MIENTRAS Apolo estaba en Corinto, Pablo atravesó la meseta y llegó a Éfeso. Allí encontró unos discípulos y les preguntó:\n\n«¿Recibisteis el Espíritu Santo al aceptar la fe?».\n\nContestaron:\n\n«Ni siquiera hemos oído hablar de un Espíritu Santo».\n\nÉl les dijo:\n\n«Entonces, ¿qué bautismo habéis recibido?».\n\nRespondieron:\n\n«El bautismo de Juan».\n\nPablo les dijo:\n\n«Juan bautizó con un bautismo de conversión, diciendo al pueblo que creyesen en el que iba a venir después de él, es decir, en Jesús».\n\nAl oír esto, se bautizaron en el nombre del Señor Jesús; cuando Pablo les impuso las manos, vino sobre ellos el Espíritu Santo, y se pusieron a hablar en lenguas extrañas y a profetizar. Eran en total unos doce hombres.\n\nPablo fue a la sinagoga y durante tres meses hablaba con toda libertad del reino de Dios, dialogando con ellos y tratando de persuadirlos.','\n',char(10)),'Sal 67,2-3.4-5',replace('R/. Reyes de la tierra, cantad a Dios\n\nSe levanta Dios, y se dispersan sus enemigos,\n\nhuyen de su presencia los que lo odian;\n\ncomo el humo se disipa, se disipan ellos;\n\ncomo se derrite la cera ante el fuego,\n\nasí perecen los impíos ante Dios. R/.\n\nEn cambio, los justos se alegran,\n\ngozan en la presencia de Dios,\n\nrebosando de alegría.\n\nCantad a Dios, tocad a su nombre;\n\nsu nombre es el Señor. R/.\n\nPadre de huérfanos, protector de viudas,\n\nDios vive en su santa morada.\n\nDios prepara casa a los desvalidos,\n\nlibera a los cautivos y los enriquece. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (16,29-33)',replace('EN aquel tiempo, aquel tiempo, los discípulos dijeron a Jesús:\n\n«Ahora sí que hablas claro y no usas comparaciones. Ahora vemos que lo sabes todo y no necesitas que te pregunten; por ello creemos que has salido de Dios».\n\nLes contestó Jesús:\n\n«¿Ahora creéis? Pues mirad: está para llegar la hora, mejor, ya ha llegado, en que os disperséis cada cual por su lado y a mí me dejéis solo. Pero no estoy solo, porque está conmigo el Padre. Os he hablado de esto, para que encontréis la paz en mí. En el mundo tendréis luchas; pero tened valor: yo he vencido al mundo».','\n',char(10)),'2026-05-13 17:46:38','2026-05-13 17:46:38');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(189,'2026-05-19',NULL,'Martes de la VII Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (20,17-27)',replace('En aquellos días, desde Mileto, mandó Pablo llamar a los presbíteros de la Iglesia de Éfeso.\n\nCuando se presentaron, les dijo: «Vosotros sabéis que todo el tiempo que he estado aquí, desde el día que por primera vez puse pie en Asia, he servido al Señor con toda humildad, en las penas y pruebas que me han procurado las maquinaciones de los judíos. Sabéis que no he ahorrado medio alguno, que os he predicado y enseñado en público y en privado, insistiendo a judíos y griegos a que se conviertan a Dios y crean en nuestro Señor Jesús. Y ahora me dirijo a Jerusalén, forzado por el Espíritu. No sé lo que me espera allí, sólo sé que el Espíritu Santo, de ciudad en ciudad, me asegura que me aguardan cárceles y luchas. Pero a mí no me importa la vida; lo que me importa es completar mi carrera, y cumplir el encargo que me dio el Señor Jesús: ser testigo del Evangelio, que es la gracia de Dios. He pasado por aquí predicando el reino, y ahora sé que ninguno de vosotros me volverá a ver. Por eso declaro hoy que no soy responsable de la suerte de nadie: nunca me he reservado nada; os he anunciado enteramente el plan de Dios.»','\n',char(10)),'Sal 67,10-11.20-21',replace('R/. Reyes de la tierra, cantad a Dios\n\nDerramaste en tu heredad,\n\noh Dios, una lluvia copiosa,\n\naliviaste la tierra extenuada\n\ny tu rebaño habitó en la tierra que tu bondad,\n\noh Dios, preparó para los pobres. R/.\n\nBendito el Señor cada día,\n\nDios lleva nuestras cargas,\n\nes nuestra salvación.\n\nNuestro Dios es un Dios que salva,\n\nel Señor Dios nos hace escapar de la muerte. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (17,1-11a)','En aquel tiempo, Jesús, levantando los ojos al cielo, dijo: «Padre, ha llegado la hora, glorifica a tu Hijo, para que tu Hijo te glorifique y, por el poder que tú le has dado sobre toda carne, dé la vida eterna a los que le confiaste. Ésta es la vida eterna: que te conozcan a ti, único Dios verdadero, y a tu enviado, Jesucristo. Yo te he glorificado sobre la tierra, he coronado la obra que me encomendaste. Y ahora, Padre, glorifícame cerca de ti, con la gloria que yo tenía cerca de ti, antes que el mundo existiese. He manifestado tu nombre a los hombres que me diste de en medio del mundo. Tuyos eran, y tú me los diste, y ellos han guardado tu palabra. Ahora han conocido que todo lo que me diste procede de ti, porque yo les he comunicado las palabras que tú me diste, y ellos las han recibido, y han conocido verdaderamente que yo salí de ti, y han creído que tú me has enviado. Te ruego por ellos; no ruego por el mundo, sino por éstos que tú me diste, y son tuyos. Sí, todo lo mío es tuyo, y lo tuyo mío; y en ellos he sido glorificado. Ya no voy a estar en el mundo, pero ellos están en el mundo, mientras yo voy a ti.»','2026-05-13 17:46:44','2026-05-13 17:46:44');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(190,'2026-05-20',NULL,'Miércoles de la VII Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (20,28-38)',replace('En aquellos días, decía Pablo a los presbíteros de la Iglesia de Éfeso: «Tened cuidado de vosotros y del rebaño que el Espíritu Santo os ha encargado guardar, como pastores de la Iglesia de Dios, que él adquirió con su propia sangre. Ya sé que, cuando os deje, se meterán entre vosotros lobos feroces, que no tendrán piedad del rebaño. Incluso algunos de vosotros deformarán la doctrina y arrastrarán a los discípulos. Por eso, estad alerta: acordaos que durante tres años, de día y de noche, no he cesado de aconsejar con lágrimas en los ojos a cada uno en particular. Ahora os dejo en manos de Dios y de su palabra de gracia, que tiene poder para construiros y daros parte en la herencia de los santos. A nadie le he pedido dinero, oro ni ropa. Bien sabéis que estas manos han ganado lo necesario para mí y mis compañeros. Siempre os he enseñado que es nuestro deber trabajar para socorrer a los necesitados, acordándonos de las palabras del Señor Jesús: “Hay más dicha en dar que en recibir.”»\n\nCuando terminó de hablar, se pusieron todos de rodillas, y rezó. Se echaron a llorar y, abrazando a Pablo, lo besaban; lo que más pena les daba era lo que había dicho, que no volverían a verlo. Y lo acompañaron hasta el barco.','\n',char(10)),'Sal 67,29-30.33-35',replace('R/. Reyes de la tierra, cantad a Dios\n\nOh Dios, despliega tu poder,\n\ntu poder, oh Dios, que actúa en favor nuestro.\n\nA tu templo de Jerusalén\n\ntraigan los reyes su tributo. R/.\n\nReyes de la tierra, cantad a Dios,\n\ntocad para el Señor,\n\nque avanza por los cielos,\n\nlos cielos antiquísimos,\n\nque lanza su voz, su voz poderosa:\n\n«Reconoced el poder de Dios.» R/.\n\nSobre Israel resplandece su majestad,\n\ny su poder, sobre las nubes.\n\n¡Dios sea bendito! R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (17,11b-19)','En aquel tiempo, Jesús, levantando los ojos al cielo, oró, diciendo: «Padre santo, guárdalos en tu nombre, a los que me has dado, para que sean uno, como nosotros. Cuando estaba con ellos, yo guardaba en tu nombre a los que me diste, y los custodiaba, y ninguno se perdió, sino el hijo de la perdición, para que se cumpliera la Escritura. Ahora voy a ti, y digo esto en el mundo para que ellos mismos tengan mi alegría cumplida. Yo les he dado tu palabra, y el mundo los ha odiado porque no son del mundo, como tampoco yo soy del mundo. No ruego que los retires del mundo, sino que los guardes del mal. No son del mundo, como tampoco yo soy del mundo. Conságralos en la verdad; tu palabra es verdad. Como tú me enviaste al mundo, así los envío yo también al mundo. Y por ellos me consagro yo, para que también se consagren ellos en la verdad.»','2026-05-13 17:46:50','2026-05-13 17:46:50');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(191,'2026-05-23',NULL,'Sábado de la VII Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (28,16-20.30-31)',replace('Cuando llegamos a Roma, le permitieron a Pablo vivir por su cuenta en una casa, con un soldado que lo vigilase.\n\nTres días después, convocó a los judíos principales; cuando se reunieron, les dijo: «Hermanos, estoy aquí preso sin haber hecho nada contra el pueblo ni las tradiciones de nuestros padres; en Jerusalén me entregaron a los romanos. Me interrogaron y querían ponerme en libertad, porque no encontraban nada que mereciera la muerte; pero, como los judíos se oponían, tuve que apelar al César; aunque no es que tenga intención de acusar a mi pueblo. Por este motivo he querido veros y hablar con vosotros; pues por la esperanza de Israel llevo encima estas cadenas.» Vivió allí dos años enteros a su propia costa, recibiendo a todos los que acudían, predicándoles el reino de Dios y enseñando lo que se refiere al Señor Jesucristo con toda libertad, sin estorbos.','\n',char(10)),'Sal 10,4.5.7',replace('R/. Los buenos verán tu rostro, Señor\n\nEl Señor está en su templo santo,\n\nel Señor tiene su trono en el cielo;\n\nsus ojos están observando,\n\nsus pupilas examinan a los hombres. R/.\n\nEl Señor examina a inocentes y culpables,\n\ny al que ama la violencia él lo odia.\n\nPorque el Señor es justo y ama la justicia:\n\nlos buenos verán su rostro. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (21,20-25)',replace('En aquel tiempo, Pedro, volviéndose, vio que los seguía el discípulo a quien Jesús tanto amaba, el mismo que en la cena se había apoyado en su pecho y le había preguntado: «Señor, ¿quién es el que te va a entregar?»\n\nAl verlo, Pedro dice a Jesús: «Señor, y éste ¿qué?»\n\nJesús le contesta: «Si quiero que se quede hasta que yo venga, ¿a ti qué? Tú sígueme.»\n\nEntonces se empezó a correr entre los hermanos el rumor de que ese discípulo no moriría. Pero no le dijo Jesús que no moriría, sino: «Si quiero que se quede hasta que yo venga, ¿a ti qué?» Éste es el discípulo que da testimonio de todo esto y lo ha escrito; y nosotros sabemos que su testimonio es verdadero. Muchas otras cosas hizo Jesús. Si se escribieran una por una, pienso que los libros no cabrían ni en todo el mundo.','\n',char(10)),'2026-05-13 17:47:30','2026-05-13 17:47:30');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(192,'2026-05-21',NULL,'Jueves de la VII Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (22,30;23,6-11)',replace('En aquellos días, queriendo el tribuno poner en claro de qué acusaban a Pablo los judíos, mandó desatarlo, ordenó que se reunieran los sumos sacerdotes y el Sanedrín en pleno, bajó a Pablo y lo presentó ante ellos.\n\nPablo sabía que una parte del Sanedrín eran fariseos y otra saduceos y gritó: «Hermanos, yo soy fariseo, hijo de fariseo, y me juzgan porque espero la resurrección de los muertos.»\n\nApenas dijo esto, se produjo un altercado entre fariseos y saduceos, y la asamblea quedó dividida. (Los saduceos sostienen que no hay resurrección, ni ángeles, ni espíritus, mientras que los fariseos admiten todo esto.) Se armó un griterío, y algunos escribas del partido fariseo se pusieron en pie, porfiando: «No encontramos ningún delito en este hombre; ¿y si le ha hablado un espíritu o un ángel?»\n\nEl altercado arreciaba, y el tribuno, temiendo que hicieran pedazos a Pablo, mandó bajar a la guarnición para sacarlo de allí y llevárselo al cuartel.\n\nLa noche siguiente, el Señor se le presentó y le dijo: «¡Ánimo! Lo mismo que has dado testimonio a favor mío en Jerusalén tienes que darlo en Roma.»','\n',char(10)),'Sal 15',replace('R/. Protégeme, Dios mío, que me refugio en ti\n\nProtégeme, Dios mío, que me refugio en ti;\n\nyo digo al Señor: «Tú eres mi bien.»\n\nEl Señor es el lote de mi heredad y mi copa;\n\nmi suerte está en tu mano. R/.\n\nBendeciré al Señor, que me aconseja,\n\nhasta de noche me instruye internamente.\n\nTengo siempre presente al Señor,\n\ncon él a mi derecha no vacilaré. R/.\n\nPor eso se me alegra el corazón,\n\nse gozan mis entrañas,\n\ny mi carne descansa serena.\n\nPorque no me entregarás a la muerte,\n\nni dejarás a tu fiel conocer la corrupción. R/.\n\nMe enseñarás el sendero de la vida,\n\nme saciarás de gozo en tu presencia,\n\nde alegría perpetua a tu derecha. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (17,20-26)','En aquel tiempo, Jesús, levantando los ojos al cielo, oró, diciendo: «Padre santo, no sólo por ellos ruego, sino también por los que crean en mí por la palabra de ellos, para que todos sean uno, como tú, Padre, en mí, y yo en ti, que ellos también lo sean en nosotros, para que el mundo crea que tú me has enviado. También les di a ellos la gloria que me diste, para que sean uno, como nosotros somos uno; yo en ellos, y tú en mí, para que sean completamente uno, de modo que el mundo sepa que tú me has enviado y los has amado como me has amado a mí. Padre, éste es mi deseo: que los que me confiaste estén conmigo donde yo estoy y contemplen mi gloria, la que me diste, porque me amabas, antes de la fundación del mundo. Padre justo, si el mundo no te ha conocido, yo te he conocido, y éstos han conocido que tú me enviaste. Les he dado a conocer y les daré a conocer tu nombre, para que el amor que me tenías esté con ellos, como también yo estoy con ellos.»','2026-05-13 17:47:31','2026-05-13 17:47:31');
INSERT INTO "cached_readings" ("id","reading_date","mass_type","liturgical_day","first_reading","first_reading_text","psalm","psalm_text","second_reading","second_reading_text","gospel","gospel_text","created_at","updated_at") VALUES(194,'2026-05-22',NULL,'Viernes de la VII Semana de Pascua','Lectura del libro de los Hechos de los apóstoles (25,13-21)',replace('En aquellos días, el rey Agripa llegó a Cesarea con Berenice para cumplimentar a Festo, y se entretuvieron allí bastantes días.\n\nFesto expuso al rey el caso de Pablo, diciéndole: «Tengo aquí un preso, que ha dejado Félix; cuando fui a Jerusalén, los sumos sacerdotes y los ancianos judíos presentaron acusación contra él, pidiendo su condena. Les respondí que no es costumbre romana ceder a un hombre por las buenas; primero el acusado tiene que carearse con sus acusadores, para que tenga ocasión de defenderse. Vinieron conmigo a Cesarea, y yo, sin dar largas al asunto, al día siguiente me senté en el tribunal y mandé traer a este hombre. Pero, cuando los acusadores tomaron la palabra, no adujeron ningún cargo grave de los que yo suponía; se trataba sólo de ciertas discusiones acerca de su religión y de un difunto llamado Jesús, que Pablo sostiene que está vivo. Yo, perdido en semejante discusión, le pregunté si quería ir a Jerusalén a que lo juzgase allí. Pero, como Pablo ha apelado, pidiendo que lo deje en la cárcel, para que decida su majestad, he dado orden de tenerlo en prisión hasta que pueda remitirlo al César.»','\n',char(10)),'Sal 10,4-7',replace('R/. El Señor puso en el cielo su trono\n\nBendice, alma mía, al Señor,\n\ny todo mi ser a su santo nombre.\n\nBendice, alma mía, al Señor,\n\ny no olvides sus beneficios. R/.\n\nComo se levanta el cielo sobre la tierra,\n\nse levanta su bondad sobre sus fieles;\n\ncomo dista el oriente del ocaso,\n\nasí aleja de nosotros nuestros delitos. R/.\n\nEl Señor puso en el cielo su trono,\n\nsu soberanía gobierna el universo.\n\nBendecid al Señor, ángeles suyos,\n\npoderosos ejecutores de sus órdenes. R/.','\n',char(10)),NULL,NULL,'Lectura del santo evangelio según san Juan (21,15-19)',replace('Habiéndose aparecido Jesús a sus discípulos, después de comer con ellos, dice a Simón Pedro:\n\n«Simón, hijo de Juan, ¿me amas más que éstos?»\n\nÉl le contestó: «Sí, Señor, tú sabes que te quiero.»\n\nJesús le dice: «Apacienta mis corderos.»\n\nPor segunda vez le pregunta: «Simón, hijo de Juan, ¿me amas?»\n\nÉl le contesta: «Sí, Señor, tú sabes que te quiero.»\n\nÉl le dice: «Pastorea mis ovejas.»\n\nPor tercera vez le pregunta: «Simón, hijo de Juan, ¿me quieres?»\n\nSe entristeció Pedro de que le preguntara por tercera vez si lo quería y le contestó: «Señor, tú conoces todo, tú sabes que te quiero.»\n\nJesús le dice: «Apacienta mis ovejas. Te lo aseguro: cuando eras joven, tú mismo te ceñías e ibas adonde querías; pero, cuando seas viejo, extenderás las manos, otro te ceñirá y te llevará adonde no quieras.»\n\nEsto dijo aludiendo a la muerte con que iba a dar gloria a Dios.\n\nDicho esto, añadió: «Sígueme.»','\n',char(10)),'2026-05-13 17:47:31','2026-05-13 17:47:31');
